INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别号", "is_correct": true, "explanation": "别号：本名和字以外另取的称号，与“齐白石的……很多，其中一个叫借山翁”相合。"}, {"text": "籍贯", "is_correct": false, "explanation": "搭配：籍贯指出生地，不说籍贯很多。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄是数字，不能说年龄很多、其中一个叫借山翁。"}, {"text": "职业", "is_correct": false, "explanation": "语义：职业指工作，借山翁是称号，不是职业。"}], "explanations": {"别号": "别号：本名和字以外另取的称号，与“齐白石的……很多，其中一个叫借山翁”相合。", "籍贯": "搭配：籍贯指出生地，不说籍贯很多。", "年龄": "搭配：年龄是数字，不能说年龄很多、其中一个叫借山翁。", "职业": "语义：职业指工作，借山翁是称号，不是职业。"}, "sentence_index": 6, "correct_answer": "别号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的别号一共有两个，都在户口本上登记过。", "explanation": "语义：别号是另取的称号，不是登记在户口本上的正式姓名；这里混同了〈正式姓名〉。"}, {"text": "这本书的别号是《东坡集》。", "explanation": "搭配：别号指人的称号，不用于书；书的另一个名称应说〈别名〉。"}, {"text": "他名叫陈云，别号也叫陈云，大家分不清。", "explanation": "语义：别号是本名以外另取的称号，不能与本名相同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位书法家有三只别号，很有名。", "corrected_sentence": "这位书法家有三个别号，很有名。", "error_description": "量词错误：别号要用量词“个”，不说“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给自己取了一个的别号，叫“醉翁”。", "corrected_sentence": "他给自己取了一个别号，叫“醉翁”。", "error_description": "结构错误：数量词“一个”修饰名词时不加“的”，应说“一个别号”，不说“一个的别号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
