INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你长大以后会过上怎样的日子。", "primary_collocate": null, "pronunciation": "qián tú", "ipa": "tɕʰjɛn˧˥ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "好好学习，你以后的前途才会好。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你长大以后的前途由你自己决定。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸希望孩子长大后有个好前途。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈担心我长大以后的前途。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他又努力又聪明，我相信他以后会有好前途。", "target_word": "前途", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子聪明又努力，前途一定很好。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了孩子的前途，他们搬到了大城市。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说你选什么专业，会影响你以后的前途。", "target_word": "前途", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己的前途一片灰暗，很难过。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明还小，他的前途要靠自己一步一步走出来。", "target_word": "前途", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个人长大以后的生活与出路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前途", "is_correct": true, "explanation": "正确：前途指一个人长大以后的生活与出路，与“你以后的……才会好”的语境相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高不随学习而改善，不能说“你以后的身高才会好”。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量与学习没有关系，“你以后的饭量才会好”不合语境。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票不能作人的好坏评价的主语，与人的未来无关。"}], "explanations": {"前途": "正确：前途指一个人长大以后的生活与出路，与“你以后的……才会好”的语境相符。", "身高": "体貌：身高不随学习而改善，不能说“你以后的身高才会好”。", "饭量": "语义：饭量与学习没有关系，“你以后的饭量才会好”不合语境。", "门票": "语义：门票不能作人的好坏评价的主语，与人的未来无关。"}, "sentence_index": 0, "correct_answer": "前途"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个蛋糕的前途很甜。", "explanation": "这里应该用〈味道〉。前途指人的未来与出路，不能用“甜”形容蛋糕。"}, {"text": "我的前途吃了三碗饭。", "explanation": "这里应该用〈饭量〉。前途指人的未来与出路，不能用来说吃了多少饭。"}, {"text": "我的前途提高了五厘米。", "explanation": "这里应该用〈身高〉。前途指人的未来与出路，不能用厘米来计量，也不能说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前途", "is_correct": true, "explanation": "正确：前途指孩子长大以后的生活与出路，与“为了孩子的……”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能作为“搬到大城市”的理由，与语境冲突。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能作为搬家的原因，与“为了孩子的”不搭。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码是鞋的尺寸，不能作为“搬到大城市”的目的。"}], "explanations": {"前途": "正确：前途指孩子长大以后的生活与出路，与“为了孩子的……”的语境相符。", "体重": "语义：体重不能作为“搬到大城市”的理由，与语境冲突。", "手机": "语义：手机不能作为搬家的原因，与“为了孩子的”不搭。", "鞋码": "语义：鞋码是鞋的尺寸，不能作为“搬到大城市”的目的。"}, "sentence_index": 6, "correct_answer": "前途"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的前途要靠自己一步一步洗干净。", "explanation": "这里应该用〈衣服〉。洗干净用于衣物等实物，前途指人的未来与出路，不能这样说。"}, {"text": "他的前途要靠自己一步一步吃下去。", "explanation": "这里应该用〈饭菜〉。吃下去用于饭菜，前途指人的未来与出路，不能这样说。"}, {"text": "他的前途每天都要睡八个小时。", "explanation": "这里应该用〈他〉。前途不能睡觉，“睡八个小时”的主语须是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校能给孩子一条好前途。", "corrected_sentence": "这所学校能给孩子一个好前途。", "error_description": "错误：“一条好前途”。正确：“一个好前途”。“条”用于细长的物体，“前途”是抽象名词，应使用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们希望女儿将来有一条好前途。", "corrected_sentence": "他们希望女儿将来有一个好前途。", "error_description": "错误：“一条好前途”。正确：“一个好前途”。“前途”是抽象名词，量词用“个”，不用表示细长物体的“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
