INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前面的道路；比喻事物未来的发展景象。", "primary_collocate": null, "pronunciation": "qián tú", "ipa": "tɕʰjɛn˧˥ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司很有前途。", "target_word": "前途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个行业的前途很好。", "target_word": "前途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想为国家的前途做点事。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说公司的前途一片光明。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看好这个新技术的前途。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为市场变小，这个行业没有前途了。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该为国家的前途努力学习。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城市的前途取决于新建的铁路。", "target_word": "前途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司虽然现在很小，但是前途不可限量。", "target_word": "前途", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，新能源汽车的前途非常广阔。", "target_word": "前途", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物（公司、行业、国家、技术等）未来的发展前景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前途", "is_correct": true, "explanation": "正确：前途指事物未来的发展前景，与“很有”搭配，符合公司的语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只用于人或动物的体形，不能说公司有身材。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高只用于人或动物，公司不能说“很有身高”。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指人吃东西的多少，与公司的发展无关。"}], "explanations": {"前途": "正确：前途指事物未来的发展前景，与“很有”搭配，符合公司的语境。", "身材": "体貌：身材只用于人或动物的体形，不能说公司有身材。", "身高": "体貌：身高只用于人或动物，公司不能说“很有身高”。", "饭量": "语义：饭量指人吃东西的多少，与公司的发展无关。"}, "sentence_index": 0, "correct_answer": "前途"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片的前途很美。", "explanation": "这里应该用〈前景〉。照片的前景指画面前方的部分，前途只指事物未来的发展，不能用来形容画面。"}, {"text": "这瓶饮料的前途很甜。", "explanation": "这里应该用〈味道〉。前途指事物未来的发展，不能用“甜”形容饮料。"}, {"text": "这个行业的前途增加了三米。", "explanation": "这里应该用〈长度〉。前途指发展前景，不能说“增加了三米”，长度才能用米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前途", "is_correct": true, "explanation": "正确：前途指国家未来的发展前景，与“为国家的……努力学习”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体数值，不能作为“为国家的”努力的对象。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高与国家的发展无关，“为国家的身高”不能成立。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：“国家的作息”不成立，国家不说作息，搭配不当。"}], "explanations": {"前途": "正确：前途指国家未来的发展前景，与“为国家的……努力学习”的语境相符。", "体重": "语义：体重是人的身体数值，不能作为“为国家的”努力的对象。", "身高": "语义：身高与国家的发展无关，“为国家的身高”不能成立。", "作息": "搭配：“国家的作息”不成立，国家不说作息，搭配不当。"}, "sentence_index": 6, "correct_answer": "前途"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新能源汽车的前途非常便宜。", "explanation": "这里应该用〈价格〉。前途指事物未来的发展，不能用“便宜”来形容。"}, {"text": "新能源汽车的前途非常硬。", "explanation": "这里应该用〈硬度〉。前途指事物未来的发展，不能用“硬”形容。"}, {"text": "新能源汽车的前途非常重。", "explanation": "这里应该用〈重量〉。前途不能用“重”形容，重量才能用“重”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有一条光明的前途。", "corrected_sentence": "这家公司有光明的前途。", "error_description": "错误：“一条光明的前途”。正确：“光明的前途”。“条”用于细长的东西，比喻发展前景的“前途”不用“条”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因为市场变大，这个行业很前途。", "corrected_sentence": "因为市场变大，这个行业很有前途。", "error_description": "错误：“很前途”。正确：“很有前途”。“前途”是名词，不能直接受“很”修饰，要说“很有前途”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
