INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96317, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情想好，再一件一件地安排好。", "primary_collocate": null, "pronunciation": "qū chǔ", "ipa": "tɕʰy⁵⁵ ʈʂʰu²¹⁴", "syllable_count": 2, "sentences": [{"text": "他先想好步骤，再把家务一件件区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把年底的工作区处得井井有条。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些事务繁杂，须先加以区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会区处家务，从不手忙脚乱。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父亲临走前，把家里的事都区处好了。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "散会前，拟先将明日事务逐一区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情很多，要想好顺序再慢慢区处。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他区处事情有条理，同事都很佩服。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母亲病倒后，大哥把家务区处得很周到。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，她把工作和家事都区处妥当。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "区处了", "label": "体标"}], "register": "书面", "sense_fingerprint": "先想好再逐件安排事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区处", "is_correct": true, "explanation": "“区处”指分别把事情想好、逐件安排，此处与“先想好步骤、再一件件”相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“先想好步骤、再一件件安排”的意思相反。"}, {"text": "躲", "is_correct": false, "explanation": "搭配：“躲”不能带“家务”作宾语，“把家务一件件躲”不成搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与家务无关，“把家务一件件唱”句意不通。"}], "explanations": {"区处": "“区处”指分别把事情想好、逐件安排，此处与“先想好步骤、再一件件”相符。", "扔": "语义：“扔”是丢弃，与“先想好步骤、再一件件安排”的意思相反。", "躲": "搭配：“躲”不能带“家务”作宾语，“把家务一件件躲”不成搭配。", "唱": "语义：“唱”与家务无关，“把家务一件件唱”句意不通。"}, "sentence_index": 0, "correct_answer": "区处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她区处了一碗热汤，喝得满头大汗。", "explanation": "这里应该用〈喝〉。“区处”指安排、处理事务，不能用于饮食；喝汤要用〈喝〉。"}, {"text": "她把房间区处得干干净净。", "explanation": "这里应该用〈打扫〉。“区处”不指清扫空间，把房间弄干净要用〈打扫〉。"}, {"text": "她细心区处生病的母亲。", "explanation": "这里应该用〈照顾〉。“区处”不用于照料人，照顾病人要用〈照顾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区处", "is_correct": true, "explanation": "“区处”指逐件安排事务，与“想好顺序再慢慢”的句意相符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉与安排事务无关，“再慢慢睡”句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“事情”作宾语，“慢慢吃事情”不成搭配。"}, {"text": "站", "is_correct": false, "explanation": "语义：站立与处理事务无关，“再慢慢站”句意不通。"}], "explanations": {"区处": "“区处”指逐件安排事务，与“想好顺序再慢慢”的句意相符。", "睡": "语义：睡觉与安排事务无关，“再慢慢睡”句意不通。", "吃": "搭配：“吃”不能带“事情”作宾语，“慢慢吃事情”不成搭配。", "站": "语义：站立与处理事务无关，“再慢慢站”句意不通。"}, "sentence_index": 6, "correct_answer": "区处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈区处了一锅粥，香气飘满了屋子。", "explanation": "这里应该用〈煮〉。“区处”用于事务，不能用来指烹饪，煮粥要用〈煮〉。"}, {"text": "师傅区处了一块木料，刨得光滑平整。", "explanation": "这里应该用〈刨〉。“区处”指安排事务，不能用于加工木料；刨平木料要用〈刨〉。"}, {"text": "他把脏衣服区处干净了。", "explanation": "这里应该用〈洗〉。“区处”不指清洗衣物，把衣服洗干净要用〈洗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把家里的事都区处了妥当。", "corrected_sentence": "她把家里的事都区处妥当。", "error_description": "错误：“区处了妥当”；正确：“区处妥当”。“了”不能插在动词“区处”和补语“妥当”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲把家里的账都区处清楚着。", "corrected_sentence": "父亲把家里的账都区处清楚了。", "error_description": "错误：“区处清楚着”；正确：“区处清楚了”。动作已经完成，表示完成要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
