INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96321, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很久很久以前，还没有现代人的时候就有的人。", "primary_collocate": null, "pronunciation": "yuán rén", "ipa": "ɥɛn˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "很久很久以前，原人住在树上。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人不知道怎么种地。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的原人穿着兽皮。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“原人为什么不穿衣服？”", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人每天都要去找吃的。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是一群原人。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人怕冷，所以要点火。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人一起用石头打猎。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到了原人的画。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候还没有城市，只有原人。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "远古时代、现代人出现之前就生活着的人，常见于故事和讲述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原人", "is_correct": true, "explanation": "原人：远古时代还没有现代人出现时就生活着的人，与「很久很久以前」和「住在树上」相符。"}, {"text": "现代人", "is_correct": false, "explanation": "语义：「现代人」指当今的人，与「很久很久以前」矛盾。"}, {"text": "机器人", "is_correct": false, "explanation": "搭配：「住在树上」的主语应是能够生活在树上的生物，机器人不能住在树上。"}, {"text": "游客", "is_correct": false, "explanation": "语义：「游客」是暂时到访的人，不会长期住在树上。"}], "explanations": {"原人": "原人：远古时代还没有现代人出现时就生活着的人，与「很久很久以前」和「住在树上」相符。", "现代人": "语义：「现代人」指当今的人，与「很久很久以前」矛盾。", "机器人": "搭配：「住在树上」的主语应是能够生活在树上的生物，机器人不能住在树上。", "游客": "语义：「游客」是暂时到访的人，不会长期住在树上。"}, "sentence_index": 0, "correct_answer": "原人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆里陈列着一支原人用过的毛笔。", "explanation": "这里应该用〈古人〉。原人指远古时代、现代人出现之前的人，不能指使用毛笔的古代人。"}, {"text": "我们的原人在汉朝就学会了织布。", "explanation": "这里应该用〈祖先〉。原人指远古时代的人类，不指汉朝时期自己的先辈。"}, {"text": "台湾的原人有自己的语言和节日。", "explanation": "这里应该用〈原住民〉。原人指远古时代的人类，不指现在生活在台湾的原住民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原人", "is_correct": true, "explanation": "原人：远古时代的人，怕冷、需要用火取暖，与句意相符。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人没有身体感觉，不会怕冷，句子说不通。"}, {"text": "动物", "is_correct": false, "explanation": "搭配：「点火」需要有意识地使用火的主体，动物一般不会点火，与「所以要点火」不搭。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物没有怕冷的感觉，也不会点火取暖。"}], "explanations": {"原人": "原人：远古时代的人，怕冷、需要用火取暖，与句意相符。", "机器人": "语义：机器人没有身体感觉，不会怕冷，句子说不通。", "动物": "搭配：「点火」需要有意识地使用火的主体，动物一般不会点火，与「所以要点火」不搭。", "植物": "语义：植物没有怕冷的感觉，也不会点火取暖。"}, "sentence_index": 6, "correct_answer": "原人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "森林里的原人在用电脑查资料。", "explanation": "这里应该用〈现代人〉。原人指现代人出现之前的人，不能指使用电脑的人。"}, {"text": "原人们在教堂里举行了婚礼。", "explanation": "这里应该用〈现代人〉。原人指远古时代的人类，不能用来指在教堂结婚的人。"}, {"text": "那位原人是一个很有名的网络作家。", "explanation": "这里应该用〈现代人〉。原人只指远古时代的人类，不能指现代的网络作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只原人住在山洞里。", "corrected_sentence": "一群原人住在山洞里。", "error_description": "量词错误：“原人”指人，应用“群”或“个”计量，“只”多用于动物。错误形式：一只原人；正确形式：一群原人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条原人在河边捕鱼。", "corrected_sentence": "那群原人在河边捕鱼。", "error_description": "量词错误：“条”多用于细长的东西，这里不宜用来数“原人”。错误形式：那条原人；正确形式：那群原人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
