INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人类演化早期的人，即原始人类。", "primary_collocate": null, "pronunciation": "yuán rén", "ipa": "ɥɛn˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "原人生活在很久以前的森林里。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一个原人的头骨。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人会用石头做工具。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在山洞里发现了原人用过的火堆。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人没有房子，住在山洞里。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里画着原人打猎的样子。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原人是怎样学会用火的？", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和现代人比，原人的脑子小一些。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些石头工具是原人留下来的。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了原人的生活。", "target_word": "原人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "人类演化早期的原始人类，多见于科普和考古语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原人", "is_correct": true, "explanation": "原人：人类演化早期的原始人类，与“很久以前的森林里”相合。"}, {"text": "现代人", "is_correct": false, "explanation": "语义：现代人生活在近代，与“很久以前”相矛盾。"}, {"text": "机器人", "is_correct": false, "explanation": "搭配：“生活”不用于机器人，这里不能说机器人生活在森林里。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生指在校学习的人，与“很久以前的森林里”的语境不符。"}], "explanations": {"原人": "原人：人类演化早期的原始人类，与“很久以前的森林里”相合。", "现代人": "语义：现代人生活在近代，与“很久以前”相矛盾。", "机器人": "搭配：“生活”不用于机器人，这里不能说机器人生活在森林里。", "学生": "语义：学生指在校学习的人，与“很久以前的森林里”的语境不符。"}, "sentence_index": 0, "correct_answer": "原人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原人设计的手机很受欢迎，大家都买了。", "explanation": "语义：原人指远古的原始人类，不可能设计现代产品；这里误当作〈设计师〉的意思。"}, {"text": "原人每天坐地铁去公司上班。", "explanation": "语义：原人指远古的原始人类，那时没有地铁和公司；这里误当作〈上班族〉来用。"}, {"text": "这只猫是原人，它很聪明。", "explanation": "语义：原人指人类演化早期的人，不指动物；这里误当作〈动物〉来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原人", "is_correct": true, "explanation": "原人：人类演化早期的原始人类，多指学会用火的远古人类。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“学会用火”的主语应是有学习能力的生物，不说石头学会用火。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能学会用火，与“怎样学会用火”的语境不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车没有学习能力，不说汽车学会用火。"}], "explanations": {"原人": "原人：人类演化早期的原始人类，多指学会用火的远古人类。", "石头": "搭配：“学会用火”的主语应是有学习能力的生物，不说石头学会用火。", "电脑": "语义：电脑不能学会用火，与“怎样学会用火”的语境不符。", "汽车": "搭配：汽车没有学习能力，不说汽车学会用火。"}, "sentence_index": 6, "correct_answer": "原人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爷爷是原人，每天都去公司上班。", "explanation": "语义：原人指远古的人类，不能用来称呼现代的人；这里误当作〈老年人〉来用。"}, {"text": "学校里的原人很多，老师教他们读书。", "explanation": "语义：原人指远古的原始人类，还没有学校；这里误当作〈学生〉来用。"}, {"text": "我给原人打了个电话，约他明天吃饭。", "explanation": "语义：原人指远古的原始人类，不能打电话约见；这里误当作〈朋友〉来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在展览里见过一只原人的模型。", "corrected_sentence": "我们在展览里见过一个原人的模型。", "error_description": "量词错误：这里的模型表现的是“原人”，原人是人，量词应用“个”；“只”用于动物，不能说“一只原人的模型”。错误形式：一只原人的模型；正确形式：一个原人的模型。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只原人白天打猎，晚上躲在山洞里。", "corrected_sentence": "一个原人白天打猎，晚上躲在山洞里。", "error_description": "量词错误：“原人”指人，量词应用“个”（或“位”），“只”用于动物，不能说“一只原人”。错误形式：一只原人；正确形式：一个原人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
