INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "某件事太难过了，自己再也忍不下去。", "primary_collocate": null, "pronunciation": "shòu bu liǎo", "ipa": "ʂoʊ̯˥˩ pu liɑʊ̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "听到那个坏消息，她难过得受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友要搬走了，我心里难受，真的受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶住院了，妈妈整天哭，我看着受不了。", "target_word": "受不了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一想到离开家人，就难过得受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到小狗死了，女儿伤心得受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听她哭得那么伤心，我也受不了了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老朋友去世的消息，让他难过得受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人在国外过年，我孤单得受不了。", "target_word": "受不了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说分手以后，每天都难过得受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了，他心里难过得受不了，一个人躲在房间里不肯出来。", "target_word": "受不了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受得了", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "心里太难过，情绪上再也忍不下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：难过到再也忍不下去，与“难过得”引出的结果相合。"}, {"text": "高兴得很", "is_correct": false, "explanation": "语义：“高兴”与“坏消息”的情绪相反，不能接在“难过得”后面。"}, {"text": "拍手", "is_correct": false, "explanation": "搭配：“难过得”后接的应是心理或身体状态，不接“拍手”这类动作。"}, {"text": "受得了", "is_correct": false, "explanation": "语义：“受得了”表示能忍受，与“难过得”的程度相矛盾。"}], "explanations": {"受不了": "受不了：难过到再也忍不下去，与“难过得”引出的结果相合。", "高兴得很": "语义：“高兴”与“坏消息”的情绪相反，不能接在“难过得”后面。", "拍手": "搭配：“难过得”后接的应是心理或身体状态，不接“拍手”这类动作。", "受得了": "语义：“受得了”表示能忍受，与“难过得”的程度相矛盾。"}, "sentence_index": 0, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试得了满分，他受不了地拍手叫好，笑个不停。", "explanation": "这里应该用〈高兴〉。“受不了”表示承受不住，不能表示兴高采烈地拍手叫好；这种欢快的情绪应说“高兴”。"}, {"text": "他被欺负了好几年，只能默默受不了，从不抱怨。", "explanation": "这里应该用〈忍耐〉。“受不了”表示承受不住、忍不下去，不能表示长期压住不说，应说“忍耐”。"}, {"text": "他咬牙受不了，一声不吭地走完了全程。", "explanation": "这里应该用〈忍耐〉。“受不了”表示承受不住、忍不下去，不能表示咬牙坚持，与“走完全程”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：难过得忍不下去，与“让他难过得”引出的结果相合。"}, {"text": "笑个不停", "is_correct": false, "explanation": "语义：“笑个不停”与“老朋友去世”的悲痛情绪相反，不符合句意。"}, {"text": "唱起歌来", "is_correct": false, "explanation": "搭配：“难过得”后接的是伤心的状态，“唱起歌来”是欢快的活动，两者不搭配。"}, {"text": "跳起舞来", "is_correct": false, "explanation": "语义：“跳舞”与老朋友去世的情境相悖，不能用“难过得”来描述。"}], "explanations": {"受不了": "受不了：难过得忍不下去，与“让他难过得”引出的结果相合。", "笑个不停": "语义：“笑个不停”与“老朋友去世”的悲痛情绪相反，不符合句意。", "唱起歌来": "搭配：“难过得”后接的是伤心的状态，“唱起歌来”是欢快的活动，两者不搭配。", "跳起舞来": "语义：“跳舞”与老朋友去世的情境相悖，不能用“难过得”来描述。"}, "sentence_index": 6, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他平静地受不了这个坏消息，一句话也没说。", "explanation": "这里应该用〈接受〉。“受不了”表示忍不下去，不能和“平静地”“一句话也没说”连用；平静地面对坏消息应说“接受”。"}, {"text": "这次旅行他玩得很开心，受不了每一个景点的美景。", "explanation": "这里应该用〈享受〉。“受不了”表示承受不住，与“玩得很开心”的语境矛盾；欣赏美景、感到快乐应说“享受”。"}, {"text": "他每天受不了地加班到深夜，从没休息过。", "explanation": "这里应该用〈坚持〉。“受不了”表示承受不住、忍不下去，不能表示坚持着做某事，这里应说“坚持加班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到父亲住院，他心里难受得受得了。", "corrected_sentence": "看到父亲住院，他心里难受得受不了。", "error_description": "可能补语肯定否定错误：此处表示难过到忍不下去，应说“受不了”；“受得了”表示能承受，与“难受得”的语境相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一想到要和孩子分开，她难过受不了。", "corrected_sentence": "一想到要和孩子分开，她难过得受不了。", "error_description": "补语标记缺失：“难过”后接程度补语要用“得”，应说“难过得受不了”，不能省掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
