INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不能忍受；承受不住。", "primary_collocate": null, "pronunciation": "shòu bu liǎo", "ipa": "ʂoʊ̯˥˩ pu liɑʊ̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "今天太热了，我真的受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里太吵了，我一分钟也受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天抽烟，我受不了那个味道。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙疼得厉害，他疼得受不了，去看医生。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板要求太多，工作压力大，他受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天这么冷，没有暖气我可受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我受不了他一直说别人的坏话。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么重的行李，小孩一个人肯定受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里又闷又臭，大家都受不了，开了窗。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的坏脾气，同事们早就受不了了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受得了", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "对热、吵、痛、压力等不能忍受，承受不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：承受不住天热，与“今天太热了”的语境吻合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示感到舒服快乐，与“太热了”的抱怨语气相反。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，与“太热”的抱怨语境相反，句子矛盾。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示愿意，与“太热”的语境不符，单独说在这里不通顺。"}], "explanations": {"受不了": "受不了：承受不住天热，与“今天太热了”的语境吻合。", "享受": "语义：“享受”表示感到舒服快乐，与“太热了”的抱怨语气相反。", "满意": "语义：“满意”表示称心，与“太热”的抱怨语境相反，句子矛盾。", "乐意": "语义：“乐意”表示愿意，与“太热”的语境不符，单独说在这里不通顺。"}, "sentence_index": 0, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到父亲离开的消息，她心里难受，却受不了地笑了起来。", "explanation": "这里应该用〈忍不住〉。“受不了”表示承受不住，不能表示控制不住地笑出来，应说“忍不住笑了起来”。"}, {"text": "这件事他默默受不了十年，从不抱怨。", "explanation": "这里应该用〈忍耐〉。“受不了”表示承受不住、忍不下去，不能表示长期压住不说，与“从不抱怨”也对不上。"}, {"text": "他很勇敢，打针的时候一点也受不了，一声都没哭。", "explanation": "这里应该用〈不怕〉。“受不了”表示承受不住，与“很勇敢”“一声都没哭”矛盾，应说“一点也不怕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：承受不住他的唠叨，与“他一直说别人的坏话”引起的烦扰相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱，与“说别人的坏话”的厌烦语气相反。"}, {"text": "赞同", "is_correct": false, "explanation": "语义：“赞同”表示认可，不能用来表示忍不住某人的坏话，句意矛盾。"}, {"text": "钦佩", "is_correct": false, "explanation": "语域：“钦佩”偏书面，与口语的抱怨语境不符，而且语义也相反。"}], "explanations": {"受不了": "受不了：承受不住他的唠叨，与“他一直说别人的坏话”引起的烦扰相合。", "欣赏": "语义：“欣赏”表示喜爱，与“说别人的坏话”的厌烦语气相反。", "赞同": "语义：“赞同”表示认可，不能用来表示忍不住某人的坏话，句意矛盾。", "钦佩": "语域：“钦佩”偏书面，与口语的抱怨语境不符，而且语义也相反。"}, "sentence_index": 6, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "想到奶奶，他受不了地坐在台阶上，一直看着天。", "explanation": "这里应该用〈发呆〉。“受不了”表示承受不住，不能修饰坐着发呆的动作。"}, {"text": "他拼命受不了眼泪，不肯在人前掉一滴。", "explanation": "这里应该用〈忍住〉。“受不了”是承受不住某种刺激，不能表示主动压抑眼泪，与“拼命”的意思不符。"}, {"text": "我们一起去爬山，他一路上受不了地唱着歌，从不喊累。", "explanation": "这里应该用〈坚持〉。“受不了”表示承受不住、忍不下去，不能表示坚持着做某事，这里应说“坚持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么吵的音乐，吵我实在受不了。", "corrected_sentence": "这么吵的音乐，吵得我实在受不了。", "error_description": "补语标记缺失：“吵”后接程度补语要用“得”，应说“吵得我实在受不了”，不能省掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个味道太刺鼻，我真的受得了。", "corrected_sentence": "这个味道太刺鼻，我真的受不了。", "error_description": "肯定否定错误：“太刺鼻”说明难以忍受，应说“受不了”；“受得了”表示能承受，与语境相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "让人想笑，因为很奇怪或者很傻。", "primary_collocate": null, "pronunciation": "kě xiào", "ipa": "kʰɤ˨˩ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他穿着大大的鞋子走路，样子很可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗的动作真可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帽子戴反了，看起来很可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说的话太可笑了。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不觉得他那样跳舞很可笑吗？", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学猫叫的声音一点也不可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鸡蛋放在头上，真是可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩的样子又可爱又可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿错了衣服，样子十分可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的画太可笑了，大家都笑了。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "样子、动作或话语滑稽，让人忍不住发笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可笑", "is_correct": true, "explanation": "可笑：让人想笑，与「穿着大大的鞋子走路」的滑稽样子相符。"}, {"text": "轻盈", "is_correct": false, "explanation": "语义：穿着大鞋子走路显得笨拙，与「轻盈」的样子矛盾。"}, {"text": "利落", "is_correct": false, "explanation": "语义：穿着大鞋子走路显得笨拙，与「利落」的干练印象矛盾。"}, {"text": "可恶", "is_correct": false, "explanation": "语义：「可恶」指令人厌恶，与这个滑稽的画面不合。"}], "explanations": {"可笑": "可笑：让人想笑，与「穿着大大的鞋子走路」的滑稽样子相符。", "轻盈": "语义：穿着大鞋子走路显得笨拙，与「轻盈」的样子矛盾。", "利落": "语义：穿着大鞋子走路显得笨拙，与「利落」的干练印象矛盾。", "可恶": "语义：「可恶」指令人厌恶，与这个滑稽的画面不合。"}, "sentence_index": 0, "correct_answer": "可笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里很可笑，大家都在认真看书。", "explanation": "这里应该用〈安静〉。可笑指让人想笑的奇怪或傻，不能用来形容图书馆的环境。"}, {"text": "我们在海边散步，今天的天气很可笑。", "explanation": "这里应该用〈晴朗〉。可笑不能用来形容天气，描述天气应该用晴朗等词。"}, {"text": "这个房间的温度很可笑，我都要冻坏了。", "explanation": "这里应该用〈寒冷〉。可笑不能形容温度，描述房间的冷应该用寒冷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可笑", "is_correct": true, "explanation": "可笑：让人想笑，与「把鸡蛋放在头上」的滑稽做法相符。"}, {"text": "合理", "is_correct": false, "explanation": "语义：把鸡蛋放在头上并不合理，与「合理」矛盾。"}, {"text": "优美", "is_correct": false, "explanation": "搭配：「优美」多形容动作、景色或文字，不用来评价这种荒唐做法。"}, {"text": "可敬", "is_correct": false, "explanation": "语义：这种做法不值得敬佩，与「可敬」矛盾。"}], "explanations": {"可笑": "可笑：让人想笑，与「把鸡蛋放在头上」的滑稽做法相符。", "合理": "语义：把鸡蛋放在头上并不合理，与「合理」矛盾。", "优美": "搭配：「优美」多形容动作、景色或文字，不用来评价这种荒唐做法。", "可敬": "语义：这种做法不值得敬佩，与「可敬」矛盾。"}, "sentence_index": 6, "correct_answer": "可笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次灾难很可笑，许多人失去了家园。", "explanation": "这里应该用〈可怕〉。可笑指让人想笑的奇怪或傻，不能用来形容灾难。"}, {"text": "这次交通事故很可笑，司机被送进了医院。", "explanation": "这里应该用〈严重〉。可笑不能用来形容交通事故这样的严重情况。"}, {"text": "他为了救人牺牲了自己，真可笑。", "explanation": "这里应该用〈可敬〉。可笑指让人想笑的奇怪或傻，不能用来评价为救人牺牲的英雄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的动作很太可笑了，孩子们都笑了。", "corrected_sentence": "她的动作太可笑了，孩子们都笑了。", "error_description": "重复程度副词：“很”和“太”不能同时修饰同一个形容词，应只用“太可笑了”，去掉“很”。错误形式：很太可笑了；正确形式：太可笑了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小猫的样子地可笑。", "corrected_sentence": "那只小猫的样子真可笑。", "error_description": "虚词错误：修饰“可笑”的程度副词应用“真”，不能用结构助词“地”。错误形式：地可笑；正确形式：真可笑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
