INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96328, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "引人发笑的；荒谬、不合情理的。", "primary_collocate": null, "pronunciation": "kě xiào", "ipa": "kʰɤ˨˩ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他连自己的名字都写错，真可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说他不会游泳，这个想法太可笑了。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的理由很可笑，没有人会相信。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用一百块买一辆车，真是可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规定可笑得让人不能接受。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不会开车的人教别人开车，多么可笑！", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说月亮是用纸做的，这话可笑极了。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家觉得这样的比赛规则很可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为这点小事生气，真可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己迟到，还说别人慢，实在可笑。", "target_word": "可笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "想法、理由、做法荒谬不合情理，带有讽刺意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可笑", "is_correct": true, "explanation": "可笑：荒谬、不合情理，与「连自己的名字都写错」的荒谬情形相符。"}, {"text": "精确", "is_correct": false, "explanation": "语义：写错自己的名字与「精确」矛盾，句子说不通。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：「清楚」表示明白无误，与「写错名字」矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：「轻松」描述心情或做事的感觉，不用来评价写错名字这件事。"}], "explanations": {"可笑": "可笑：荒谬、不合情理，与「连自己的名字都写错」的荒谬情形相符。", "精确": "语义：写错自己的名字与「精确」矛盾，句子说不通。", "清楚": "语义：「清楚」表示明白无误，与「写错名字」矛盾。", "轻松": "搭配：「轻松」描述心情或做事的感觉，不用来评价写错名字这件事。"}, "sentence_index": 0, "correct_answer": "可笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次手术很可笑，病人的情况很严重。", "explanation": "这里应该用〈危险〉。可笑表示引人发笑或荒谬，不能用来形容手术的风险。"}, {"text": "这次意外很可笑，他的腿骨折了。", "explanation": "这里应该用〈悲惨〉。可笑不能用来形容骨折这样的意外。"}, {"text": "妈妈病了好几天，我觉得很可笑。", "explanation": "这里应该用〈心疼〉。可笑表示引人发笑或荒谬，不能用来表达对生病的妈妈的关心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可笑", "is_correct": true, "explanation": "可笑：荒谬、不合情理，与「月亮是用纸做的」这种说法相符。"}, {"text": "真实", "is_correct": false, "explanation": "语义：月亮是纸做的并不真实，「真实」与句意矛盾。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：这种说法并不可靠，「可靠」与荒谬的说法矛盾。"}, {"text": "正确", "is_correct": false, "explanation": "语义：「月亮是用纸做的」本是荒谬的说法，不能说“正确”，与句意矛盾。"}], "explanations": {"可笑": "可笑：荒谬、不合情理，与「月亮是用纸做的」这种说法相符。", "真实": "语义：月亮是纸做的并不真实，「真实」与句意矛盾。", "可靠": "语义：这种说法并不可靠，「可靠」与荒谬的说法矛盾。", "正确": "语义：「月亮是用纸做的」本是荒谬的说法，不能说“正确”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "可笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水很可笑，里面的鱼都死光了。", "explanation": "这里应该用〈脏〉。可笑表示荒谬或引人发笑，不能用来形容河水被污染的情况。"}, {"text": "他的演讲很可笑，听得大家都哭了。", "explanation": "这里应该用〈感人〉。可笑表示荒谬或引人发笑，不能用来形容让人落泪的演讲。"}, {"text": "这个孩子没有饭吃，真可笑。", "explanation": "这里应该用〈可怜〉。可笑表示荒谬或引人发笑，不能用来同情没有饭吃的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的理由可笑的没人相信。", "corrected_sentence": "他的理由可笑得没人相信。", "error_description": "助词错误：“可笑”后接表程度的补语，应用“得”而非“的”。错误形式：可笑的没人相信；正确形式：可笑得没人相信。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个说法很太可笑了，没人会信。", "corrected_sentence": "这个说法太可笑了，没人会信。", "error_description": "重复程度副词：“很”和“太”不能同时修饰同一个形容词，应只用“太可笑了”，去掉“很”。错误形式：很太可笑了；正确形式：太可笑了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
