INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和别人一起走同一条路。", "primary_collocate": null, "pronunciation": "tóng xíng", "ipa": "tʰʊŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我和朋友同行去学校。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们同行吧。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我同行了一段路。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很长，我们三个人同行。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去车站吗？我们可以同行。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天和妹妹同行回家。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生同行去公园。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们同行过一次，很开心。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，你一个人走，我和你同行。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们同行到路口才分开。", "target_word": "同行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同行了", "label": "体标（了）"}, {"form": "同行过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "和别人一起走同一条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96329, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同行", "is_correct": true, "explanation": "同行（tóng xíng）意思是和别人一起走同一条路。"}, {"text": "通行", "is_correct": false, "explanation": "通行（tōng xíng）第一音节为第一声，与 tóng 第二声不同，意思是畅通地通过。"}, {"text": "同性", "is_correct": false, "explanation": "同性（tóng xìng）第二音节为第四声，与 xíng 第二声不同，意思是性别相同。"}, {"text": "同心", "is_correct": false, "explanation": "同心（tóng xīn）韵尾为 -n，与 xíng 的 -ng 不同，意思是心意一致。"}], "explanations": {"同行": "同行（tóng xíng）意思是和别人一起走同一条路。", "通行": "通行（tōng xíng）第一音节为第一声，与 tóng 第二声不同，意思是畅通地通过。", "同性": "同性（tóng xìng）第二音节为第四声，与 xíng 第二声不同，意思是性别相同。", "同心": "同心（tóng xīn）韵尾为 -n，与 xíng 的 -ng 不同，意思是心意一致。"}, "sentence_index": null, "correct_answer": "同行"}, "level_3": {"options": [{"text": "同行", "is_correct": true, "explanation": "同行：和朋友一起走，与“去学校”的行走搭配。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”是去单位工作，与“去学校”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与结伴去学校不相干，说不通。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：“结账”需在收银处进行，不能与“去学校”连用。"}], "explanations": {"同行": "同行：和朋友一起走，与“去学校”的行走搭配。", "上班": "语义：“上班”是去单位工作，与“去学校”矛盾。", "睡觉": "语义：“睡觉”与结伴去学校不相干，说不通。", "结账": "搭配：“结账”需在收银处进行，不能与“去学校”连用。"}, "sentence_index": 0, "correct_answer": "同行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈同行我长大。", "explanation": "这里应该用〈陪伴〉。同行只指同路并排行走，不能用来说陪人长大。"}, {"text": "侦探同行嫌疑人。", "explanation": "这里应该用〈跟随〉。同行不能直接带人作宾语（应说“与某人同行”），且不表示在后面追踪对方。"}, {"text": "我们同行做作业。", "explanation": "这里应该用〈同时〉。同行只表示结伴走路，不表示同时做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96329, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同行", "is_correct": true, "explanation": "同行（tóng xíng）意思是和别人一起走同一条路。"}, {"text": "同姓", "is_correct": false, "explanation": "同姓（tóng xìng）第二音节为第四声，与 xíng 第二声不同，意思是姓氏相同。"}, {"text": "童星", "is_correct": false, "explanation": "童星（tóng xīng）第二音节为第一声，与 xíng 第二声不同，意思是儿童演员。"}, {"text": "童心", "is_correct": false, "explanation": "童心（tóng xīn）韵尾为 -n，与 xíng 的 -ng 不同，意思是孩子的心思。"}], "explanations": {"同行": "同行（tóng xíng）意思是和别人一起走同一条路。", "同姓": "同姓（tóng xìng）第二音节为第四声，与 xíng 第二声不同，意思是姓氏相同。", "童星": "童星（tóng xīng）第二音节为第一声，与 xíng 第二声不同，意思是儿童演员。", "童心": "童心（tóng xīn）韵尾为 -n，与 xíng 的 -ng 不同，意思是孩子的心思。"}, "sentence_index": null, "correct_answer": "同行"}, "level_3": {"options": [{"text": "同行", "is_correct": true, "explanation": "同行：一起走同一条路，与“去公园”的行走搭配。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与结伴去公园不相干，说不通。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”说的是身高变化，不能指结伴行走。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指不见了，与“去公园”的行动矛盾。"}], "explanations": {"同行": "同行：一起走同一条路，与“去公园”的行走搭配。", "结婚": "语义：“结婚”与结伴去公园不相干，说不通。", "长高": "体貌：“长高”说的是身高变化，不能指结伴行走。", "失踪": "语义：“失踪”指不见了，与“去公园”的行动矛盾。"}, "sentence_index": 6, "correct_answer": "同行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们同行解决了这道难题。", "explanation": "这里应该用〈合作〉。同行只表示结伴走路，不表示一起解决问题。"}, {"text": "警察同行犯人回局里。", "explanation": "这里应该用〈护送〉。同行不能直接带人作宾语（应说“与某人同行”），也不含押送保护之义。"}, {"text": "两队同行争抢冠军。", "explanation": "这里应该用〈竞争〉。同行表示一起同路行走，与争抢冠军的含义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们同行了过一小段路，很开心。", "corrected_sentence": "我们同行过一小段路，很开心。", "error_description": "错误：“同行了过”；正确：“同行过”。“过”已表示经历，不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们同行了到街口才分开。", "corrected_sentence": "他们同行到街口才分开。", "error_description": "错误：“了”插在“同行”和补语“到”之间；正确：去掉“了”，写作“同行到街口”。动词与结果补语之间不能插“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
