INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你在家里或者在一起做事的人中，是什么样的身份。", "primary_collocate": null, "pronunciation": "míng fèn", "ipa": "miŋ˧˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "她在这个家里一直没有名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虽然住在我们家，却没有名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子想知道自己在新家的名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都叫她姐姐，她在家里有了名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，不给孩子名分，他会难过的。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在店里帮忙多年，却一直没有名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们一起做生意，每个人都要有名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她来我们家三年了，还没有正式的名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王刚来队里，大家先给了他一个名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，一家人要先把名分说清楚。", "target_word": "名分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在家里或一起做事的人中被承认的身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名分", "is_correct": true, "explanation": "正确：“名分”指在家里被承认的身份，与“在这个家里一直没有”语义吻合。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是家里的东西，“在这个家里一直没有学校”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，与家里的身份无关，不能用“没有身材”来描述这种处境。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然景物，不会是家里缺少的东西。"}], "explanations": {"名分": "正确：“名分”指在家里被承认的身份，与“在这个家里一直没有”语义吻合。", "学校": "语义：学校不是家里的东西，“在这个家里一直没有学校”说不通。", "身材": "体貌：“身材”指人的体形，与家里的身份无关，不能用“没有身材”来描述这种处境。", "大海": "语义：大海是自然景物，不会是家里缺少的东西。"}, "sentence_index": 0, "correct_answer": "名分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他以公司的名分签了合同。", "explanation": "这里应该用〈名义〉。“以……的名义”表示凭某种名目行事，名分指在家庭或团体中被承认的身份，不能这样用。"}, {"text": "这家店的名分很好听。", "explanation": "这里应该用〈名称〉。名称指事物的叫法，名分指身份，不能说“名分很好听”。"}, {"text": "这次比赛只有三个名分。", "explanation": "这里应该用〈名额〉。名额是可以分配的席位，名分指身份，不能按个数分配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名分", "is_correct": true, "explanation": "正确：“名分”指在团体或合作中被承认的身份，与“做生意”的语境相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室用品，与做生意无关，“每个人都要有黑板”不通。"}, {"text": "尾巴", "is_correct": false, "explanation": "体貌：“尾巴”是身体部位，不能作为合作中每个人都要有的东西。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人可以拥有的东西，“每个人都要有天气”与做生意无关。"}], "explanations": {"名分": "正确：“名分”指在团体或合作中被承认的身份，与“做生意”的语境相符。", "黑板": "语义：黑板是教室用品，与做生意无关，“每个人都要有黑板”不通。", "尾巴": "体貌：“尾巴”是身体部位，不能作为合作中每个人都要有的东西。", "天气": "语义：天气不是人可以拥有的东西，“每个人都要有天气”与做生意无关。"}, "sentence_index": 6, "correct_answer": "名分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司里有了一条名分。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，名分是抽象的身份，不能用“条”来计量。"}, {"text": "她在家里拿到了一把名分。", "explanation": "这里应该用〈个〉。〈把〉用于有柄的东西，名分是抽象的身份，不能用“把”来计量。"}, {"text": "这件事让他有了一张名分。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，名分是抽象的身份，不能用“张”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于有着名分。", "corrected_sentence": "她终于有了名分。", "error_description": "体标错误：“终于”表示状态变化已经实现，要用“了”，不能用表示持续的“着”，应说“她终于有了名分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在团体里没有一件名分。", "corrected_sentence": "她在团体里没有名分。", "error_description": "量词错误：名分是抽象的身份，不能用量词〈件〉计量（〈件〉多用于衣物、事情等）；应直接说“她在团体里没有名分”，去掉“一件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
