INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人在社会或团体中所处的地位和身份。", "primary_collocate": null, "pronunciation": "míng fèn", "ipa": "miŋ˧˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "在那个年代，女人在社会上没有名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想在团体里争一个名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子生下来，却没有合法的名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组织给了新成员正式的名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，名分高低决定一个人的待遇。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了名分，一直留在那个团体里。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有名分，在社会上很难得到尊重。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说做人要守名分，不能乱来。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司成立后，大家的名分都清楚了。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事让他在行业里有了名分。", "target_word": "名分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人在社会或团体中的地位和身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名分", "is_correct": true, "explanation": "正确：“名分”指社会或团体中的地位和身份，与“没有”搭配，符合语境。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是用来看路的，“在社会上没有地图”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体器官，不能说社会上“没有眼睛”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，与社会地位毫无关系。"}], "explanations": {"名分": "正确：“名分”指社会或团体中的地位和身份，与“没有”搭配，符合语境。", "地图": "语义：地图是用来看路的，“在社会上没有地图”说不通。", "眼睛": "体貌：“眼睛”是身体器官，不能说社会上“没有眼睛”。", "钢笔": "语义：钢笔是书写工具，与社会地位毫无关系。"}, "sentence_index": 0, "correct_answer": "名分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，他的名分排在前三。", "explanation": "这里应该用〈名次〉。名次指排列的次序，名分指身份，不能用于排名。"}, {"text": "学校只有两个名分。", "explanation": "这里应该用〈名额〉。名额是可以分配的席位，名分不能这样按数量分配。"}, {"text": "他以行业协会的名分举办了比赛。", "explanation": "这里应该用〈名义〉。“以……的名义”表示凭某种名目行事，名分指人在团体中的地位和身份，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名分", "is_correct": true, "explanation": "正确：“名分”是社会上的身份地位，与“很难得到尊重”构成因果关系。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出门带的东西，与社会尊重无关，“没有行李，很难得到尊重”不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能作为社会尊重的前提。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能说“没有桌子，在社会上很难得到尊重”。"}], "explanations": {"名分": "正确：“名分”是社会上的身份地位，与“很难得到尊重”构成因果关系。", "行李": "语义：行李是出门带的东西，与社会尊重无关，“没有行李，很难得到尊重”不通。", "身高": "体貌：“身高”指身体的高矮，不能作为社会尊重的前提。", "桌子": "语义：桌子是家具，不能说“没有桌子，在社会上很难得到尊重”。"}, "sentence_index": 6, "correct_answer": "名分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事让他在行业里有了一根名分。", "explanation": "这里应该用〈个〉。〈根〉用于细长的条状物，名分是抽象的身份，不能用“根”来计量。"}, {"text": "这件事让他在行业里有了一张名分。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，名分是抽象的身份，不能用“张”来计量。"}, {"text": "这件事让他在行业里有了一件名分。", "explanation": "这里应该用〈个〉。〈件〉多用于衣物、事情等，名分是抽象的身份，不能用“件”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司终于给着他名分。", "corrected_sentence": "公司终于给了他名分。", "error_description": "体标错误：“给”是一次完成的动作，“终于”也表示已经实现，要用“了”，不能用表示持续的“着”，应说“公司终于给了他名分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在团体里一直没有一条名分。", "corrected_sentence": "他在团体里一直没有名分。", "error_description": "量词错误：名分是抽象的身份，不能用量词〈条〉计量（〈条〉用于细长的条状物）；应说“他在团体里一直没有名分”，去掉“一条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
