INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大人喝的、有很多泡泡的黄黄的饮料。", "primary_collocate": null, "pronunciation": "pí jiǔ", "ipa": "pʰi˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸晚饭时喝一杯啤酒。", "target_word": "啤酒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "啤酒是黄色的，上面有白泡泡。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩不能喝啤酒，那是大人喝的。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "啤酒倒进杯子里，有很多泡泡。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天很热，叔叔喝了一大杯冰啤酒。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我闻了一下啤酒，味道有点苦。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看球赛的时候，喜欢喝一瓶啤酒。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸开了一瓶啤酒，泡泡一下子冒了出来。", "target_word": "啤酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶黄黄的饮料是啤酒，不是果汁。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "叔叔拿着一杯啤酒，坐在沙发上。", "target_word": "啤酒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "瓶", "label": "量词"}, {"form": "罐", "label": "量词"}], "register": "口语", "sense_fingerprint": "大人喝的、黄色有泡泡的饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "啤酒", "is_correct": true, "explanation": "正确：与“喝一杯”搭配，指爸爸晚饭时喝的啤酒。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“喝”要搭配饮品，米饭是主食，不能说“喝一杯米饭”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是固体食物，不是饮料，“一杯面包”也说不通。"}, {"text": "香蕉", "is_correct": false, "explanation": "搭配：“一杯”要配液体，香蕉不能喝，也不能用“杯”计量。"}], "explanations": {"啤酒": "正确：与“喝一杯”搭配，指爸爸晚饭时喝的啤酒。", "米饭": "搭配：“喝”要搭配饮品，米饭是主食，不能说“喝一杯米饭”。", "面包": "语义：面包是固体食物，不是饮料，“一杯面包”也说不通。", "香蕉": "搭配：“一杯”要配液体，香蕉不能喝，也不能用“杯”计量。"}, "sentence_index": 0, "correct_answer": "啤酒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是刚鲜榨出来的啤酒。", "explanation": "这里应该用〈橙汁〉。“鲜榨”用于果汁等，啤酒要经过发酵酿造，不说鲜榨。"}, {"text": "我买了一只啤酒。", "explanation": "这里应该用〈瓶〉或〈罐〉。“只”用于动物等，啤酒按瓶、罐、杯计量。"}, {"text": "啤酒要烧开再喝，才能保证安全。", "explanation": "这里应该用〈饮用水〉。“烧开再喝”用于生水，啤酒是发酵酿成的含酒精饮料，不需要也不能烧开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "啤酒", "is_correct": true, "explanation": "正确：与“喜欢喝一瓶”搭配，指爷爷看球赛时喝的啤酒。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是主食，不是饮料，不能“喝”。"}, {"text": "薯片", "is_correct": false, "explanation": "语义：薯片是零食，不是饮料，“一瓶薯片”说不通。"}, {"text": "花生", "is_correct": false, "explanation": "搭配：“喝一瓶”要搭配饮品，花生是坚果，不能喝。"}], "explanations": {"啤酒": "正确：与“喜欢喝一瓶”搭配，指爷爷看球赛时喝的啤酒。", "饺子": "语义：饺子是主食，不是饮料，不能“喝”。", "薯片": "语义：薯片是零食，不是饮料，“一瓶薯片”说不通。", "花生": "搭配：“喝一瓶”要搭配饮品，花生是坚果，不能喝。"}, "sentence_index": 6, "correct_answer": "啤酒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的啤酒很大，走路都喘。", "explanation": "这里应该用〈啤酒肚〉。“啤酒肚”指凸出的大肚子，“啤酒”单独不能用来形容身材。"}, {"text": "喝啤酒前要先醒酒。", "explanation": "这里应该用〈红酒〉。红酒常需醒酒，啤酒不需要，“醒酒”不适用于啤酒。"}, {"text": "啤酒要趁热喝，凉了就不好喝了。", "explanation": "这里应该用〈咖啡〉。“趁热喝”多用于咖啡等热饮，啤酒一般冰镇后喝，不能说趁热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天晚上喝一只啤酒。", "corrected_sentence": "妈妈每天晚上喝一杯啤酒。", "error_description": "错误形式：“一只啤酒”；正确形式：“一杯啤酒”。“只”用于动物等，啤酒要用杯、瓶、罐计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天晚上开了一张啤酒。", "corrected_sentence": "他今天晚上开了一瓶啤酒。", "error_description": "错误形式：“一张啤酒”；正确形式：“一瓶啤酒”。“张”用于纸、桌子等扁平的东西，啤酒要用瓶、罐、杯计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
