INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用大麦芽和啤酒花发酵酿成的含酒精饮料，有泡沫。", "primary_collocate": null, "pronunciation": "pí jiǔ", "ipa": "pʰi˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "啤酒是用大麦芽酿成的。", "target_word": "啤酒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "啤酒含有少量酒精，喝多了会醉。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酿造啤酒需要大麦芽和水。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "啤酒经过发酵，会产生很多泡沫。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每年生产几百万吨啤酒。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "啤酒的酒精含量一般只有百分之四左右。", "target_word": "啤酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "啤酒倒进杯子后，表面会出现一层泡沫。", "target_word": "啤酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国的啤酒历史很长，品种也很多。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把大麦芽放进罐里发酵，最后酿成啤酒。", "target_word": "啤酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和白酒相比，啤酒的酒精度比较低。", "target_word": "啤酒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "瓶", "label": "量词"}, {"form": "罐", "label": "量词"}], "register": "中性", "sense_fingerprint": "以大麦芽发酵酿成的含酒精、有泡沫的饮料（酿造与成分角度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啤酒", "is_correct": true, "explanation": "正确答案。啤酒 pí jiǔ，用大麦芽发酵酿成的含酒精饮料。"}, {"text": "白酒", "is_correct": false, "explanation": "bái（第二声）与 pí 声调相同，只差声母（b 与 p），意思是用高粱等蒸馏出的烈性酒。"}, {"text": "梨酒", "is_correct": false, "explanation": "lí 与 pí 只差声母，声调相同，意思是用梨酿的酒。"}, {"text": "陪酒", "is_correct": false, "explanation": "péi（第二声）与 pí 声调相同，只多一个元音 e，意思是陪人一起饮酒。"}], "explanations": {"啤酒": "正确答案。啤酒 pí jiǔ，用大麦芽发酵酿成的含酒精饮料。", "白酒": "bái（第二声）与 pí 声调相同，只差声母（b 与 p），意思是用高粱等蒸馏出的烈性酒。", "梨酒": "lí 与 pí 只差声母，声调相同，意思是用梨酿的酒。", "陪酒": "péi（第二声）与 pí 声调相同，只多一个元音 e，意思是陪人一起饮酒。"}, "sentence_index": null, "correct_answer": "啤酒"}, "level_3": {"options": [{"text": "啤酒", "is_correct": true, "explanation": "正确：“酿成”的对象是酒类，啤酒是用大麦芽酿成的。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁用水果榨成，不是用大麦芽酿成的。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是用面粉烤成的，不是酿成的。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“酿成”用于酒、醋等发酵物，牛奶不能说“酿成”。"}], "explanations": {"啤酒": "正确：“酿成”的对象是酒类，啤酒是用大麦芽酿成的。", "果汁": "语义：果汁用水果榨成，不是用大麦芽酿成的。", "面包": "语义：面包是用面粉烤成的，不是酿成的。", "牛奶": "搭配：“酿成”用于酒、醋等发酵物，牛奶不能说“酿成”。"}, "sentence_index": 0, "correct_answer": "啤酒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "啤酒要现磨现喝，放久了味道就变了。", "explanation": "这里应该用〈咖啡〉。“现磨”用于咖啡等要磨粉的饮品，啤酒不用磨，不能说现磨现喝。"}, {"text": "喝啤酒前要先醒酒。", "explanation": "这里应该用〈红酒〉。红酒常需醒酒，啤酒不需要，“醒酒”不适用于啤酒。"}, {"text": "这瓶啤酒是用葡萄酿成的。", "explanation": "这里应该用〈葡萄酒〉。葡萄酒用葡萄酿成，啤酒用大麦芽酿成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "啤酒", "is_correct": true, "explanation": "正确：啤酒倒进杯子后会起泡沫，表面出现一层泡沫。"}, {"text": "沙子", "is_correct": false, "explanation": "搭配：“倒进杯子”后会起泡沫，要求液体，沙子是颗粒，不能这样。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油倒进杯子后不会产生泡沫。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块倒进杯子后会融化，不会出现一层泡沫。"}], "explanations": {"啤酒": "正确：啤酒倒进杯子后会起泡沫，表面出现一层泡沫。", "沙子": "搭配：“倒进杯子”后会起泡沫，要求液体，沙子是颗粒，不能这样。", "汽油": "语义：汽油倒进杯子后不会产生泡沫。", "冰块": "语义：冰块倒进杯子后会融化，不会出现一层泡沫。"}, "sentence_index": 6, "correct_answer": "啤酒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的啤酒越来越大了。", "explanation": "这里应该用〈啤酒肚〉。“啤酒肚”指凸出的大肚子，“啤酒”单独不能用来形容身材。"}, {"text": "这杯鲜榨的啤酒很新鲜。", "explanation": "这里应该用〈橙汁〉。“鲜榨”用于果汁，啤酒经发酵酿造，不说鲜榨。"}, {"text": "啤酒是靠蒸馏提高酒精度的。", "explanation": "这里应该用〈白酒〉。白酒靠蒸馏提高酒精度，啤酒靠发酵酿成，不经过蒸馏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们晚上要买一只啤酒。", "corrected_sentence": "我们晚上要买一箱啤酒。", "error_description": "错误形式：“一只啤酒”；正确形式：“一箱啤酒”。“只”用于动物等，啤酒要用箱、瓶、罐、杯计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人搬来了三匹啤酒。", "corrected_sentence": "工人搬来了三箱啤酒。", "error_description": "错误形式：“三匹啤酒”；正确形式：“三箱啤酒”。“匹”用于马、布等，啤酒要用箱、瓶、罐、杯计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
