INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96335, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "看到别人时用来打招呼的话。", "primary_collocate": null, "pronunciation": "hāi", "ipa": "xaɪ˥", "syllable_count": 1, "sentences": [{"text": "嗨，你好吗？", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗨，好久不见！", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到她，就说：“嗨！”", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗨，小王，你去哪儿？", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗨，今天天气真好，你去散步吗？", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我笑着说：“嗨！”", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗨，我是新同学，叫小明。", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走过来，对大家说：“嗨！”", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗨，你也在这儿买东西吗？", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在电梯里，邻居对我说了一声“嗨”。", "target_word": "嗨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "见面时打招呼用的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嗨", "is_correct": true, "explanation": "嗨（hāi）是见面打招呼的叹词，声调为第一声。"}, {"text": "还", "is_correct": false, "explanation": "还（hái）为第二声，与 hāi 声调不同，意思是仍然。"}, {"text": "海", "is_correct": false, "explanation": "海（hǎi）为第三声，与 hāi 声调不同，意思是海洋。"}, {"text": "开", "is_correct": false, "explanation": "开（kāi）声母为 k，与 h 不同，意思是打开。"}], "explanations": {"嗨": "嗨（hāi）是见面打招呼的叹词，声调为第一声。", "还": "还（hái）为第二声，与 hāi 声调不同，意思是仍然。", "海": "海（hǎi）为第三声，与 hāi 声调不同，意思是海洋。", "开": "开（kāi）声母为 k，与 h 不同，意思是打开。"}, "sentence_index": null, "correct_answer": "嗨"}, "level_3": {"options": [{"text": "嗨", "is_correct": true, "explanation": "嗨：打招呼的叹词，用在问候语之前，正确。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是表示唾弃的粗俗叹词，不用于礼貌问候。"}, {"text": "噗", "is_correct": false, "explanation": "语义：“噗”是吹气的声音，与问候无关。"}, {"text": "呜", "is_correct": false, "explanation": "搭配：“呜”多与哭声连用，不用于开口问候。"}], "explanations": {"嗨": "嗨：打招呼的叹词，用在问候语之前，正确。", "呸": "语域：“呸”是表示唾弃的粗俗叹词，不用于礼貌问候。", "噗": "语义：“噗”是吹气的声音，与问候无关。", "呜": "搭配：“呜”多与哭声连用，不用于开口问候。"}, "sentence_index": 0, "correct_answer": "嗨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考了满分，高兴地喊：“嗨！”", "explanation": "这里的〈嗨〉表示高兴地欢呼，而不是打招呼。"}, {"text": "这个蛋糕太好吃了，我忍不住说：“嗨！”", "explanation": "这里的〈嗨〉表示赞叹，而不是打招呼。"}, {"text": "嗨，做个好梦！", "explanation": "这里应该用〈晚安〉。嗨用于见面打招呼，不用于睡前道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96335, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嗨", "is_correct": true, "explanation": "嗨（hāi）是见面打招呼的叹词，声调为第一声。"}, {"text": "害", "is_correct": false, "explanation": "害（hài）为第四声，与 hāi 声调不同，意思是伤害。"}, {"text": "黑", "is_correct": false, "explanation": "黑（hēi）韵母为 ei，与 ai 不同，意思是黑色。"}, {"text": "胎", "is_correct": false, "explanation": "胎（tāi）声母为 t，与 h 不同，意思是轮胎或胎儿。"}], "explanations": {"嗨": "嗨（hāi）是见面打招呼的叹词，声调为第一声。", "害": "害（hài）为第四声，与 hāi 声调不同，意思是伤害。", "黑": "黑（hēi）韵母为 ei，与 ai 不同，意思是黑色。", "胎": "胎（tāi）声母为 t，与 h 不同，意思是轮胎或胎儿。"}, "sentence_index": null, "correct_answer": "嗨"}, "level_3": {"options": [{"text": "嗨", "is_correct": true, "explanation": "嗨：打招呼的叹词，用于自我介绍之前，正确。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与自我介绍的语境不符。"}, {"text": "哼", "is_correct": false, "explanation": "语域：“哼”带轻蔑口气，用于自我介绍显得不礼貌。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃，用在自我介绍前很不礼貌。"}], "explanations": {"嗨": "嗨：打招呼的叹词，用于自我介绍之前，正确。", "嘘": "语义：“嘘”表示让人安静，与自我介绍的语境不符。", "哼": "语域：“哼”带轻蔑口气，用于自我介绍显得不礼貌。", "呸": "语域：“呸”表示唾弃，用在自我介绍前很不礼貌。"}, "sentence_index": 6, "correct_answer": "嗨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然从门后走出来，我吓了一跳，喊了一声“嗨”。", "explanation": "这里的〈嗨〉表示惊吓，而不是打招呼。"}, {"text": "又把作业忘在家里了，我懊恼地说：“嗨！”", "explanation": "这里的〈嗨〉表示懊恼，而不是打招呼。"}, {"text": "这道菜太辣了，她忍不住喊了一声“嗨”。", "explanation": "这里的〈嗨〉表示辣得惊叫，而不是打招呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在走廊里，邻居对我说了一个“嗨”。", "corrected_sentence": "在走廊里，邻居对我说了一声“嗨”。", "error_description": "错误：“一个嗨”；正确：“一声嗨”。打招呼的声音用量词“声”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "嗨了，你最近还好吗？", "corrected_sentence": "嗨，你最近还好吗？", "error_description": "错误：“嗨了”；正确：“嗨”。叹词“嗨”后面不能加动态助词“了”，应直接说“嗨，你最近还好吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
