INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人活着一定要有的东西，比如吃的、喝的和住的地方。", "primary_collocate": null, "pronunciation": "jī běn xū yào", "ipa": "tɕi˥ pən˨˩˦ ɕy˥ jɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "吃饭和喝水是基本需要。", "target_word": "基本需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人要活下去，有吃有喝是基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住的地方也是人的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚出生的婴儿也需要有吃的、喝的和住的地方，这是基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有水，人就活不下去，水是基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈给我吃的、穿的，这是我的基本需要。", "target_word": "基本需要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了吃的和住的地方，我们的基本需要就满足了。", "target_word": "基本需要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都要吃、喝和住，这是基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们很穷，连基本需要都没有。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，吃饱和睡好是孩子的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人活着一定要有的吃的、喝的和住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本需要", "is_correct": true, "explanation": "正确：吃饭和喝水是人活着必需的基本需要。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：吃饭和喝水是生存必需，不是业余时间喜欢做的事。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指身体形态，吃饭和喝水不是身材。"}, {"text": "工作", "is_correct": false, "explanation": "语义：吃饭和喝水不是工作，“吃饭和喝水是工作”说不通。"}], "explanations": {"基本需要": "正确：吃饭和喝水是人活着必需的基本需要。", "爱好": "语义：吃饭和喝水是生存必需，不是业余时间喜欢做的事。", "身材": "语义：“身材”指身体形态，吃饭和喝水不是身材。", "工作": "语义：吃饭和喝水不是工作，“吃饭和喝水是工作”说不通。"}, "sentence_index": 0, "correct_answer": "基本需要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直有个基本需要，想去北京工作。", "explanation": "这里应该用〈愿望〉。“愿望”指个人希望实现的事，“基本需要”指生存必需，不能用来表示想去哪里。"}, {"text": "这家商店卖很多基本需要。", "explanation": "这里应该用〈生活用品〉。“卖”的对象是具体商品，“基本需要”是抽象的，不能卖。"}, {"text": "孩子最爱吃的是基本需要。", "explanation": "这里应该用〈零食〉。“最爱吃”说的是口味偏好，“基本需要”指生存必需，不能用来说孩子最爱吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本需要", "is_correct": true, "explanation": "正确：有了吃的和住的地方，人们维持生存的必需条件就满足了。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给别人的东西，不是需要被“满足”的生存条件。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“满足”的对象要是需求或愿望，“成绩”不能被满足。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“满足”不能接“天气”，天气不能作为被满足的对象。"}], "explanations": {"基本需要": "正确：有了吃的和住的地方，人们维持生存的必需条件就满足了。", "礼物": "语义：礼物是送给别人的东西，不是需要被“满足”的生存条件。", "成绩": "搭配：“满足”的对象要是需求或愿望，“成绩”不能被满足。", "天气": "搭配：“满足”不能接“天气”，天气不能作为被满足的对象。"}, "sentence_index": 6, "correct_answer": "基本需要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取得了很大的基本需要。", "explanation": "这里应该用〈成就〉。“成就”指取得的成绩，“基本需要”不能用“取得”来说。"}, {"text": "他拿到了一笔丰厚的基本需要。", "explanation": "这里应该用〈奖金〉。“拿到”“丰厚”用于奖金等钱款，“基本需要”指生存必需的东西，不能这样说。"}, {"text": "这次比赛的基本需要很好。", "explanation": "这里应该用〈成绩〉。“成绩”可以说“好”，“基本需要”不能用来评价好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个孩子都要满足几只基本需要。", "corrected_sentence": "每个孩子都要满足几项基本需要。", "error_description": "错误形式：“几只基本需要”；正确形式：“几项基本需要”。“只”用于动物，抽象的“需要”应用“项”或“种”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的基本需要要先得到满意。", "corrected_sentence": "孩子的基本需要要先得到满足。", "error_description": "错误形式：“得到满意”；正确形式：“得到满足”。“满意”是形容词，表示心里称心，不能说“得到满意”；需要被照顾到要说“得到满足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
