INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "维持生存和正常生活所必需的物质与条件，如衣食住行。", "primary_collocate": null, "pronunciation": "jī běn xū yào", "ipa": "tɕi˥ pən˨˩˦ ɕy˥ jɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "食物和水是人的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣食住行是人的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要先满足大家的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭、穿衣和住房都是基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的人们连基本需要都难以满足。", "target_word": "基本需要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资只够满足家里的基本需要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灾区的基本需要是食物、饮用水和帐篷。", "target_word": "基本需要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先解决基本需要，再考虑旅游和娱乐。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对穷人来说，基本需要比什么都重要。", "target_word": "基本需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者给灾区送去了帐篷和食物，满足了大家的基本需要。", "target_word": "基本需要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "维持生存和正常生活所必需的物质与条件（衣食住行）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本需要", "is_correct": true, "explanation": "正确：指维持生存的必需条件，食物和水属于人的基本需要。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：食物和水不是颜色，“人的颜色”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：食物和水不是年龄，不能作为“人的”某种属性。"}, {"text": "体貌", "is_correct": false, "explanation": "语义：“体貌”指外在形貌，食物和水不是人的体貌。"}], "explanations": {"基本需要": "正确：指维持生存的必需条件，食物和水属于人的基本需要。", "颜色": "语义：食物和水不是颜色，“人的颜色”说不通。", "年龄": "语义：食物和水不是年龄，不能作为“人的”某种属性。", "体貌": "语义：“体貌”指外在形貌，食物和水不是人的体貌。"}, "sentence_index": 0, "correct_answer": "基本需要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的基本需要是拿到冠军。", "explanation": "这里应该用〈目标〉。“目标”指想要达到的方向，“基本需要”指维持生存的必需品，不能用来说比赛的目标。"}, {"text": "市场对空调的基本需要很旺盛。", "explanation": "这里应该用〈需求〉。“需求”可以说“旺盛”，“基本需要”指维持生活必需的东西，不能用“旺盛”来形容。"}, {"text": "这家超市专门卖各种基本需要。", "explanation": "这里应该用〈生活用品〉。“卖”的对象是具体商品，“基本需要”是抽象概念，不能卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本需要", "is_correct": true, "explanation": "正确：灾区最迫切的必需品就是食物、饮用水和帐篷，属于基本需要。"}, {"text": "温度", "is_correct": false, "explanation": "语义：食物、饮用水和帐篷不是温度，“灾区的温度是……”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：食物、饮用水和帐篷不是味道，句子的所属关系不成立。"}, {"text": "名字", "is_correct": false, "explanation": "语义：食物、饮用水和帐篷不是名字，“灾区的名字是……”说不通。"}], "explanations": {"基本需要": "正确：灾区最迫切的必需品就是食物、饮用水和帐篷，属于基本需要。", "温度": "语义：食物、饮用水和帐篷不是温度，“灾区的温度是……”说不通。", "味道": "语义：食物、饮用水和帐篷不是味道，句子的所属关系不成立。", "名字": "语义：食物、饮用水和帐篷不是名字，“灾区的名字是……”说不通。"}, "sentence_index": 6, "correct_answer": "基本需要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的基本需要是当一名医生。", "explanation": "这里应该用〈理想〉。“理想”指长远的目标，“基本需要”指维持生存的必需品，不能用来指职业目标。"}, {"text": "早起是他的基本需要。", "explanation": "这里应该用〈习惯〉。“习惯”指长期养成的行为，“基本需要”指生存必需，不能用来说早起。"}, {"text": "这次出差的基本需要很紧，每天都排满了。", "explanation": "这里应该用〈行程〉。“紧”“排满”用于行程、日程，“基本需要”指生存必需，不能这样描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三只基本需要都很重要。", "corrected_sentence": "这三项基本需要都很重要。", "error_description": "错误形式：“三只基本需要”；正确形式：“三项基本需要”。“只”用于动物，抽象的“需要”应用“项”或“种”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要优先满意老人的基本需要。", "corrected_sentence": "我们要优先满足老人的基本需要。", "error_description": "错误形式：“满意”；正确形式：“满足”。“满意”是形容词，不能带“需要”作宾语；满足需求要用“满足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单用户", "is_correct": true, "explanation": "反义：“单用户”指只供一人使用，与“多用户”正好相反。"}, {"text": "昂贵的", "is_correct": false, "explanation": "无反义关系：“昂贵的”说价格高，与“多用户”所指的使用人数无关。"}, {"text": "粗糙的", "is_correct": false, "explanation": "无反义关系：“粗糙的”说表面不光滑，与“多用户”所指的使用人数无关。"}, {"text": "简洁的", "is_correct": false, "explanation": "无反义关系：“简洁的”说内容简练，与“多用户”所指的使用人数无关。"}], "correct_answer": "单用户", "explanations": {"单用户": "反义：“单用户”指只供一人使用，与“多用户”正好相反。", "昂贵的": "无反义关系：“昂贵的”说价格高，与“多用户”所指的使用人数无关。", "粗糙的": "无反义关系：“粗糙的”说表面不光滑，与“多用户”所指的使用人数无关。", "简洁的": "无反义关系：“简洁的”说内容简练，与“多用户”所指的使用人数无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单用户", "is_correct": true, "explanation": "反义：“单用户”指只供一人使用，与“多用户”正好相反。"}, {"text": "古老的", "is_correct": false, "explanation": "无反义关系：“古老的”说年代久远，与“多用户”所指的使用人数无关。"}, {"text": "灵活的", "is_correct": false, "explanation": "无反义关系：“灵活的”说变通方便，与“多用户”所指的使用人数无关。"}, {"text": "温暖的", "is_correct": false, "explanation": "无反义关系：“温暖的”说感觉温和，与“多用户”所指的使用人数无关。"}], "correct_answer": "单用户", "explanations": {"单用户": "反义：“单用户”指只供一人使用，与“多用户”正好相反。", "古老的": "无反义关系：“古老的”说年代久远，与“多用户”所指的使用人数无关。", "灵活的": "无反义关系：“灵活的”说变通方便，与“多用户”所指的使用人数无关。", "温暖的": "无反义关系：“温暖的”说感觉温和，与“多用户”所指的使用人数无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "允许多个使用者同时或分别使用的（多指计算机系统或软件）。", "primary_collocate": null, "pronunciation": "duō yòng hù", "ipa": "tu̯ɔ˥ jʊŋ˥˩ xu˥˩", "syllable_count": 3, "sentences": [{"text": "这台电脑装的是多用户系统。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多用户系统可以让几个人同时登录。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件有多用户版，适合公司使用。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板想买一个多用户的管理软件。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台服务器是多用户的，每个人有自己的账号。", "target_word": "多用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多用户的系统要设置不同的密码。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的电脑房用的是多用户系统。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的电脑是多用户的，每人一个桌面。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多用户软件可以分别保存每个人的文件。", "target_word": "多用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司的多用户系统里改了密码。", "target_word": "多用户", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多用户系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "计算机系统或软件允许多人同时或分别使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多用户", "is_correct": true, "explanation": "正确：“多用户系统”指允许多人同时或分别使用的系统，与句意一致。"}, {"text": "粉色的", "is_correct": false, "explanation": "搭配：颜色词不用来修饰“系统”，“粉色的系统”不成词。"}, {"text": "甜的", "is_correct": false, "explanation": "搭配：“甜的”是味道词，不修饰“系统”，“甜的系统”不成词。"}, {"text": "木头的", "is_correct": false, "explanation": "搭配：“木头的”说材料，不修饰软件系统，“木头系统”不说。"}], "explanations": {"多用户": "正确：“多用户系统”指允许多人同时或分别使用的系统，与句意一致。", "粉色的": "搭配：颜色词不用来修饰“系统”，“粉色的系统”不成词。", "甜的": "搭配：“甜的”是味道词，不修饰“系统”，“甜的系统”不成词。", "木头的": "搭配：“木头的”说材料，不修饰软件系统，“木头系统”不说。"}, "sentence_index": 0, "correct_answer": "多用户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机是多用户的，只有我一个人在用。", "explanation": "这里应该用〈专属〉。多用户指允许多人使用，与“只有我一个人在用”矛盾；只归一人用要说“专属”。"}, {"text": "这张书桌是多用户的，只属于我。", "explanation": "这里应该用〈私人〉。多用户只用于计算机系统或软件，不能用来形容书桌；东西只归自己一人用要说“私人”。"}, {"text": "这个软件只能一个人用，却是一款多用户软件。", "explanation": "这里应该用〈单机版〉。多用户软件允许多人同时或分别使用，与“只能一个人用”矛盾；只供一人用的软件要说“单机版”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多用户", "is_correct": true, "explanation": "正确：“多用户系统”指允许多人使用的系统，与“学校的电脑房”相符。"}, {"text": "一次性的", "is_correct": false, "explanation": "搭配：“一次性的”多用于餐具、用品，不修饰“系统”。"}, {"text": "私人的", "is_correct": false, "explanation": "语义：“私人的”指只归个人使用，与“学校的电脑房”供多人用的情境矛盾。"}, {"text": "易燃的", "is_correct": false, "explanation": "搭配：“易燃的”修饰物质，不修饰“系统”，说“易燃系统”不通。"}], "explanations": {"多用户": "正确：“多用户系统”指允许多人使用的系统，与“学校的电脑房”相符。", "一次性的": "搭配：“一次性的”多用于餐具、用品，不修饰“系统”。", "私人的": "语义：“私人的”指只归个人使用，与“学校的电脑房”供多人用的情境矛盾。", "易燃的": "搭配：“易燃的”修饰物质，不修饰“系统”，说“易燃系统”不通。"}, "sentence_index": 6, "correct_answer": "多用户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子是多用户的，只有我一个人能用。", "explanation": "这里应该用〈专用〉。多用户指允许多人使用，与“只有我一个人能用”矛盾；只给一人用要说“专用”。"}, {"text": "我的妹妹是个多用户的人，谁都能找她。", "explanation": "这里应该用〈平易近人〉。多用户只用于计算机系统或软件，不能形容人；说一个人谁都能接近要用“平易近人”。"}, {"text": "这首歌是多用户的，只有作曲的人能唱。", "explanation": "这里应该用〈独有〉。多用户指允许多人使用，与“只有作曲的人能唱”矛盾；只归一人所有要说“独有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套软件是多用户的的，每个员工都有自己的账号。", "corrected_sentence": "这套软件是多用户的，每个员工都有自己的账号。", "error_description": "“的”多写了一个。“多用户的”作谓语只用一个“的”，应说“这套软件是多用户的”，不能连用两个“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统是多用户地，几个人可以同时登录。", "corrected_sentence": "这套系统是多用户的，几个人可以同时登录。", "error_description": "“的”误用成“地”。“多用户”作谓语时用“的”，“地”只修饰动词，这里应说“多用户的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
