INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主制国家中被确定为继承皇位的儿子。", "primary_collocate": null, "pronunciation": "tài zǐ", "ipa": "tʰai˥˩ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "皇帝正式立他的大儿子为太子。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们都支持二儿子当太子。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝生病以后，太子开始处理国家大事。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个太子是皇帝亲自选出来的。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太子还小，皇后一直陪着他。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老皇帝去世了，太子马上登上了皇位。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝换了太子，大臣们都很吃惊。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太子的位置很重要，所有人都看着他。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝说，他的第二个儿子是新太子。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有很多太子，没有当上皇帝。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太子妃", "label": "复合"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "君主制国家中被正式确定的皇位继承人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7870b6f4-2759-41c0-b1b7-31d9f7ccd8bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96342, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太子", "is_correct": true, "explanation": "tài zǐ 指君主制国家中被正式确定为继承皇位的儿子。"}, {"text": "台子", "is_correct": false, "explanation": "台子 táizi 第一个音节声调与 tài 不同（阳平与去声），意思是桌子、平台。"}, {"text": "盖子", "is_correct": false, "explanation": "盖子 gàizi 第一个音节声母不同（g 与 t），声调相同，意思是盖儿。"}, {"text": "菜子", "is_correct": false, "explanation": "菜子 càizi 第一个音节声母不同（c 与 t），意思是菜籽。"}, {"text": "袋子", "is_correct": false, "explanation": "袋子 dàizi 第一个音节声母不同（d 与 t），声调相同，意思是口袋。"}], "explanations": {"太子": "tài zǐ 指君主制国家中被正式确定为继承皇位的儿子。", "台子": "台子 táizi 第一个音节声调与 tài 不同（阳平与去声），意思是桌子、平台。", "盖子": "盖子 gàizi 第一个音节声母不同（g 与 t），声调相同，意思是盖儿。", "菜子": "菜子 càizi 第一个音节声母不同（c 与 t），意思是菜籽。", "袋子": "袋子 dàizi 第一个音节声母不同（d 与 t），声调相同，意思是口袋。"}, "sentence_index": null, "correct_answer": "太子"}, "level_3": {"options": [{"text": "太子", "is_correct": true, "explanation": "太子指被正式确定的皇位继承人，这里指皇帝立为继承人的大儿子。"}, {"text": "公主", "is_correct": false, "explanation": "语义：“公主”指女儿，与前文“大儿子”的性别不符，句意不通。"}, {"text": "皇后", "is_correct": false, "explanation": "语义：“皇后”指皇帝的妻子，不能被立为儿子的身份，句意不通。"}, {"text": "皇宫", "is_correct": false, "explanation": "搭配：“立……为”后接身份或称号，“皇宫”是场所，不能用于“立为”。"}], "explanations": {"太子": "太子指被正式确定的皇位继承人，这里指皇帝立为继承人的大儿子。", "公主": "语义：“公主”指女儿，与前文“大儿子”的性别不符，句意不通。", "皇后": "语义：“皇后”指皇帝的妻子，不能被立为儿子的身份，句意不通。", "皇宫": "搭配：“立……为”后接身份或称号，“皇宫”是场所，不能用于“立为”。"}, "sentence_index": 0, "correct_answer": "太子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位太子是皇帝哥哥的孩子，将来要继承皇位。", "explanation": "这里应该用〈侄子〉。“太子”必须是皇帝的儿子，哥哥的孩子不能称太子。"}, {"text": "皇帝的哥哥是太子，他一直没有继承皇位。", "explanation": "这里应该用〈长兄〉。“太子”指皇帝的儿子，皇帝的哥哥不能称太子。"}, {"text": "这位太子是皇帝的妻子，她不能继承王位。", "explanation": "这里应该用〈皇后〉。“太子”指皇帝的儿子，不能指妻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96342, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "太子", "is_correct": true, "explanation": "tài zǐ 指君主制国家中被正式确定为继承皇位的儿子。"}, {"text": "带子", "is_correct": false, "explanation": "带子 dài zi 第一个音节声母不同（d 与 t），声调相同，意思是带儿、绳带。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子 pāizi 第一个音节声母不同（p 与 t），声调也不同，意思是球拍或节拍。"}, {"text": "癞子", "is_correct": false, "explanation": "癞子 làizi 第一个音节声母不同（l 与 t），声调相同，意思是头上长癣的人。"}], "explanations": {"太子": "tài zǐ 指君主制国家中被正式确定为继承皇位的儿子。", "带子": "带子 dài zi 第一个音节声母不同（d 与 t），声调相同，意思是带儿、绳带。", "拍子": "拍子 pāizi 第一个音节声母不同（p 与 t），声调也不同，意思是球拍或节拍。", "癞子": "癞子 làizi 第一个音节声母不同（l 与 t），声调相同，意思是头上长癣的人。"}, "sentence_index": null, "correct_answer": "太子"}, "level_3": {"options": [{"text": "太子", "is_correct": true, "explanation": "太子指被正式确定的皇位继承人，这里指皇帝换掉的那位继承人。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”不是可以被皇帝更换的继承人身份，句意不通。"}, {"text": "丫鬟", "is_correct": false, "explanation": "语义：“丫鬟”是服侍主人的人，不能作为皇帝更换的对象，句意不通。"}, {"text": "王宫", "is_correct": false, "explanation": "搭配：“换”后接的是人或物，“王宫”是场所，不能作被更换的对象。"}], "explanations": {"太子": "太子指被正式确定的皇位继承人，这里指皇帝换掉的那位继承人。", "农民": "语义：“农民”不是可以被皇帝更换的继承人身份，句意不通。", "丫鬟": "语义：“丫鬟”是服侍主人的人，不能作为皇帝更换的对象，句意不通。", "王宫": "搭配：“换”后接的是人或物，“王宫”是场所，不能作被更换的对象。"}, "sentence_index": 6, "correct_answer": "太子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位太子已经当了二十年皇帝。", "explanation": "这里应该用〈皇帝〉。“太子”是将来继承皇位的人，已经在位的人不能称太子。"}, {"text": "他的父亲是太子，所以他自己就是太子。", "explanation": "这里应该用〈皇孙〉。太子的儿子只能称皇孙，不能自己也称太子。"}, {"text": "他的妻子是太子，将来会成为王后。", "explanation": "这里应该用〈太子妃〉。“太子”指男性继承人，妻子应称“太子妃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇帝正式立他的二儿子是太子。", "corrected_sentence": "皇帝正式立他的二儿子为太子。", "error_description": "错误：“立……为……”结构中的“为”写成了“是”。“立”后接对象，再用“为”引出身份，正确说法是“皇帝正式立他的二儿子为太子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大臣们听说皇帝换了一只太子，都很吃惊。", "corrected_sentence": "大臣们听说皇帝换了一位太子，都很吃惊。", "error_description": "错误：量词用了“只”。“只”用于动物，“太子”指人，应用量词“位”，正确说法是“皇帝换了一位太子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb06fdd9-08b5-4670-be89-e1f673d9f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
