INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96343, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用两个东西或者手指把东西紧紧按住。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "他用筷子夹了一块鱼。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用两根手指夹着一张纸。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我夹了一个鸡腿。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指夹着一支笔。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用钳子夹住这块铁。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用筷子夹不起花生。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用两腿夹紧了马肚子。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指夹住我的鼻子。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用筷子夹菜时，手要拿稳。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟用小棍子夹住了那条虫。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夹了", "label": "完成体"}, {"form": "夹着", "label": "持续体"}, {"form": "夹过", "label": "经历体"}, {"form": "夹住", "label": "复合"}], "register": "中性", "sense_fingerprint": "夹：用筷子、钳子或手指等两个部分把东西按住拿起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96343, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹 jiā（第一声）：用筷子、手指等两个部分把东西按住拿起。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 jiā 韵母不同（a 与 ang），意思是江河。"}, {"text": "交", "is_correct": false, "explanation": "jiāo 与 jiā 韵母不同（a 与 ao），意思是交给、交付。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 jiā 声母不同（q 与 j），意思是用指甲或手指按压。"}], "explanations": {"夹": "夹 jiā（第一声）：用筷子、手指等两个部分把东西按住拿起。", "假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。", "驾": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。", "江": "jiāng 与 jiā 韵母不同（a 与 ang），意思是江河。", "交": "jiāo 与 jiā 韵母不同（a 与 ao），意思是交给、交付。", "掐": "qiā 与 jiā 声母不同（q 与 j），意思是用指甲或手指按压。"}, "sentence_index": null, "correct_answer": "夹"}, "level_3": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹了一块鱼：用筷子把鱼块夹起来，符合句意。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”需用刀斧等利器，不能用筷子砍鱼，句子不通。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”用手掌或拍子，不说“用筷子拍一块鱼”。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”是用肩膀承担重物，与“用筷子”不合，句子不通。"}], "explanations": {"夹": "夹了一块鱼：用筷子把鱼块夹起来，符合句意。", "砍": "语义：“砍”需用刀斧等利器，不能用筷子砍鱼，句子不通。", "拍": "搭配：“拍”用手掌或拍子，不说“用筷子拍一块鱼”。", "扛": "语义：“扛”是用肩膀承担重物，与“用筷子”不合，句子不通。"}, "sentence_index": 0, "correct_answer": "夹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把杯子夹在桌上。", "explanation": "这里应该用〈放〉。夹指用两个部分把东西按住，杯子只是搁在桌面上，应说“放”。"}, {"text": "她把一盆花夹在窗台上。", "explanation": "这里应该用〈摆〉。夹指用两个部分把东西按住，花盆只是摆放在窗台上，应说“摆”。"}, {"text": "他说话总爱夹着英语。", "explanation": "这里是“夹杂、混入”的意思，与本义“从两边用力按住或放入两物之间”无关，不能用于此义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96343, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹 jiā（第一声）：用筷子、手指等两个部分把东西按住拿起。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "将", "is_correct": false, "explanation": "jiāng 与 jiā 韵母不同（a 与 ang），意思是将要、把。"}, {"text": "间", "is_correct": false, "explanation": "jiān 与 jiā 韵母不同（a 与 an），意思是中间、房间。"}, {"text": "瞎", "is_correct": false, "explanation": "xiā 与 jiā 声母不同（x 与 j），意思是看不见。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是指甲。"}], "explanations": {"夹": "夹 jiā（第一声）：用筷子、手指等两个部分把东西按住拿起。", "价": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "将": "jiāng 与 jiā 韵母不同（a 与 ang），意思是将要、把。", "间": "jiān 与 jiā 韵母不同（a 与 an），意思是中间、房间。", "瞎": "xiā 与 jiā 声母不同（x 与 j），意思是看不见。", "甲": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是指甲。"}, "sentence_index": null, "correct_answer": "夹"}, "level_3": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹紧：用两腿把马肚子夹住，符合句意。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”是抬脚撞击，不能说“踢紧了马肚子”。"}, {"text": "搂", "is_correct": false, "explanation": "语义：“搂”是用胳膊环抱，与“用两腿”不合，句子不通。"}, {"text": "握", "is_correct": false, "explanation": "语义：“握”是用手抓持，不能用两腿来握。"}], "explanations": {"夹": "夹紧：用两腿把马肚子夹住，符合句意。", "踢": "搭配：“踢”是抬脚撞击，不能说“踢紧了马肚子”。", "搂": "语义：“搂”是用胳膊环抱，与“用两腿”不合，句子不通。", "握": "语义：“握”是用手抓持，不能用两腿来握。"}, "sentence_index": 6, "correct_answer": "夹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他夹了一管牙膏。", "explanation": "这里应该用〈挤〉。夹是用两面按住，挤牙膏是用力压出，应说“挤”。"}, {"text": "医生夹了我一针。", "explanation": "这里应该用〈扎〉。夹是两面按住或放入两物之间，打针是刺入皮肤，应说“扎”。"}, {"text": "他夹下了开关。", "explanation": "这里应该用〈按〉。夹要用两面按住或放入两物之间，压下开关应说“按”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用镊子夹了住那根刺。", "corrected_sentence": "我用镊子夹住了那根刺。", "error_description": "错误形式是“夹了住”，正确形式是“夹住了”。补语“住”要紧跟在动词“夹”后面，“了”放在句尾，不能插在“夹”和“住”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用钳子夹了着一根钉子。", "corrected_sentence": "她用钳子夹着一根钉子。", "error_description": "错误形式是“夹了着”，正确形式是“夹着”。“着”表示动作持续，不能与“了”同时用在动词后，应说“夹着一根钉子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
