INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从两边用力按住或挟住；也指放入两物之间。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "他把一张照片夹在书里。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在笔记本里夹了一张书签。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包中间夹着一片火腿。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别让车门夹到手。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把信夹在日记本里。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他腋下夹着一把雨伞。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里夹着一张旧车票。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门夹住了弟弟的手指。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在两页纸中间夹一张卡片。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课本里夹了好几张纸条。", "target_word": "夹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夹了", "label": "完成体"}, {"form": "夹着", "label": "持续体"}, {"form": "夹过", "label": "经历体"}, {"form": "夹住", "label": "复合"}], "register": "中性", "sense_fingerprint": "夹：把东西放进两物之间，或被两边的东西按住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹 jiā（第一声）：用两物按住，或放入两物之间。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。"}, {"text": "交", "is_correct": false, "explanation": "jiāo 与 jiā 韵母不同（a 与 ao），意思是交给、交付。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 jiā 声母不同（q 与 j），意思是用指甲或手指按压。"}], "explanations": {"夹": "夹 jiā（第一声）：用两物按住，或放入两物之间。", "价": "jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的。", "交": "jiāo 与 jiā 韵母不同（a 与 ao），意思是交给、交付。", "掐": "qiā 与 jiā 声母不同（q 与 j），意思是用指甲或手指按压。"}, "sentence_index": null, "correct_answer": "夹"}, "level_3": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹在书里：把照片放进两页纸之间，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，照片不能吃，句子不通。"}, {"text": "撕", "is_correct": false, "explanation": "配价：“撕”不带“在书里”这样的处所补语，不能说“撕在书里”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”后面不接“在书里”，不说“洗在书里”。"}], "explanations": {"夹": "夹在书里：把照片放进两页纸之间，符合句意。", "吃": "语义：“吃”指把食物咽下去，照片不能吃，句子不通。", "撕": "配价：“撕”不带“在书里”这样的处所补语，不能说“撕在书里”。", "洗": "搭配：“洗”后面不接“在书里”，不说“洗在书里”。"}, "sentence_index": 0, "correct_answer": "夹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把牛奶夹进杯子里。", "explanation": "这里应该用〈倒〉。夹要求用两面挤压或放入两物之间，液体倒进杯子应说“倒”，不说“夹”。"}, {"text": "他把钥匙夹在桌上。", "explanation": "这里应该用〈放〉。夹是用两面按住或放入两物之间，钥匙只是搁在桌面上，应说“放”。"}, {"text": "她把一盆花夹在窗台上。", "explanation": "这里应该用〈摆〉。夹指从两边用力按住或放入两物之间，花盆只是放在窗台上，应说“摆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96344, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夹", "is_correct": true, "explanation": "夹 jiā（第一声）：用两物按住，或放入两物之间。"}, {"text": "间", "is_correct": false, "explanation": "jiān 与 jiā 韵母不同（a 与 an），意思是房间、中间。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 jiā 韵母不同（a 与 ang），意思是江河。"}, {"text": "瞎", "is_correct": false, "explanation": "xiā 与 jiā 声母不同（x 与 j），意思是看不见。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}], "explanations": {"夹": "夹 jiā（第一声）：用两物按住，或放入两物之间。", "间": "jiān 与 jiā 韵母不同（a 与 an），意思是房间、中间。", "江": "jiāng 与 jiā 韵母不同（a 与 ang），意思是江河。", "瞎": "xiā 与 jiā 声母不同（x 与 j），意思是看不见。", "驾": "jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "夹"}, "level_3": {"options": [{"text": "夹", "is_correct": true, "explanation": "书里夹着一张旧车票：车票被夹在书页之间，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住，书里的车票不能被咬着。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指咀嚼食物，车票不能嚼，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”要接被擦拭的表面，不能说“书里擦着一张车票”。"}], "explanations": {"夹": "书里夹着一张旧车票：车票被夹在书页之间，符合句意。", "咬": "语义：“咬”指用牙齿咬住，书里的车票不能被咬着。", "嚼": "语义：“嚼”指咀嚼食物，车票不能嚼，句子不通。", "擦": "搭配：“擦”要接被擦拭的表面，不能说“书里擦着一张车票”。"}, "sentence_index": 6, "correct_answer": "夹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话总爱夹着英语。", "explanation": "这里是“夹杂”（混入）的意思，与本义“从两边用力按住或放入两物之间”无关，不能用于此义。"}, {"text": "他把衣服夹进了洗衣机。", "explanation": "这里应该用〈放〉。夹指把东西放进两物之间或从两边按住，衣服放进洗衣机应说“放”。"}, {"text": "她把汤夹到碗里。", "explanation": "这里应该用〈盛〉。汤是液体，不能放在两物之间按住，应说“盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一张地图夹着在信封里。", "corrected_sentence": "我把一张地图夹在信封里。", "error_description": "错误形式是“夹着在信封里”，正确形式是“夹在信封里”。“把”字句中“夹”后面直接接“在＋处所”作补语，中间不能插入持续体标记“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把书签夹了在日记本里了。", "corrected_sentence": "我把书签夹在日记本里了。", "error_description": "错误形式是“夹了在日记本里了”，正确形式是“夹在日记本里了”。“了”不能插在“夹”和介词“在”之间，应放在句末，表示“夹”的动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
