INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结婚的时候，女孩子自己的家人。", "primary_collocate": null, "pronunciation": "nǚ jiā", "ipa": "ny˨˩˦ tɕja˥", "syllable_count": 2, "sentences": [{"text": "结婚那天，女家来了很多亲戚。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家的人都很高兴。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家和女家的人都很熟。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼前，男方要去拜访女家的长辈。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家准备了很多嫁妆。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出嫁那天，女家的亲戚都来送行。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家和男家的人坐在一起吃饭。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚前，他先去见了女家的人。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家的客人也来参加婚礼了。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家的人都来送她上车。", "target_word": "女家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "婚礼时新娘自己的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女家", "is_correct": true, "explanation": "正确。女家指结婚时新娘一方的家人，这里是“来了很多亲戚”的主语。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是仪式，不是人，不能“来”出一群亲戚。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不是能来人的一方，“来了很多亲戚”无法指它。"}, {"text": "工厂", "is_correct": false, "explanation": "配价：“来”的主语需要是人或集体，工厂作主语说“来了亲戚”不合理。"}], "explanations": {"女家": "正确。女家指结婚时新娘一方的家人，这里是“来了很多亲戚”的主语。", "婚礼": "语义：婚礼是仪式，不是人，不能“来”出一群亲戚。", "教室": "语义：教室是场所，不是能来人的一方，“来了很多亲戚”无法指它。", "工厂": "配价：“来”的主语需要是人或集体，工厂作主语说“来了亲戚”不合理。"}, "sentence_index": 0, "correct_answer": "女家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她嫁到女家后，很少回娘家。", "explanation": "这里应该用〈婆家〉。女家指新娘一方的家庭，新娘出嫁后嫁入的是男方家庭，所以不能说“嫁到女家”。"}, {"text": "她回女家住了几天，然后就回去了。", "explanation": "这里应该用〈娘家〉。女家只指结婚典礼时新娘一方的家人，出嫁后回去探望要说娘家。"}, {"text": "两家是女家，经常一起吃饭。", "explanation": "这里应该用〈亲家〉。女家只指新娘一方，不能用来表示两家之间的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女家", "is_correct": true, "explanation": "正确。女家指新娘一方的家人，与“男家”相对，句中是两家人坐在一起吃饭。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不能与人一起坐下吃饭，句子读不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能与人并列坐下吃饭，与句意完全不合。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“和……坐在一起吃饭”接的是人，医院是场所，不能这样搭配。"}], "explanations": {"女家": "正确。女家指新娘一方的家人，与“男家”相对，句中是两家人坐在一起吃饭。", "学校": "语义：学校是机构，不能与人一起坐下吃饭，句子读不通。", "电脑": "语义：电脑不能与人并列坐下吃饭，与句意完全不合。", "医院": "搭配：“和……坐在一起吃饭”接的是人，医院是场所，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "女家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新郎的父母是女家，他们很高兴。", "explanation": "这里应该用〈男家〉。女家指新娘一方，新郎的父母是男家。"}, {"text": "她结婚十年了，今天回女家看父母。", "explanation": "这里应该用〈娘家〉。女家只用于婚事中指新娘一方，婚后回自己父母家说娘家。"}, {"text": "这个家里只有女人，所以叫女家。", "explanation": "这里的〈女家〉被误解为女人的家。女家只指结婚时新娘一方的家人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新郎的父亲是女家的长辈。", "corrected_sentence": "新娘的父亲是女家的长辈。", "error_description": "错误：“新郎”；正确：“新娘”。女家指新娘一方的家人，新郎的父亲属于男家，不是女家的长辈。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "婚礼那天，新郎的妈妈代表女家讲了话。", "corrected_sentence": "婚礼那天，新娘的妈妈代表女家讲了话。", "error_description": "错误：“新郎”；正确：“新娘”。女家是新娘一方，只有新娘的家人才能代表女家。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
