INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96347, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "做事很用心，很小心地。", "primary_collocate": null, "pronunciation": "hǎo shēng", "ipa": "xaʊ̯˨˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "你要好生照顾奶奶。", "target_word": "好生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件瓷器很贵，请好生保管。", "target_word": "好生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把客人好生招待了一番。", "target_word": "好生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们好生爱护公共的东西。", "target_word": "好生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，你要好生养伤，别乱动。", "target_word": "好生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把这封信好生收了起来。", "target_word": "好生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你好生看着孩子，别让他跑远了。", "target_word": "好生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是爷爷留下的表，你要好生收着。", "target_word": "好生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好生对待每一位来客。", "target_word": "好生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些花很娇贵，要好生浇水。", "target_word": "好生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "做事用心小心地（照顾、保管等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好生", "is_correct": true, "explanation": "正确：“好生”是副词，表示做事很用心、很小心，与“照顾奶奶”相合。"}, {"text": "草草", "is_correct": false, "explanation": "语义：“草草”指随便敷衍，与“照顾奶奶”要用心的意思矛盾。"}, {"text": "狠狠", "is_correct": false, "explanation": "搭配：“狠狠”多修饰“打”“骂”等动作，不修饰“照顾”。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”指随意、没有章法，与“照顾奶奶”要细心的意思矛盾。"}], "explanations": {"好生": "正确：“好生”是副词，表示做事很用心、很小心，与“照顾奶奶”相合。", "草草": "语义：“草草”指随便敷衍，与“照顾奶奶”要用心的意思矛盾。", "狠狠": "搭配：“狠狠”多修饰“打”“骂”等动作，不修饰“照顾”。", "乱": "语义：“乱”指随意、没有章法，与“照顾奶奶”要细心的意思矛盾。"}, "sentence_index": 0, "correct_answer": "好生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他好生把钥匙落在了车上，回家才发现。", "explanation": "这里应该用〈大意〉。好生表示做事很用心、小心，与“把钥匙落在车上”矛盾；做事疏忽、不小心要说“大意”。"}, {"text": "他好生签了合同，连条款都没看。", "explanation": "这里应该用〈草率〉。好生表示做事很用心，与“连条款都没看”矛盾；做事不细致、随便应付要说“草率”。"}, {"text": "他随手把钥匙好生扔在路边。", "explanation": "这里应该用〈马虎〉。好生表示做事很用心，与“随手扔在路边”矛盾；做事不用心要说“马虎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好生", "is_correct": true, "explanation": "正确：“好生”表示小心用心地，与“看着孩子”相合。"}, {"text": "胡乱", "is_correct": false, "explanation": "语义：“胡乱”指随便、不认真，与“别让他跑远了”要认真看管的意思矛盾。"}, {"text": "懒洋洋", "is_correct": false, "explanation": "语义：“懒洋洋”指没精神、不上心，与“看着孩子”要用心的意思矛盾。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”多修饰“说”，不修饰“看着”这类动作。"}], "explanations": {"好生": "正确：“好生”表示小心用心地，与“看着孩子”相合。", "胡乱": "语义：“胡乱”指随便、不认真，与“别让他跑远了”要认真看管的意思矛盾。", "懒洋洋": "语义：“懒洋洋”指没精神、不上心，与“看着孩子”要用心的意思矛盾。", "随口": "搭配：“随口”多修饰“说”，不修饰“看着”这类动作。"}, "sentence_index": 6, "correct_answer": "好生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他好生把孩子一个人丢在家里。", "explanation": "这里应该用〈疏忽〉。好生表示做事很用心，与“把孩子一个人丢在家里”矛盾；不照看、不在意要说“疏忽”。"}, {"text": "她好生打碎了那只瓷碗，也没有道歉。", "explanation": "这里应该用〈不小心〉。好生表示小心用心，与“打碎了瓷碗”矛盾；不当心弄坏东西要说“不小心”。"}, {"text": "这些文件他好生丢在地上，没人去捡。", "explanation": "这里应该用〈随便〉。好生表示做事很用心、小心，与“丢在地上”矛盾；随手乱放、不当回事要说“随便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些药很贵，你要很好生收着。", "corrected_sentence": "这些药很贵，你要好生收着。", "error_description": "“好生”本身是副词，前面不能再加程度副词“很”，应去掉“很”，说“你要好生收着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子很调皮，你要好生的看着他。", "corrected_sentence": "孩子很调皮，你要好生看着他。", "error_description": "“好生”是副词，修饰动词时不加“的”，应说“好生看着他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
