INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校给每个学生的一串数字，用来分清是谁。", "primary_collocate": null, "pronunciation": "xué hào", "ipa": "ɕɥe˧˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我的学号是二零二三零五。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我：你的学号是多少？", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个学生都有自己的学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带学生卡，只好告诉老师我的学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一下成绩单上的学号，别写错。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前，要先在卷子上写学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的学号最后一位是八。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用学号叫同学上台。", "target_word": "学号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校用学号分清每一个学生。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把学号告诉了管理员，就进图书馆了。", "target_word": "学号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校发给每个学生、用来分清身份的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学号", "is_correct": true, "explanation": "正确：“学号”是学校给学生的编号，可以说“是二零二三零五”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不是一串像学号那样的编号，“我的年龄是二零二三零五”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的分量，不能用一串编号来表示。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高矮，与编号无关，不能说“身高是二零二三零五”。"}], "explanations": {"学号": "正确：“学号”是学校给学生的编号，可以说“是二零二三零五”。", "年龄": "语义：年龄是人的岁数，不是一串像学号那样的编号，“我的年龄是二零二三零五”说不通。", "体重": "语义：体重是身体的分量，不能用一串编号来表示。", "身高": "语义：“身高”指身体的高矮，与编号无关，不能说“身高是二零二三零五”。"}, "sentence_index": 0, "correct_answer": "学号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司给每位员工编了学号。", "explanation": "这里应该用〈工号〉。员工的编号称工号，学号只指学校给学生的编号。"}, {"text": "银行卡背面印着学号。", "explanation": "这里应该用〈卡号〉。银行卡上的号码称卡号，学号只用于学生。"}, {"text": "这批货物都有学号。", "explanation": "这里应该用〈编号〉。货物的顺序号一般说编号，学号专指学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学号", "is_correct": true, "explanation": "正确：“学号”是编号，可以说最后一位是几。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不能说“最后一位是八”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以数位数的编号，“最后一位是八”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是身体器官，不存在“最后一位”，此处说不通。"}], "explanations": {"学号": "正确：“学号”是编号，可以说最后一位是几。", "朋友": "语义：朋友是人，不能说“最后一位是八”。", "天气": "语义：天气不是可以数位数的编号，“最后一位是八”说不通。", "眼睛": "语义：“眼睛”是身体器官，不存在“最后一位”，此处说不通。"}, "sentence_index": 6, "correct_answer": "学号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她有一把学号，每天都带在身上。", "explanation": "这里应该用〈个〉。〈把〉用于有柄的东西，学号是一个编号，不能用“把”来计量。"}, {"text": "老师给我发了一条学号。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，学号不能用“条”来计量。"}, {"text": "学校给他分了一根学号。", "explanation": "这里应该用〈个〉。〈根〉用于细长的东西，学号不能用“根”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的学号换了过一次。", "corrected_sentence": "我的学号换过一次。", "error_description": "“了”与“过”不能同用。“换过”已表示曾经发生，中间加“了”不通，应为“我的学号换过一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一下子记得不住学号。", "corrected_sentence": "我一下子记不住学号。", "error_description": "补语错误：可能补语的否定形式是“记不住”，不能说“记得不住”，应为“我一下子记不住学号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
