INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96351, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数画、布这种又宽又平的东西时用的字。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu˧˥", "syllable_count": 1, "sentences": [{"text": "教室前面挂着一幅大地图。", "target_word": "幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用一幅红布做了一条裙子。", "target_word": "幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅布又宽又长。", "target_word": "幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子画了一幅全家人的画。", "target_word": "幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画太大，墙放不下。", "target_word": "幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上铺着一幅白布。", "target_word": "幅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在街上看到一幅很大的广告画。", "target_word": "幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一幅画送给了朋友。", "target_word": "幅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有三幅小画。", "target_word": "幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这幅蓝布很宽，可以做窗帘。", "target_word": "幅", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "称量画、布等又宽又平的东西的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幅", "is_correct": true, "explanation": "幅 fú（第二声）：量词，用于画、布等又宽又平的东西。"}, {"text": "富", "is_correct": false, "explanation": "富 fù（第四声）与 fú（第二声）声调不同，意思是富有。"}, {"text": "府", "is_correct": false, "explanation": "府 fǔ（第三声）与 fú（第二声）声调不同，意思是府第。"}, {"text": "付", "is_correct": false, "explanation": "付 fù（第四声）与 fú（第二声）声调不同，意思是付钱。"}, {"text": "夫", "is_correct": false, "explanation": "夫 fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}], "explanations": {"幅": "幅 fú（第二声）：量词，用于画、布等又宽又平的东西。", "富": "富 fù（第四声）与 fú（第二声）声调不同，意思是富有。", "府": "府 fǔ（第三声）与 fú（第二声）声调不同，意思是府第。", "付": "付 fù（第四声）与 fú（第二声）声调不同，意思是付钱。", "夫": "夫 fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, "sentence_index": null, "correct_answer": "幅"}, "level_3": {"options": [{"text": "幅", "is_correct": true, "explanation": "幅：量词，用于地图等又宽又平的东西，与“一幅大地图”搭配正确。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、房屋等大型固定物，不能计量地图。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，地图不是细长物。"}, {"text": "册", "is_correct": false, "explanation": "搭配：“册”用于书籍，挂在教室墙上的地图不是书册。"}], "explanations": {"幅": "幅：量词，用于地图等又宽又平的东西，与“一幅大地图”搭配正确。", "座": "搭配：“座”用于山、桥、房屋等大型固定物，不能计量地图。", "条": "搭配：“条”用于细长的东西，地图不是细长物。", "册": "搭配：“册”用于书籍，挂在教室墙上的地图不是书册。"}, "sentence_index": 0, "correct_answer": "幅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家里有一幅床。", "explanation": "这里应该用〈张〉。幅用于画、布等又宽又平的东西，床要用张。"}, {"text": "我买了一幅鞋。", "explanation": "这里应该用〈双〉。幅不能计量鞋，鞋要用双。"}, {"text": "门口停着一幅车。", "explanation": "这里应该用〈辆〉。幅不能计量车，车要用辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "幅", "is_correct": true, "explanation": "幅 fú（第二声）：量词，用于画、布等又宽又平的东西。"}, {"text": "父", "is_correct": false, "explanation": "父 fù（第四声）与 fú（第二声）声调不同，意思是父亲。"}, {"text": "斧", "is_correct": false, "explanation": "斧 fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。"}, {"text": "辅", "is_correct": false, "explanation": "辅 fǔ（第三声）与 fú（第二声）声调不同，意思是辅助。"}, {"text": "副", "is_correct": false, "explanation": "副 fù（第四声）与 fú（第二声）声调不同，意思是副手或副本。"}], "explanations": {"幅": "幅 fú（第二声）：量词，用于画、布等又宽又平的东西。", "父": "父 fù（第四声）与 fú（第二声）声调不同，意思是父亲。", "斧": "斧 fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。", "辅": "辅 fǔ（第三声）与 fú（第二声）声调不同，意思是辅助。", "副": "副 fù（第四声）与 fú（第二声）声调不同，意思是副手或副本。"}, "sentence_index": null, "correct_answer": "幅"}, "level_3": {"options": [{"text": "幅", "is_correct": true, "explanation": "幅：量词，用于广告画等又宽又平的东西，与“一幅广告画”搭配正确。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，广告画不是书册。"}, {"text": "部", "is_correct": false, "explanation": "搭配：“部”用于影视、书籍、机器等，不能计量广告画。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对事物中的一个，不能计量广告画。"}], "explanations": {"幅": "幅：量词，用于广告画等又宽又平的东西，与“一幅广告画”搭配正确。", "本": "搭配：“本”用于书册，广告画不是书册。", "部": "搭配：“部”用于影视、书籍、机器等，不能计量广告画。", "只": "搭配：“只”用于动物或成对事物中的一个，不能计量广告画。"}, "sentence_index": 6, "correct_answer": "幅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一幅狗。", "explanation": "这里应该用〈只〉。幅不能计量动物，狗要用只。"}, {"text": "我喝了一幅水。", "explanation": "这里应该用〈杯〉。幅不能计量水，喝水要用杯。"}, {"text": "桌上有一幅笔。", "explanation": "这里应该用〈支〉。幅不能计量笔，笔要用支。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家门口停着一幅新车。", "corrected_sentence": "我们家门口停着一辆新车。", "error_description": "量词“幅”用于画、布等又宽又平的东西，不能计量车：应为“一辆新车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一幅椅子。", "corrected_sentence": "我买了一把椅子。", "error_description": "量词“幅”不能计量“椅子”：应为“一把椅子”，不能说“一幅椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
