INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "包庇或收留某人，使其不受追究或伤害。", "primary_collocate": null, "pronunciation": "bì hù", "ipa": "pi˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "国家庇护了这些难民。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他庇护罪犯，自己也犯了法。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能因为是亲戚就庇护他。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板一直庇护着犯错的员工。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家愿意庇护逃出来的人。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不应该庇护犯错的孩子。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他庇护朋友，不肯说出真相。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他庇护了一个逃犯。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在背后庇护他，他才敢这样做。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不会庇护做错事的学生。", "target_word": "庇护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "庇护了", "label": "完成体"}, {"form": "庇护着", "label": "持续体"}, {"form": "庇护过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "庇护：包庇或收留某人，使其不受追究或伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96354, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庇护", "is_correct": true, "explanation": "庇护 bì hù（第四声）：包庇或收留某人，使其不受追究或伤害。"}, {"text": "闭幕", "is_correct": false, "explanation": "bì mù 与 bì hù 第二个音节声母不同（m 与 h），意思是闭幕。"}, {"text": "避祸", "is_correct": false, "explanation": "bì huò 与 bì hù 第二个音节韵母不同（o 与 u），意思是躲避灾祸。"}, {"text": "壁画", "is_correct": false, "explanation": "bì huà 与 bì hù 第二个音节韵母不同（a 与 u），意思是墙上的绘画。"}, {"text": "避讳", "is_correct": false, "explanation": "bì huì 与 bì hù 第二个音节韵母不同（uì 与 u），意思是避开忌讳的说法。"}], "explanations": {"庇护": "庇护 bì hù（第四声）：包庇或收留某人，使其不受追究或伤害。", "闭幕": "bì mù 与 bì hù 第二个音节声母不同（m 与 h），意思是闭幕。", "避祸": "bì huò 与 bì hù 第二个音节韵母不同（o 与 u），意思是躲避灾祸。", "壁画": "bì huà 与 bì hù 第二个音节韵母不同（a 与 u），意思是墙上的绘画。", "避讳": "bì huì 与 bì hù 第二个音节韵母不同（uì 与 u），意思是避开忌讳的说法。"}, "sentence_index": null, "correct_answer": "庇护"}, "level_3": {"options": [{"text": "庇护", "is_correct": true, "explanation": "庇护：国家收留并保护这些难民，符合句意。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是用针线连接织物，不能用来指国家与难民，句子不通。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”后接颜料、油等，不能说“涂了这些难民”。"}, {"text": "掷", "is_correct": false, "explanation": "语义：“掷”指投掷物品，不能用于人，句子不通。"}], "explanations": {"庇护": "庇护：国家收留并保护这些难民，符合句意。", "缝": "语义：“缝”是用针线连接织物，不能用来指国家与难民，句子不通。", "涂": "搭配：“涂”后接颜料、油等，不能说“涂了这些难民”。", "掷": "语义：“掷”指投掷物品，不能用于人，句子不通。"}, "sentence_index": 0, "correct_answer": "庇护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那笔钱庇护在床下。", "explanation": "这里应该用〈隐藏〉。庇护的对象是人或生物，钱不能被庇护，藏钱要说“隐藏”。"}, {"text": "他一心想庇护事实。", "explanation": "这里应该用〈掩盖〉。庇护的对象是人或生物，不能用于“事实”，掩盖事实要说“掩盖”。"}, {"text": "他庇护了桌上的那杯茶。", "explanation": "这里应该用〈放〉。庇护的对象是人或生物，茶杯只是放在桌上，应说“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96354, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "庇护", "is_correct": true, "explanation": "庇护 bì hù（第四声）：包庇或收留某人，使其不受追究或伤害。"}, {"text": "壁虎", "is_correct": false, "explanation": "bì hǔ 与 bì hù 第二个音节声调不同（第三声与第四声），意思是一种爬行动物。"}, {"text": "闭目", "is_correct": false, "explanation": "bì mù 与 bì hù 第二个音节声母不同（m 与 h），意思是闭上眼睛。"}, {"text": "避祸", "is_correct": false, "explanation": "bì huò 与 bì hù 第二个音节韵母不同（o 与 u），意思是躲避灾祸。"}], "explanations": {"庇护": "庇护 bì hù（第四声）：包庇或收留某人，使其不受追究或伤害。", "壁虎": "bì hǔ 与 bì hù 第二个音节声调不同（第三声与第四声），意思是一种爬行动物。", "闭目": "bì mù 与 bì hù 第二个音节声母不同（m 与 h），意思是闭上眼睛。", "避祸": "bì huò 与 bì hù 第二个音节韵母不同（o 与 u），意思是躲避灾祸。"}, "sentence_index": null, "correct_answer": "庇护"}, "level_3": {"options": [{"text": "庇护", "is_correct": true, "explanation": "庇护：他包庇朋友，不肯说出真相，符合句意。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变成液体，不能用于人，句子不通。"}, {"text": "揭发", "is_correct": false, "explanation": "语义：“揭发”就是说出隐情，与“不肯说出真相”矛盾。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的宾语是火、蜡烛等可燃物，不能说“点燃朋友”。"}], "explanations": {"庇护": "庇护：他包庇朋友，不肯说出真相，符合句意。", "熔化": "语义：“熔化”指固体受热变成液体，不能用于人，句子不通。", "揭发": "语义：“揭发”就是说出隐情，与“不肯说出真相”矛盾。", "点燃": "搭配：“点燃”的宾语是火、蜡烛等可燃物，不能说“点燃朋友”。"}, "sentence_index": 6, "correct_answer": "庇护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他庇护着这些文件。", "explanation": "这里应该用〈保管〉。庇护的对象是人或生物，文件应说“保管”。"}, {"text": "他庇护了自己的病情。", "explanation": "这里应该用〈隐瞒〉。庇护的对象是人或生物，病情不能被庇护，隐瞒病情要说“隐瞒”。"}, {"text": "他庇护了很多古董。", "explanation": "这里应该用〈收藏〉。庇护的对象是人或生物，古董不能被庇护，收集保存古董要说“收藏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那个逃犯庇护很好。", "corrected_sentence": "他把那个逃犯庇护得很好。", "error_description": "错误形式是“庇护很好”，正确形式是“庇护得很好”。动词和“很好”之间的补语要用“得”连接，不能直接说“庇护很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这群老师一直庇护了着受欺负的学生。", "corrected_sentence": "这群老师一直庇护着受欺负的学生。", "error_description": "错误形式是“庇护了着”，正确形式是“庇护着”。“着”表示动作持续，不能与“了”同时用在动词后，应说“庇护着受欺负的学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
