INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96355, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "别人不愿意，还硬要做。", "primary_collocate": null, "pronunciation": "qiáng xíng", "ipa": "tɕʰiɑŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他不想去，你别强行拉他去。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿意说，我们不要强行问她。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想吃，妈妈没有强行让他吃。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板强行要大家周末来公司加班。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友不想喝酒，他却强行给朋友倒了一杯。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不肯搬家，儿子也不能强行让他搬。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不同意，他还是强行替她做了决定。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别强行改变别人的习惯，这样不好。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王不想唱歌，同事却强行把话筒递给他。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能强行让孩子学他不喜欢的东西。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；对方不愿意，仍然硬要去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强行", "is_correct": true, "explanation": "正确。“强行”表示不顾对方不愿意，硬要拉他去，与“他不想去”呼应。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”表示出于本人意愿，与“他不想去”矛盾，句子不合情理。"}, {"text": "轻松地", "is_correct": false, "explanation": "搭配：“轻松”描述不费力，与“硬拉他去”的强迫语境不合，句子读来别扭。"}, {"text": "客气地", "is_correct": false, "explanation": "搭配：“客气”多用于待人的态度，不能说“客气地拉人去”。"}], "explanations": {"强行": "正确。“强行”表示不顾对方不愿意，硬要拉他去，与“他不想去”呼应。", "自愿": "语义：“自愿”表示出于本人意愿，与“他不想去”矛盾，句子不合情理。", "轻松地": "搭配：“轻松”描述不费力，与“硬拉他去”的强迫语境不合，句子读来别扭。", "客气地": "搭配：“客气”多用于待人的态度，不能说“客气地拉人去”。"}, "sentence_index": 0, "correct_answer": "强行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作很轻松，他强行把它接了过去。", "explanation": "这里应该用〈主动〉。强行表示违背他人意愿，没有人反对、工作又轻松时不能用“强行”。"}, {"text": "我们都没有意见，他却强行同意了这个方案。", "explanation": "这里应该用〈自愿〉。强行强调违背他人的反对，别人没有反对时不能用“强行”。"}, {"text": "事情进行得很顺利，他却强行完成了任务。", "explanation": "这里应该用〈轻松地〉。强行表示遇到阻碍而硬做，事情很顺利时不能用“强行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强行", "is_correct": true, "explanation": "正确。“强行”表示不顾她的不同意，仍替她做决定，与“她不同意”呼应。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，不能修饰动词“替她做决定”。"}, {"text": "感激地", "is_correct": false, "explanation": "语义：“感激”表示对帮助的谢意，与替她做主的情境不合，也与“她不同意”矛盾。"}, {"text": "很高", "is_correct": false, "explanation": "语义：“很高”形容高度，不能修饰“替她做了决定”。"}], "explanations": {"强行": "正确。“强行”表示不顾她的不同意，仍替她做决定，与“她不同意”呼应。", "桌子": "词性：“桌子”是名词，不能修饰动词“替她做决定”。", "感激地": "语义：“感激”表示对帮助的谢意，与替她做主的情境不合，也与“她不同意”矛盾。", "很高": "语义：“很高”形容高度，不能修饰“替她做了决定”。"}, "sentence_index": 6, "correct_answer": "强行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都很支持他的决定，他强行表示同意。", "explanation": "这里应该用〈坚决〉。强行表示违背他人意愿，大家都支持、他表示同意时不能用“强行”。"}, {"text": "这是一个很好的机会，他却强行放弃了。", "explanation": "这里应该用〈主动〉。强行表示违背意愿，放弃机会是自己的选择时不能用“强行”。"}, {"text": "他身体很好，却强行住进了医院。", "explanation": "这里应该用〈执意〉。强行表示违背他人意愿，他没有反对住院时不能用“强行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别强行的拉他回家。", "corrected_sentence": "你别强行拉他回家。", "error_description": "结构助词错误：副词“强行”修饰动词时不用“的”，应直接说“强行拉他回家”，去掉多余的“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他强行的替我做了决定。", "corrected_sentence": "他强行替我做了决定。", "error_description": "错误：“强行的替我”；正确：“强行替我”。副词“强行”直接修饰动词，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用强力迫使进行；不顾对方意愿而为。", "primary_collocate": null, "pronunciation": "qiáng xíng", "ipa": "tɕʰiɑŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小偷强行打开了那扇门。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机强行超车，差点出了事故。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察强行带走了那个闹事的人。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，我只好强行关机。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强行推开人群，冲到了前面。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方不让进，他们却强行闯了进去。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件会强行弹出很多广告。", "target_word": "强行", "complexity_tier": "T3", "furigana": "zhè ge ruǎn jiàn huì qiáng xíng tán chū hěn duō guǎng gào", "sentence_source": "generated"}, {"text": "天气不好，船长却强行出海。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强行拉着我上了车。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不能强行收学生的钱。", "target_word": "强行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；用强力或强硬手段迫使事情进行，不顾阻碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强行", "is_correct": true, "explanation": "正确。“强行”表示用强力迫使开门，与“小偷”撬门的行为相符。"}, {"text": "恭敬地", "is_correct": false, "explanation": "语义：“恭敬”表示尊重有礼，与小偷开门的行为相反，句子不合情理。"}, {"text": "礼貌地", "is_correct": false, "explanation": "语义：“礼貌”是有礼的态度，与小偷的行为矛盾，句子不通。"}, {"text": "友好地", "is_correct": false, "explanation": "搭配：“友好”多用于交往的态度，不能修饰“打开门”这样的动作。"}], "explanations": {"强行": "正确。“强行”表示用强力迫使开门，与“小偷”撬门的行为相符。", "恭敬地": "语义：“恭敬”表示尊重有礼，与小偷开门的行为相反，句子不合情理。", "礼貌地": "语义：“礼貌”是有礼的态度，与小偷的行为矛盾，句子不通。", "友好地": "搭配：“友好”多用于交往的态度，不能修饰“打开门”这样的动作。"}, "sentence_index": 0, "correct_answer": "强行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门一推就开，他却强行把它推开了。", "explanation": "这里应该用〈轻轻地〉。强行表示用强力迫使进行，门一推就开时不需要用强力，不能用“强行”。"}, {"text": "这张纸很薄，他却强行把它撕开了。", "explanation": "这里应该用〈随手〉。强行强调用强力硬做，纸很薄、轻轻一撕就开时不能用“强行”。"}, {"text": "这道题很简单，他强行做出了答案。", "explanation": "这里应该用〈轻松〉。强行表示遇到阻碍而硬做，题目简单时不能用“强行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强行", "is_correct": true, "explanation": "正确。“强行”表示用强力让广告弹出，与“软件会”的行为相符。"}, {"text": "温柔地", "is_correct": false, "explanation": "语义：“温柔”形容性情或动作轻柔，与软件强制弹出广告的行为不合。"}, {"text": "耐心地", "is_correct": false, "explanation": "语义：“耐心”指有耐性地做事，与弹出广告这一行为不合。"}, {"text": "精心地", "is_correct": false, "explanation": "语义：“精心”指细致用心地做好某事，与强制弹出广告的行为不合。"}], "explanations": {"强行": "正确。“强行”表示用强力让广告弹出，与“软件会”的行为相符。", "温柔地": "语义：“温柔”形容性情或动作轻柔，与软件强制弹出广告的行为不合。", "耐心地": "语义：“耐心”指有耐性地做事，与弹出广告这一行为不合。", "精心地": "语义：“精心”指细致用心地做好某事，与强制弹出广告的行为不合。"}, "sentence_index": 6, "correct_answer": "强行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很想去，大家却强行劝他留下。", "explanation": "这里应该用〈再三〉。强行表示用强力迫使进行，劝说不需要强力，不能用“强行”。"}, {"text": "朋友请他吃饭，他高高兴兴地强行答应了。", "explanation": "这里应该用〈爽快地〉。强行表示用强力迫使进行，自己高兴地答应邀请不需要强力，不能用“强行”。"}, {"text": "大家都同意这个方案，他却强行表示赞成。", "explanation": "这里应该用〈欣然〉。强行表示违背意愿，大家都同意、他表示赞成时不能用“强行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机强行的把车开走了。", "corrected_sentence": "司机强行地把车开走了。", "error_description": "结构助词错误：副词“强行”修饰动词时应用“地”，不用“的”，应把“强行的把车”改为“强行地把车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们强行着闯进了大门。", "corrected_sentence": "他们强行闯进了大门。", "error_description": "体标误用：“强行”是副词，后面不能加“着”。应删去“着”，说“强行闯进了大门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
