INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96357, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里很坏很可怕的怪物。", "primary_collocate": null, "pronunciation": "è mó", "ipa": "ɤ˥˩ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的恶魔长着尖角，很可怕。", "target_word": "恶魔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个恶魔长着两只红眼睛。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王子打败了山洞里的恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们害怕电影里的恶魔。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里说，恶魔住在黑暗的森林里。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在游戏里杀死了一个大恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恶魔想把公主带到山上。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚梦到了一个恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多恶魔的画。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恶魔的样子又黑又丑。", "target_word": "恶魔", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "小恶魔", "label": "复合"}, {"form": "惡魔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "故事里很坏很可怕的怪物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天使", "is_correct": false, "explanation": "语义：天使是善良的神灵，与「很可怕」相反，句意不通。"}, {"text": "恶魔", "is_correct": true, "explanation": "正确：恶魔是传说中凶恶可怕的怪物，与「很可怕」相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不会是故事里令人害怕的角色。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会是故事里长着尖角的可怕角色。"}], "explanations": {"天使": "语义：天使是善良的神灵，与「很可怕」相反，句意不通。", "恶魔": "正确：恶魔是传说中凶恶可怕的怪物，与「很可怕」相符。", "面包": "语义：面包是食物，不会是故事里令人害怕的角色。", "桌子": "语义：桌子是家具，不会是故事里长着尖角的可怕角色。"}, "sentence_index": 0, "correct_answer": "恶魔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的恶魔每天晚上都会巡视街道，保护居民的安全。", "explanation": "这里应该用〈守护神〉。守护神保护居民的安全；恶魔是凶恶的鬼怪，不会守护居民。"}, {"text": "勇敢的恶魔打败了山洞里的怪物，救出了村民。", "explanation": "这里应该用〈英雄〉。英雄是勇敢正义、救助他人的人；恶魔是凶恶的鬼怪，不会去救村民。"}, {"text": "这个恶魔做的饭很好吃，大家都夸他手艺好。", "explanation": "这里应该用〈厨师〉。厨师做饭、手艺好，是正面形象；恶魔是凶恶的鬼怪，做不出让大家夸赞的饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园是没有意识的地方，不可能想把公主带到山上。"}, {"text": "自行车", "is_correct": false, "explanation": "配价：「想」的主语须是能有意图的生物，自行车不能有想法。"}, {"text": "恶魔", "is_correct": true, "explanation": "正确：恶魔有意图，能够想把公主带走，与句意相符。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，与故事中有意图的角色不符。"}], "explanations": {"花园": "语义：花园是没有意识的地方，不可能想把公主带到山上。", "自行车": "配价：「想」的主语须是能有意图的生物，自行车不能有想法。", "恶魔": "正确：恶魔有意图，能够想把公主带走，与句意相符。", "面条": "语义：面条是食物，与故事中有意图的角色不符。"}, "sentence_index": 6, "correct_answer": "恶魔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "恶魔在天上为人们唱歌。", "explanation": "这里应该用〈天使〉。天使是善良的神灵，为人们唱歌是它的特征；恶魔是凶恶的鬼怪，与此不符。"}, {"text": "森林里住着一个恶魔，它喜欢帮助迷路的人。", "explanation": "这里应该用〈精灵〉。精灵常帮助迷路的人，恶魔是凶恶的鬼怪，这句的行为与恶魔的形象不合。"}, {"text": "恶魔在医院里救了很多病人。", "explanation": "这里应该用〈医生〉。在医院救治病人是医生的工作，恶魔不能替代医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城堡里住着一条恶魔。", "corrected_sentence": "城堡里住着一个恶魔。", "error_description": "量词错误：「恶魔」应搭配量词「个」，「条」多用于蛇、龙等细长的生物，用在这里不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森林深处住着一本恶魔。", "corrected_sentence": "森林深处住着一个恶魔。", "error_description": "量词错误：「恶魔」应搭配「个」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
