INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "传说中的凶恶鬼怪；比喻极其凶狠残忍的人。", "primary_collocate": null, "pronunciation": "è mó", "ipa": "ɤ˥˩ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "传说里，恶魔会吃人。", "target_word": "恶魔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个杀人的坏人是个恶魔。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争把他变成了恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人说他是恶魔。", "target_word": "恶魔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古书里写着恶魔的故事。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对孩子那么凶，简直是个恶魔。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏人残忍无情，人们把他叫作恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说有个恶魔住在海底。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老板对员工很残忍，大家都叫他恶魔。", "target_word": "恶魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个恶魔毁了很多家庭。", "target_word": "恶魔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小恶魔", "label": "复合"}, {"form": "惡魔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "传说中的凶恶鬼怪，也比喻极其凶狠残忍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜡烛", "is_correct": false, "explanation": "配价：「吃人」要求能行动的施事，蜡烛不能吃人。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使是善良的神灵，不会吃人，与传说的内容相反。"}, {"text": "恶魔", "is_correct": true, "explanation": "正确：传说中的恶魔会吃人，与句中的「传说里」相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用品，与「吃人」的传说无关，句意不通。"}], "explanations": {"蜡烛": "配价：「吃人」要求能行动的施事，蜡烛不能吃人。", "天使": "语义：天使是善良的神灵，不会吃人，与传说的内容相反。", "恶魔": "正确：传说中的恶魔会吃人，与句中的「传说里」相符。", "书包": "语义：书包是学习用品，与「吃人」的传说无关，句意不通。"}, "sentence_index": 0, "correct_answer": "恶魔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的恶魔每天耐心地给大家讲课，同学们都很喜欢他。", "explanation": "这里应该用〈老师〉。老师耐心教书，是正面形象；恶魔是凶狠残忍的人，与耐心讲课不符。"}, {"text": "恶魔每天细心地给病人量体温，病人都很感激他。", "explanation": "这里应该用〈护士〉。护士细心照顾病人，是正面形象；恶魔是凶狠残忍的人，不会细心照顾病人。"}, {"text": "这位恶魔每天给流浪的小猫喂食，还给它们盖上被子。", "explanation": "这里应该用〈好心人〉。给流浪小猫喂食、盖被子是善良的举动；恶魔是凶狠残忍的人，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "搭配：「叫作」后的称呼应体现人的特征，花瓶多指只有外表的人，与「坏人」不合。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使是美好的形象，与「坏人」相反，不适合作为对坏人的称呼。"}, {"text": "小猫", "is_correct": false, "explanation": "体貌：小猫常指可爱的小动物，外形和形象都不能作为对坏人的称呼。"}, {"text": "恶魔", "is_correct": true, "explanation": "正确：「恶魔」用来称呼残忍的坏人，与「坏人」相符。"}], "explanations": {"花瓶": "搭配：「叫作」后的称呼应体现人的特征，花瓶多指只有外表的人，与「坏人」不合。", "天使": "语义：天使是美好的形象，与「坏人」相反，不适合作为对坏人的称呼。", "小猫": "体貌：小猫常指可爱的小动物，外形和形象都不能作为对坏人的称呼。", "恶魔": "正确：「恶魔」用来称呼残忍的坏人，与「坏人」相符。"}, "sentence_index": 6, "correct_answer": "恶魔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "恶魔在火场里救出了孩子。", "explanation": "这里应该用〈消防员〉。在火场救人是消防员的职责，恶魔不能替代。"}, {"text": "恶魔在医院里救了很多病人。", "explanation": "这里应该用〈医生〉。在医院救治病人是医生的工作，恶魔不能替代医生。"}, {"text": "恶魔在街上扶起了摔倒的老人。", "explanation": "这里应该用〈好人〉。扶起摔倒的老人是善良的行为；恶魔是凶狠残忍的人，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一本恶魔。", "corrected_sentence": "他是一个恶魔。", "error_description": "量词错误：「恶魔」指人时应用「个」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本恶魔毁了我们村里很多家庭。", "corrected_sentence": "那个恶魔毁了我们村里很多家庭。", "error_description": "量词错误：「恶魔」应搭配「个」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
