INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "本来是想的或者梦里的，后来真的有了。", "primary_collocate": null, "pronunciation": "chéng zhēn", "ipa": "ʈʂʰɤŋ˧˥ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "他做梦都想有一辆车，现在成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她昨晚梦到的事情，今天成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的飞船，今天已经成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想象中的花园成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个奇怪的梦后来竟然成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前只能想一想的事，现在全都成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写的故事，在现实中成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候想的那个画面，长大后成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时梦见的那次环球旅行，后来成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的机器人慢慢成真了。", "target_word": "成真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成真了", "label": "体标"}], "register": "中性", "sense_fingerprint": "想象中或梦里的事物后来真的出现在现实中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成真", "is_correct": true, "explanation": "“成真”指想象中的事情变为现实，与“做梦都想”的内容相呼应。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指生命的诞生，不能用于句中成年人的愿望。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪等的变化，与句中的人和车不相符。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接收者和所送之物两个成分，句中缺少宾语。"}], "explanations": {"成真": "“成真”指想象中的事情变为现实，与“做梦都想”的内容相呼应。", "出生": "语义：“出生”指生命的诞生，不能用于句中成年人的愿望。", "融化": "语义：“融化”指冰雪等的变化，与句中的人和车不相符。", "送给": "配价：“送给”需要接收者和所送之物两个成分，句中缺少宾语。"}, "sentence_index": 0, "correct_answer": "成真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的作业终于成真了。", "explanation": "这里应该用〈完成〉。成真指想象或梦中的事情变为现实，作业做完应说完成。"}, {"text": "这道菜终于成真了。", "explanation": "这里应该用〈做好〉。成真指想象或梦中的事情变为现实，菜做好要说做好。"}, {"text": "这件衣服终于成真了。", "explanation": "这里应该用〈洗完〉。成真指想象或梦中的事情变为现实，衣服洗好要说洗完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成真", "is_correct": true, "explanation": "“成真”指书中想象的故事在现实中出现，与“在现实中”呼应，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：故事不会哭，“哭”要求有感情的人或动物作主语。"}, {"text": "脸红", "is_correct": false, "explanation": "语义：“脸红”是人的面部反应，主语须是人，故事不会脸红。"}, {"text": "生病", "is_correct": false, "explanation": "语义：故事不会生病，“生病”针对生命体。"}], "explanations": {"成真": "“成真”指书中想象的故事在现实中出现，与“在现实中”呼应，符合句意。", "哭": "语义：故事不会哭，“哭”要求有感情的人或动物作主语。", "脸红": "语义：“脸红”是人的面部反应，主语须是人，故事不会脸红。", "生病": "语义：故事不会生病，“生病”针对生命体。"}, "sentence_index": 6, "correct_answer": "成真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场考试终于成真了。", "explanation": "这里应该用〈结束〉。成真指想象或梦中的事物变为现实，考试这类活动结束要说结束。"}, {"text": "这局棋终于成真了。", "explanation": "这里应该用〈下完〉。成真指想象或梦中的事情变为现实，一局棋结束要说下完。"}, {"text": "这片稻田终于成真了。", "explanation": "这里应该用〈收割〉。成真指想象中的事物实现，稻子成熟后割下来要说收割。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做梦都想有一辆车，后来被成真了。", "corrected_sentence": "他做梦都想有一辆车，后来成真了。", "error_description": "错误在“被”：“成真”是不及物动词，不能用被动式。应写作“后来成真了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书里的故事，在现实中终于成真着。", "corrected_sentence": "书里的故事，在现实中终于成真了。", "error_description": "错误在“了”：“成真”表示变化已经完成，句末要用“了”，不能用“着”。应写作“书里的故事，在现实中终于成真了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
