INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96361, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打得很重，让它死掉。", "primary_collocate": null, "pronunciation": "dǎ sǐ", "ipa": "ta˨˩˦ sz̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他用拖鞋打死了一只蚊子。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拿报纸打死了一只苍蝇。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里打死了一条蛇。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用棍子打死了老鼠。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只蜘蛛太大，我一下就打死了它。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶拿着扇子，打死了桌上的苍蝇。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别把蜜蜂打死，它不会咬人。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起鞋，把爬上墙的蟑螂打死了。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天晚上，我在房间里打死了好几只蚊子。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王打死了咬他的那条蛇。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打死了", "label": "完成体"}, {"form": "打死过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "用东西重打小动物或虫子，使它死掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打死", "is_correct": true, "explanation": "正确：“打死”指用力打使蚊子死亡，与“用拖鞋”的动作相合。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”用于易碎的器物，不说摔碎蚊子。"}, {"text": "养大", "is_correct": false, "explanation": "语义：“养大”指抚养使其长大，与用拖鞋击打蚊子的动作不合。"}, {"text": "洗净", "is_correct": false, "explanation": "语义：“洗净”针对需要清洗的东西，与击打蚊子的意思不合。"}], "explanations": {"打死": "正确：“打死”指用力打使蚊子死亡，与“用拖鞋”的动作相合。", "摔碎": "搭配：“摔碎”用于易碎的器物，不说摔碎蚊子。", "养大": "语义：“养大”指抚养使其长大，与用拖鞋击打蚊子的动作不合。", "洗净": "语义：“洗净”针对需要清洗的东西，与击打蚊子的意思不合。"}, "sentence_index": 0, "correct_answer": "打死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用拖鞋把地上的碗打死了。", "explanation": "这里应该用〈打碎〉。打死只用于能死的生物，碗不会死，应该说打碎。"}, {"text": "他用锤子把石头打死了。", "explanation": "这里应该用〈砸碎〉。打死指使有生命的东西死亡，石头没有生命，只能说砸碎。"}, {"text": "他不小心打死了一个杯子。", "explanation": "这里应该用〈打碎〉。打死只用于能死的生物，杯子不会死，应该说打碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打死", "is_correct": true, "explanation": "正确：“打死”指打使蜜蜂死亡，“它不会咬人”说明不该伤害它。"}, {"text": "擦干", "is_correct": false, "explanation": "语义：“擦干”针对湿的东西，不用于蜜蜂，与句意不合。"}, {"text": "叠好", "is_correct": false, "explanation": "搭配：“叠好”用于衣物、纸张，不说叠好蜜蜂。"}, {"text": "刷亮", "is_correct": false, "explanation": "搭配：“刷亮”用于鞋子等器物的表面，不说刷亮蜜蜂。"}], "explanations": {"打死": "正确：“打死”指打使蜜蜂死亡，“它不会咬人”说明不该伤害它。", "擦干": "语义：“擦干”针对湿的东西，不用于蜜蜂，与句意不合。", "叠好": "搭配：“叠好”用于衣物、纸张，不说叠好蜜蜂。", "刷亮": "搭配：“刷亮”用于鞋子等器物的表面，不说刷亮蜜蜂。"}, "sentence_index": 6, "correct_answer": "打死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心打死了一面镜子。", "explanation": "这里应该用〈打碎〉。打死只用于能死的生物，镜子不会死，应该说打碎。"}, {"text": "他一拳把那扇木门打死了。", "explanation": "这里应该用〈打坏〉。打死指使有生命的东西死亡，木门没有生命，只能说打坏。"}, {"text": "他一脚把那把椅子打死了。", "explanation": "这里应该用〈踢坏〉。打死指使有生命的东西死亡，椅子没有生命，只能说踢坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用扇子打死着一只苍蝇。", "corrected_sentence": "我用扇子打死了一只苍蝇。", "error_description": "错误：“打死”是已完成的结果，后面应接表示完成的“了”，却用了持续体的“着”，成了“打死着”。正确：“打死了一只苍蝇”，“了”表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没打死了那只蟑螂。", "corrected_sentence": "他没打死那只蟑螂。", "error_description": "错误：否定句“没”后面不能加“了”，成了“没打死了”。正确：“没打死那只蟑螂”，否定时去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
