INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打击致死；用暴力使生命终止。", "primary_collocate": null, "pronunciation": "dǎ sǐ", "ipa": "ta˨˩˦ sz̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "坏人打死了那个年轻的保安。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了酒，打死了自己的邻居。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，是他打死了那位老人。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几个人打死了一个小偷，警察正在找他们。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气，就把同学打死了。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，有人在街上打死了一个人。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是故意的，可是真的打死了人。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打死了偷东西的工人，要坐牢。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他在打架时打死了对方。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗打死了看门的老人，拿走了钱。", "target_word": "打死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打死了", "label": "完成体"}, {"form": "打死过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "用暴力殴打，使人死亡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打死", "is_correct": true, "explanation": "正确：“打死”指用暴力使人死亡，与“坏人”的行为相合。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”用于器物的表面，不说擦亮保安。"}, {"text": "晒干", "is_correct": false, "explanation": "搭配：“晒干”用于衣物、粮食，不说晒干保安。"}, {"text": "修好", "is_correct": false, "explanation": "搭配：“修好”针对机器、器物，不说修好一个人。"}], "explanations": {"打死": "正确：“打死”指用暴力使人死亡，与“坏人”的行为相合。", "擦亮": "搭配：“擦亮”用于器物的表面，不说擦亮保安。", "晒干": "搭配：“晒干”用于衣物、粮食，不说晒干保安。", "修好": "搭配：“修好”针对机器、器物，不说修好一个人。"}, "sentence_index": 0, "correct_answer": "打死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在打架时打死了对方的手。", "explanation": "这里应该用〈打伤〉。打死指使人死亡，对方的手不能死，只能说打伤。"}, {"text": "他一棍子把那个旧闹钟打死了。", "explanation": "这里应该用〈砸坏〉。打死指使有生命的东西死亡，闹钟没有生命，只能说砸坏。"}, {"text": "他一生气，把桌子打死了。", "explanation": "这里应该用〈打坏〉。打死指致人死亡，桌子不会死，只能说打坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打死", "is_correct": true, "explanation": "正确：“打死”指暴力致人死亡，与“真的……了人”的结果相合。"}, {"text": "烤熟", "is_correct": false, "explanation": "语义：“烤熟”指加热至能吃，用在人身上不通。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、燃料，不说点燃人。"}, {"text": "拧干", "is_correct": false, "explanation": "搭配：“拧干”用于湿的衣物，不说拧干人。"}], "explanations": {"打死": "正确：“打死”指暴力致人死亡，与“真的……了人”的结果相合。", "烤熟": "语义：“烤熟”指加热至能吃，用在人身上不通。", "点燃": "搭配：“点燃”用于火、燃料，不说点燃人。", "拧干": "搭配：“拧干”用于湿的衣物，不说拧干人。"}, "sentence_index": 6, "correct_answer": "打死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心把那盏台灯打死了。", "explanation": "这里应该用〈摔坏〉。打死指使有生命的东西死亡，台灯没有生命，只能说摔坏。"}, {"text": "他一脚把那扇木门打死了。", "explanation": "这里应该用〈踢坏〉。打死指使有生命的东西死亡，木门没有生命，只能说踢坏。"}, {"text": "他一拳把那台旧收音机打死了。", "explanation": "这里应该用〈弄坏〉。打死指使有生命的东西死亡，收音机没有生命，只能说弄坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个强盗打死着一位老人。", "corrected_sentence": "那个强盗打死了一位老人。", "error_description": "错误：“打死”是已完成的结果，后面应接表示完成的“了”，却用了持续体的“着”，成了“打死着”。正确：“打死了一位老人”，“了”表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没打死了那个老人。", "corrected_sentence": "他没打死那个老人。", "error_description": "错误：否定句“没”后面不能加“了”，成了“没打死了”。正确：“没打死那个老人”，否定时去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
