INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96363, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把带子或者钮扣合上，让它不松开。", "primary_collocate": null, "pronunciation": "kòu", "ipa": "kʰou˥˩", "syllable_count": 1, "sentences": [{"text": "天冷了，把外衣扣上吧。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衬衫没扣好。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，她扣好了大衣。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子已经学会自己扣衣服了。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上车后请扣好安全带。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的裙子扣不上了。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把腰带扣得很紧。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衬衫最上面一颗也要扣上。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他总是把大衣扣得严严实实。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的帽带没扣，快扣好。", "target_word": "扣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扣了", "label": "完成体"}, {"form": "扣着", "label": "持续体"}, {"form": "扣过", "label": "经历体"}, {"form": "扣上", "label": "复合"}, {"form": "扣好", "label": "复合"}], "register": "中性", "sense_fingerprint": "扣：把衣服的钮扣或带子合上系紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扣", "is_correct": true, "explanation": "扣 kòu：把纽扣或带子合上，是本题的目标词。"}, {"text": "口", "is_correct": false, "explanation": "口 kǒu（第三声）与 kòu（第四声）声调不同，意思是嘴。"}, {"text": "抠", "is_correct": false, "explanation": "抠 kōu（第一声）与 kòu（第四声）声调不同，意思是用指甲或细物挖取。"}, {"text": "后", "is_correct": false, "explanation": "后 hòu 与 kòu 声母不同（h 与 k），意思是之后、后面。"}, {"text": "够", "is_correct": false, "explanation": "够 gòu 与 kòu 声母不同（g 与 k），意思是足够。"}], "explanations": {"扣": "扣 kòu：把纽扣或带子合上，是本题的目标词。", "口": "口 kǒu（第三声）与 kòu（第四声）声调不同，意思是嘴。", "抠": "抠 kōu（第一声）与 kòu（第四声）声调不同，意思是用指甲或细物挖取。", "后": "后 hòu 与 kòu 声母不同（h 与 k），意思是之后、后面。", "够": "够 gòu 与 kòu 声母不同（g 与 k），意思是足够。"}, "sentence_index": null, "correct_answer": "扣"}, "level_3": {"options": [{"text": "扣", "is_correct": true, "explanation": "扣：把外衣的纽扣合上，符合“天冷了”的语境。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”指用针线连缀，不能说把外衣缝上。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：“锁”多用于门、箱子等，不能用于外衣。"}, {"text": "贴", "is_correct": false, "explanation": "语义：“贴”是粘在表面，与穿衣保暖的语境不符。"}], "explanations": {"扣": "扣：把外衣的纽扣合上，符合“天冷了”的语境。", "缝": "搭配：“缝”指用针线连缀，不能说把外衣缝上。", "锁": "搭配：“锁”多用于门、箱子等，不能用于外衣。", "贴": "语义：“贴”是粘在表面，与穿衣保暖的语境不符。"}, "sentence_index": 0, "correct_answer": "扣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把鞋带扣好了。", "explanation": "这里应该用〈系〉。扣用于纽扣、带扣，系鞋带要用系。"}, {"text": "她把书包扣在肩上。", "explanation": "这里应该用〈背〉。扣用于纽扣、带扣，背书包要用背，不能用扣。"}, {"text": "他把钥匙扣在门上。", "explanation": "这里应该用〈挂〉。扣用于纽扣、带扣，把钥匙挂在门上要用挂，不能用扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96363, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扣", "is_correct": true, "explanation": "扣 kòu：把纽扣或带子合上，是本题的目标词。"}, {"text": "购", "is_correct": false, "explanation": "购 gòu 与 kòu 声母不同（g 与 k，不送气），意思是购买。"}, {"text": "透", "is_correct": false, "explanation": "透 tòu 与 kòu 声母不同（t 与 k），意思是穿过、透过。"}, {"text": "豆", "is_correct": false, "explanation": "豆 dòu 与 kòu 声母不同（d 与 k），意思是豆子。"}, {"text": "臭", "is_correct": false, "explanation": "臭 chòu 与 kòu 声母不同（ch 与 k），意思是难闻。"}], "explanations": {"扣": "扣 kòu：把纽扣或带子合上，是本题的目标词。", "购": "购 gòu 与 kòu 声母不同（g 与 k，不送气），意思是购买。", "透": "透 tòu 与 kòu 声母不同（t 与 k），意思是穿过、透过。", "豆": "豆 dòu 与 kòu 声母不同（d 与 k），意思是豆子。", "臭": "臭 chòu 与 kòu 声母不同（ch 与 k），意思是难闻。"}, "sentence_index": null, "correct_answer": "扣"}, "level_3": {"options": [{"text": "扣", "is_correct": true, "explanation": "扣：把腰带扣合并拉紧，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹拭，与腰带扣紧的状态无关。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”是用力压，腰带不是靠按紧的。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆开，不能与“紧”搭配描述腰带的状态。"}], "explanations": {"扣": "扣：把腰带扣合并拉紧，符合句意。", "擦": "语义：“擦”是抹拭，与腰带扣紧的状态无关。", "按": "语义：“按”是用力压，腰带不是靠按紧的。", "拆": "搭配：“拆”指拆开，不能与“紧”搭配描述腰带的状态。"}, "sentence_index": 6, "correct_answer": "扣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把领带扣在脖子上。", "explanation": "这里应该用〈系〉。扣用于纽扣、带扣，打领带要用系，不能用扣。"}, {"text": "她把头发扣在脑后。", "explanation": "这里应该用〈扎〉。扣用于纽扣、带扣，把头发束起来要用扎，不能用扣。"}, {"text": "他把狗扣在树上。", "explanation": "这里应该用〈拴〉。扣用于纽扣、带扣，拴狗要用拴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没把第一颗纽扣扣好了。", "corrected_sentence": "他没把第一颗纽扣扣好。", "error_description": "错误形式：“没……扣好了”；正确形式：“没……扣好”。否定句中结果补语之后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把领口的扣子扣下了。", "corrected_sentence": "她把领口的扣子扣上了。", "error_description": "错误形式：“扣下”；正确形式：“扣上”。纽扣合住要用“上”，“下”表示向下，与句意不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
