INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96365, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找了很久，最后看到了要找的东西。", "primary_collocate": null, "pronunciation": "zhǎo jiàn", "ipa": "ʈʂɑʊ̯˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我找了一个小时，终于找见了钥匙。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机掉在沙发下面，我找了半天才找见。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈找了很久，在抽屉里找见了我的旧照片。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子找了一下午，终于找见了丢掉的小狗。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我翻遍了书包，才找见那支红笔。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找了这么久，找见你的眼镜了吗？", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间找了一遍，也没找见护照。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，我们找了好久才找见他的自行车。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她翻了半天书架，找见了那本看过的书。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了很多地方，终于找见了小时候玩过的玩具。", "target_word": "找见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找见了", "label": "完成体"}, {"form": "找见过", "label": "经历体"}, {"form": "找不见", "label": "否定可能补语"}], "register": "口语", "sense_fingerprint": "找了很久之后终于看到所找的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找见", "is_correct": true, "explanation": "找见：找了一个小时后终于找到，符合句意。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是失去，与“找了一个小时”后的结果相反。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与寻找后的结果不符。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”指抛弃，不能接在“终于”之后表示找到钥匙。"}], "explanations": {"找见": "找见：找了一个小时后终于找到，符合句意。", "丢": "语义：“丢”是失去，与“找了一个小时”后的结果相反。", "藏": "语义：“藏”是隐藏，与寻找后的结果不符。", "扔": "搭配：“扔”指抛弃，不能接在“终于”之后表示找到钥匙。"}, "sentence_index": 0, "correct_answer": "找见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找见了一个好主意，大家都同意。", "explanation": "这里应该用〈想出〉。找见指寻找后看到具体的东西，主意要用想出。"}, {"text": "我们在海边找见了一个愉快的下午。", "explanation": "这里应该用〈度过〉。找见的对象是要寻找的东西，“愉快的下午”是时间，要用度过。"}, {"text": "售货员找见了我五块钱。", "explanation": "这里应该用〈找〉。“找钱”是把多收的钱退还，与寻找后看到东西的找见无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找见", "is_correct": true, "explanation": "找见：翻遍房间后没有找到护照，符合否定句的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“护照”搭配，句子不通。"}, {"text": "买", "is_correct": false, "explanation": "搭配：护照不能“买”，只能办理或申请。"}, {"text": "续", "is_correct": false, "explanation": "语义：“续”是延期，与“找了一遍”的语境不符。"}], "explanations": {"找见": "找见：翻遍房间后没有找到护照，符合否定句的语境。", "吃": "搭配：“吃”不能与“护照”搭配，句子不通。", "买": "搭配：护照不能“买”，只能办理或申请。", "续": "语义：“续”是延期，与“找了一遍”的语境不符。"}, "sentence_index": 6, "correct_answer": "找见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在屋里找见了敲门声。", "explanation": "这里应该用〈听见〉。找见是寻找后得到具体的东西，听到声音要用听见。"}, {"text": "听到这个消息，我找见很难过。", "explanation": "这里应该用〈觉得〉。找见后要接具体的东西，表示心情要用觉得。"}, {"text": "他总是找见我的茬。", "explanation": "这里应该用〈找〉。“找茬”是固定说法，意思是故意挑毛病，不能说找见茬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找了半天，终于找见过车票。", "corrected_sentence": "他找了半天，终于找见了车票。", "error_description": "错误形式：“找见过”；正确形式：“找见了”。这里说的是这次终于找到，要用“了”；“过”表示曾经有过的经历，与“终于”的语境不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我翻了很久，也没找见了那把伞。", "corrected_sentence": "我翻了很久，也没找见那把伞。", "error_description": "错误形式：“没找见了”；正确形式：“没找见”。否定句中不能在“找见”后加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
