INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拿到别人给的东西的人。", "primary_collocate": null, "pronunciation": "jiē shòu zhě", "ipa": "tɕjɛ˧˥ ʂoʊ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这笔捐款的接受者是一所小学。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "礼物的接受者看到卡片，笑了。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "器官捐献者和接受者从没见过面。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份奖学金的接受者将在周五公布。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个接受者都能领到一袋大米。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这次爱心捐助的接受者之一。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捐赠者把书送给了接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "器官移植的接受者需要长期服药。", "target_word": "接受者", "complexity_tier": "T3", "furigana": "qì guān yí zhí de jiē shòu zhě xū yào cháng qī fú yào.", "sentence_source": "generated"}, {"text": "这批救济物资的接受者是谁？", "target_word": "接受者", "complexity_tier": "T3", "furigana": "zhè pī jiù jì wù zī de jiē shòu zhě shì shéi?", "sentence_source": "generated"}, {"text": "接受者收到包裹后，给我们回了信。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "收到别人捐赠、赠送的东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不可能是一所小学，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是物，不能与“一所小学”同指，句意不通。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受别人给的东西（此处是捐款）的一方，指接受这笔捐款的小学。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是机构，不能与“一所小学”同指，句意不通。"}], "explanations": {"学生": "语义：学生是人，不可能是一所小学，句意不通。", "汽车": "语义：汽车是物，不能与“一所小学”同指，句意不通。", "接受者": "接受者：接受别人给的东西（此处是捐款）的一方，指接受这笔捐款的小学。", "医院": "语义：医院是机构，不能与“一所小学”同指，句意不通。"}, "sentence_index": 0, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "接受者把书送给了一所小学。", "explanation": "这里应该用〈捐赠者〉。接受者是拿到东西的一方，不会把东西送出去；“送”的一方要用捐赠者。"}, {"text": "这次比赛的接受者有三百人。", "explanation": "这里应该用〈参赛者〉。接受者指拿到别人给的东西的人，比赛的参与者要用参赛者。"}, {"text": "那位接受者站在讲台上给学生上课。", "explanation": "这里应该用〈老师〉。接受者是拿到别人给的东西的人，站在讲台上给学生上课的人要用老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "语义：“书”是物，不能作为“送给”的接受对象，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“送给”要求有生命的接受对象，“空气”不能接受东西。"}, {"text": "捐赠者", "is_correct": false, "explanation": "语义：“捐赠者”是送出东西的人，前文已经占据了这个角色，不能同时作为接受者。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受别人给的东西的人，此处指收到书的人。"}], "explanations": {"书": "语义：“书”是物，不能作为“送给”的接受对象，句子不通。", "空气": "配价：“送给”要求有生命的接受对象，“空气”不能接受东西。", "捐赠者": "语义：“捐赠者”是送出东西的人，前文已经占据了这个角色，不能同时作为接受者。", "接受者": "接受者：接受别人给的东西的人，此处指收到书的人。"}, "sentence_index": 6, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的接受者笑着迎接每位客人。", "explanation": "这里应该用〈接待者〉。接受者指拿到别人给的东西的人，在门口迎接、招呼客人的要用接待者。"}, {"text": "他是公司的接受者，三年后将接任总经理。", "explanation": "这里应该用〈接班人〉。接受者指拿到别人给的东西的人，接替职位的要用接班人。"}, {"text": "总机的接受者接转了电话。", "explanation": "这里应该用〈接线员〉。接受者指拿到别人给的东西的人，负责接转电话的要用接线员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位很高接受者在门口等着。", "corrected_sentence": "那位很高的接受者在门口等着。", "error_description": "结构助词漏用：“很高”修饰“接受者”时要用“的”，应说“那位很高的接受者”，不能漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那批物资得接受者是我们学校。", "corrected_sentence": "那批物资的接受者是我们学校。", "error_description": "结构助词误用：修饰名词要用“的”，不能用“得”（“得”用于补语）。应为“那批物资的接受者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接受某物或某事的人。", "primary_collocate": null, "pronunciation": "jiē shòu zhě", "ipa": "tɕjɛ˧˥ ʂoʊ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "新药的接受者要每天记录体温。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这种教育方式的接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项治疗的接受者大多是老人。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为信息的接受者，我们要学会判断。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查显示，培训的接受者都很满意。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接受者对新规定没有意见。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法的接受者越来越多。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术的接受者需要在医院住三天。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是家庭教育的接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项补贴政策的接受者需要提交材料。", "target_word": "接受者", "complexity_tier": "T3", "furigana": "zhè xiàng bǔ tiē zhèng cè de jiē shòu zhě xū yào tí jiāo cái liào.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "接受治疗、教育、信息等事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "配价：“记录体温”要求有体温的主体，“椅子”不能作为记录者。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是需要服药的人，句子说它要记录体温，不合情理。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受某种药物或治疗的人，此处指服用新药的人。"}, {"text": "药剂", "is_correct": false, "explanation": "语义：药剂是药物本身，不会服药，也不会记录体温。"}], "explanations": {"椅子": "配价：“记录体温”要求有体温的主体，“椅子”不能作为记录者。", "电脑": "语义：电脑不是需要服药的人，句子说它要记录体温，不合情理。", "接受者": "接受者：接受某种药物或治疗的人，此处指服用新药的人。", "药剂": "语义：药剂是药物本身，不会服药，也不会记录体温。"}, "sentence_index": 0, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次手术的接受者是张大夫。", "explanation": "这里应该用〈医生〉。接受者指接受治疗的人，做手术的人要用医生。"}, {"text": "接受者在会上介绍了新政策。", "explanation": "这里应该用〈发言人〉。接受者指接收服务或信息的人，在会上介绍政策的要用发言人。"}, {"text": "接受者为顾客端来了热水。", "explanation": "这里应该用〈服务员〉。接受者指接受某物或某事的人，为顾客服务的要用服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能成为接受想法的对象，句子说它越来越多也不合理。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能接受想法，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能接受一个想法，“这个想法的空气”句意不通。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受这个想法的人，指赞同或接受该想法的人。"}], "explanations": {"石头": "语义：石头不是人，不能成为接受想法的对象，句子说它越来越多也不合理。", "桌子": "语义：桌子是家具，不能接受想法，句意不通。", "空气": "语义：空气不是人，不能接受一个想法，“这个想法的空气”句意不通。", "接受者": "接受者：接受这个想法的人，指赞同或接受该想法的人。"}, "sentence_index": 6, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前台的接受者正在修电脑。", "explanation": "这里应该用〈技术员〉。接受者指接受某物或某事的人，修电脑的要用技术员。"}, {"text": "他是这家店的接受者，每天负责煮咖啡。", "explanation": "这里应该用〈咖啡师〉。接受者指接受某物或某事的人，负责煮咖啡的要用咖啡师。"}, {"text": "这位接受者负责设计公司的网站。", "explanation": "这里应该用〈设计师〉。接受者指接受某物或某事的人，负责设计网站的要用设计师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位很年轻接受者参加了这次培训。", "corrected_sentence": "一位很年轻的接受者参加了这次培训。", "error_description": "结构助词漏用：“很年轻”修饰“接受者”时要加“的”，应为“一位很年轻的接受者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次培训得接受者都拿到了证书。", "corrected_sentence": "那次培训的接受者都拿到了证书。", "error_description": "结构助词误用：修饰名词要用“的”，不能用“得”。应为“那次培训的接受者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
