INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96371, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有人做了坏事，你去告诉警察或法官，请他们来管。", "primary_collocate": null, "pronunciation": "kòng gào", "ipa": "kʰʊŋ˥˩ kau̯˥˩", "syllable_count": 2, "sentences": [{"text": "邻居偷了我的车，我去警察局控告他。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不给工资，工人们去法院控告他。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打了我的孩子，我要去控告他。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司骗了很多人，大家一起控告它。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东一直不还钱，他决定控告房东。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去警察局控告那个偷包的人。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以去法院控告他，法官会管这件事。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生控告了那个打他的人。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想控告这家饭馆，因为他们卖坏肉。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向警察控告邻居抢走了他的手机。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控告了", "label": "完成体"}, {"form": "控告过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "受害的人去找警察或法官，说明别人做的坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控告", "is_correct": true, "explanation": "正确：“控告”指去警察局告发对方的违法行为，与“偷了我的车”相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，偷车的人不该被感谢，与句意矛盾。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”的对象是来访的客人，不与“去警察局”搭配。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”表示称赞，与偷车的行为相矛盾。"}], "explanations": {"控告": "正确：“控告”指去警察局告发对方的违法行为，与“偷了我的车”相合。", "感谢": "语义：“感谢”表示感激，偷车的人不该被感谢，与句意矛盾。", "迎接": "搭配：“迎接”的对象是来访的客人，不与“去警察局”搭配。", "夸奖": "语义：“夸奖”表示称赞，与偷车的行为相矛盾。"}, "sentence_index": 0, "correct_answer": "控告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去酒店控告服务员，因为他态度不好。", "explanation": "这里应该用〈投诉〉。控告针对违法行为，服务态度不好只能投诉。"}, {"text": "我控告天气太热了。", "explanation": "这里应该用〈抱怨〉。控告针对违法的人或单位，天气热只能抱怨。"}, {"text": "我控告妈妈不让我玩游戏。", "explanation": "这里应该用〈埋怨〉。控告只用于告发违法行为，家里的小事只能说埋怨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控告", "is_correct": true, "explanation": "正确：“控告”指向法院告发他人违法，与“法院会管这件事”相合。"}, {"text": "恭喜", "is_correct": false, "explanation": "搭配：“恭喜”用于向人道贺，不说去法院恭喜他。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”是美好的心愿，与“法官会管这件事”的意思不合。"}, {"text": "送别", "is_correct": false, "explanation": "语义：“送别”指送人离开，与去法院处理纠纷的意思不合。"}], "explanations": {"控告": "正确：“控告”指向法院告发他人违法，与“法院会管这件事”相合。", "恭喜": "搭配：“恭喜”用于向人道贺，不说去法院恭喜他。", "祝福": "语义：“祝福”是美好的心愿，与“法官会管这件事”的意思不合。", "送别": "语义：“送别”指送人离开，与去法院处理纠纷的意思不合。"}, "sentence_index": 6, "correct_answer": "控告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我控告这个房间太小。", "explanation": "这里应该用〈嫌弃〉。控告是向机关告发违法行为，房间太小不是违法，只能说嫌弃。"}, {"text": "我控告这幅画的颜色。", "explanation": "这里应该用〈欣赏〉。控告不能用于赞美的事物，画的颜色不是违法行为。"}, {"text": "大家控告他的生日。", "explanation": "这里应该用〈庆祝〉。控告针对违法的人或单位，生日只能庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去法院了控告那个骗子。", "corrected_sentence": "我去法院控告那个骗子。", "error_description": "错误：“了”被放到动词“控告”的前面。正确：“了”只能放在动词之后，如“控告了那个骗子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没控告了那个老板。", "corrected_sentence": "他没控告那个老板。", "error_description": "错误：否定句“没”后面不能加“了”，成了“没控告了”。正确：“没控告那个老板”，否定时去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
