INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向司法机关或有关部门检举、告发。", "primary_collocate": null, "pronunciation": "kòng gào", "ipa": "kʰʊŋ˥˩ kau̯˥˩", "syllable_count": 2, "sentences": [{"text": "村民向县里控告村长贪污。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向法院控告公司违法。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们一起控告老板拖欠工资。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近居民向环保部门控告那家工厂偷排污水。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向检察院控告经理收了别人的钱。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主们控告开发商擅自挪用维修基金。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人控告这位官员受贿。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她控告老师打学生，学校正在调查。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民向有关部门控告这家公司乱排废水。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向法院控告对方伪造合同，还提交了证据。", "target_word": "控告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控告了", "label": "完成体"}, {"form": "控告过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "向司法机关或有关部门检举他人违法行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控告", "is_correct": true, "explanation": "正确：“控告”指向县里检举村长的违法行为，与“贪污”相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与“贪污”的违法行为矛盾。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”用于奖状、证书，不说颁发贪污。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”表示称赞，与“贪污”的意思相反。"}], "explanations": {"控告": "正确：“控告”指向县里检举村长的违法行为，与“贪污”相合。", "感谢": "语义：“感谢”表示感激，与“贪污”的违法行为矛盾。", "颁发": "搭配：“颁发”用于奖状、证书，不说颁发贪污。", "表扬": "语义：“表扬”表示称赞，与“贪污”的意思相反。"}, "sentence_index": 0, "correct_answer": "控告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "居民向政府控告修建公园。", "explanation": "这里应该用〈建议〉。控告是检举违法行为，修建公园不是违法，只能说建议。"}, {"text": "他向银行控告了贷款。", "explanation": "这里应该用〈申请〉。控告针对违法行为，申请贷款不是违法，应该说申请。"}, {"text": "居民向有关部门控告办理手续。", "explanation": "这里应该用〈咨询〉。控告针对违法行为，询问办理手续只能说咨询。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控告", "is_correct": true, "explanation": "正确：“控告”指向有关机关告发他人违法，与“这位官员受贿”相合。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”表示表彰，与“受贿”的违法行为矛盾。"}, {"text": "提拔", "is_correct": false, "explanation": "语义：“提拔”表示升职，与“受贿”的违法行为矛盾。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”用于申请、计划，不说批准受贿。"}], "explanations": {"控告": "正确：“控告”指向有关机关告发他人违法，与“这位官员受贿”相合。", "奖励": "语义：“奖励”表示表彰，与“受贿”的违法行为矛盾。", "提拔": "语义：“提拔”表示升职，与“受贿”的违法行为矛盾。", "批准": "搭配：“批准”用于申请、计划，不说批准受贿。"}, "sentence_index": 6, "correct_answer": "控告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师控告学生多读书。", "explanation": "这里应该用〈鼓励〉。控告是检举违法行为，多读书不是违法，应该说鼓励。"}, {"text": "我们控告他来参加婚礼。", "explanation": "这里应该用〈邀请〉。控告针对违法行为，请人来参加婚礼只能说邀请。"}, {"text": "他向警察控告了事情的经过。", "explanation": "这里应该用〈说明〉。控告是告发他人违法，讲清事情经过只能说说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向公安局了控告那家店欺诈顾客。", "corrected_sentence": "他向公安局控告那家店欺诈顾客。", "error_description": "错误：“了”被放到动词“控告”的前面。正确：“了”只能放在动词之后，“控告”前不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没向法院控告了对方。", "corrected_sentence": "他没向法院控告对方。", "error_description": "错误：否定句“没”后面不能加“了”，成了“没向法院控告了对方”。正确：“没向法院控告对方”，否定时去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
