INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在推特等社交平台上发布的短消息。", "primary_collocate": null, "pronunciation": "tuī wén", "ipa": "tʰweɪ̯˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "他每天早上在推特上发一条推文。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条推文在推特上被转发了很多次。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在推特上写的推文很短，只有十几个字。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在推特上看到了一条有意思的推文。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在推特上写了一条推文，介绍一本新书。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手在推特上的推文被转发了几万次。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在推特上删掉了那条推文，因为写错了字。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在推特上看过他今天的推文吗？", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在一条推文里宣布了新手机的价格。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个明星每次更新推特，推文都有很多人点赞。", "target_word": "推文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "通用", "sense_fingerprint": "社交平台推特上发布的短消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6890a3e-4b06-44e7-ac3e-181d3cd72888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裙子", "is_correct": false, "explanation": "搭配：“发”后面接的是可以在推特上发布的内容，“裙子”不能这样发布。"}, {"text": "推文", "is_correct": true, "explanation": "推文：在推特等平台上发布的短消息，与“发一条”和“推特上”搭配。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然景物，无法在推特上发布。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，不能作为消息在推特上发出。"}], "explanations": {"裙子": "搭配：“发”后面接的是可以在推特上发布的内容，“裙子”不能这样发布。", "推文": "推文：在推特等平台上发布的短消息，与“发一条”和“推特上”搭配。", "河": "语义：河是自然景物，无法在推特上发布。", "鱼": "语义：鱼是动物，不能作为消息在推特上发出。"}, "sentence_index": 0, "correct_answer": "推文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在论坛上看到了一条有意思的推文。", "explanation": "这里应该用〈帖子〉。推文专指推特等平台上发布的短消息，论坛上的帖子不能说“推文”。"}, {"text": "我昨天在电视上看到了一条有意思的推文。", "explanation": "这里应该用〈广告〉或〈节目〉。推文是在社交平台上发布的短消息，电视上播的不能叫推文。"}, {"text": "我昨天在报纸上看到了一条有意思的推文。", "explanation": "这里应该用〈新闻〉。推文是用户在推特上发布的短消息，报纸上的内容应说“新闻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领带", "is_correct": false, "explanation": "语义：领带是衣物，不是用字写成的，也不能在推特上删掉。"}, {"text": "推文", "is_correct": true, "explanation": "推文：在推特等平台上发布的短消息，与“删掉”和“写错了字”相符。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“删掉”一般接文字、图片等内容，不接“绳子”这样的实物。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是天空中的自然现象，不能在推特上删除。"}], "explanations": {"领带": "语义：领带是衣物，不是用字写成的，也不能在推特上删掉。", "推文": "推文：在推特等平台上发布的短消息，与“删掉”和“写错了字”相符。", "绳子": "搭配：“删掉”一般接文字、图片等内容，不接“绳子”这样的实物。", "彩虹": "语义：彩虹是天空中的自然现象，不能在推特上删除。"}, "sentence_index": 6, "correct_answer": "推文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个明星每次开演唱会，推文都很快卖光了。", "explanation": "这里应该用〈门票〉。推文是网上发布的短消息，不能买卖，演唱会卖的是门票。"}, {"text": "我在书店买了一本推文。", "explanation": "这里应该用〈书〉。推文是在社交平台上发布的短消息，不能在书店买。"}, {"text": "他给妈妈写了一封推文，寄到了老家。", "explanation": "这里应该用〈信〉。推文在网上发布，不能装进信封寄出，寄的是信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天发了三只推文，大家都看到了。", "corrected_sentence": "我昨天发了三条推文，大家都看到了。", "error_description": "“推文”的量词应为“条”。“只”多用于动物或成对的东西，不能修饰推文，应改为“三条推文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那只推文删掉了。", "corrected_sentence": "他把那条推文删掉了。", "error_description": "错误形式：“那只推文”；正确形式：“那条推文”。推文用量词“条”，“只”多用于动物或成对的东西，不能修饰推文。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fb1dfeb-bcdb-4245-a11d-125bb504fa86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
