INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从有危险的地方走开，去安全的地方。", "primary_collocate": null, "pronunciation": "chè lí", "ipa": "ʈʂʰɤ˥˩ li˧˥", "syllable_count": 2, "sentences": [{"text": "大水来了，居民都撤离了村子。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾发生后，大家马上撤离大楼。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，学生们撤离了教室。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风要来了，海边的人必须撤离。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察让大家快点撤离危险地区。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上有大火，游客已经撤离了。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家走楼梯安全撤离。", "target_word": "撤离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们撤离矿井时，没有人受伤。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水到来前，我们撤离到了高处。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员帮老人撤离了着火的房子。", "target_word": "撤离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤离了", "label": "体标（了）"}, {"form": "撤离过", "label": "体标（过）"}, {"form": "撤離", "label": "繁体"}], "register": "书面", "sense_fingerprint": "撤离：人从危险的地方走开，转到安全处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撤离", "is_correct": true, "explanation": "撤离：从危险的地方走开，转到安全处，与“大水来了”的情境相合。"}, {"text": "进入", "is_correct": false, "explanation": "语义：进入是走进某处，洪水来临时居民不会进村，与情境相反。"}, {"text": "占领", "is_correct": false, "explanation": "搭配：占领指以武力夺取，居民不能占领自己的村子。"}, {"text": "冲毁", "is_correct": false, "explanation": "配价：冲毁的施事应是洪水等自然力，居民不能作施事。"}], "explanations": {"撤离": "撤离：从危险的地方走开，转到安全处，与“大水来了”的情境相合。", "进入": "语义：进入是走进某处，洪水来临时居民不会进村，与情境相反。", "占领": "搭配：占领指以武力夺取，居民不能占领自己的村子。", "冲毁": "配价：冲毁的施事应是洪水等自然力，居民不能作施事。"}, "sentence_index": 0, "correct_answer": "撤离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他撤离了申请。", "explanation": "这里应该用〈撤回〉。撤离指人员、部队从所在地撤出，已提交的申请要说撤回。"}, {"text": "他撤离了比赛。", "explanation": "这里应该用〈退出〉。撤离用于从危险地方转移，中途放弃比赛要说退出。"}, {"text": "法院撤离了那项判决。", "explanation": "这里应该用〈撤销〉。撤离针对人员或地点的转移，判决被取消要说撤销。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤离", "is_correct": true, "explanation": "撤离：从危险地方走开，去安全处，与“走楼梯安全”的要求相合。"}, {"text": "滞留", "is_correct": false, "explanation": "语义：滞留指停留不走，与“安全撤离”的要求相反。"}, {"text": "围观", "is_correct": false, "explanation": "搭配：围观是聚在一起看热闹，不能与“走楼梯安全”搭配。"}, {"text": "点名", "is_correct": false, "explanation": "搭配：点名是清点人数，不表示以安全的方式移动。"}], "explanations": {"撤离": "撤离：从危险地方走开，去安全处，与“走楼梯安全”的要求相合。", "滞留": "语义：滞留指停留不走，与“安全撤离”的要求相反。", "围观": "搭配：围观是聚在一起看热闹，不能与“走楼梯安全”搭配。", "点名": "搭配：点名是清点人数，不表示以安全的方式移动。"}, "sentence_index": 6, "correct_answer": "撤离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员把菜撤离了。", "explanation": "这里应该用〈撤下〉。撤离只用于人员或部队从危险地方转移，把菜从桌上拿走要说撤下。"}, {"text": "公司撤离了他的职务。", "explanation": "这里应该用〈撤职〉。撤离针对人员从危险地点撤出，罢免职务要说撤职。"}, {"text": "她的注意力撤离了屏幕。", "explanation": "这里应该用〈抽离〉。撤离用于地点或危险场所，注意力、情绪的转移要说抽离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家迅速撤离在安全的地方。", "corrected_sentence": "大家迅速撤离到安全的地方。", "error_description": "错误形式“撤离在”，正确形式“撤离到”。撤离后接终点要用“到”，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
