INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从所在地方撤出离开，多指因危险而转移。", "primary_collocate": null, "pronunciation": "chè lí", "ipa": "ʈʂʰɤ˥˩ li˧˥", "syllable_count": 2, "sentences": [{"text": "军队已经撤离了这座城市。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生和护士撤离了战区。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司因为战争撤离了所有员工。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大使馆要求本国人员尽快撤离。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队在天亮前撤离了山区。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不得不撤离自己的家园。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国记者昨天撤离了那个国家。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员已经从灾区撤离。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人撤离后，村子安静了。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府安排车辆帮助居民撤离。", "target_word": "撤离", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤离了", "label": "体标（了）"}, {"form": "撤离过", "label": "体标（过）"}, {"form": "撤離", "label": "繁体"}], "register": "书面", "sense_fingerprint": "撤离：部队、机构或人员从所在地撤出离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撤离", "is_correct": true, "explanation": "撤离：部队、人员从所在地撤出，与“军队已经”和“这座城市”相合。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：诞生是不及物动词，不能带“这座城市”作宾语。"}, {"text": "参军", "is_correct": false, "explanation": "配价：参军是不及物动词，不能带“这座城市”作宾语。"}, {"text": "冲毁", "is_correct": false, "explanation": "搭配：冲毁多用于洪水、地震等破坏，不与军队搭配。"}], "explanations": {"撤离": "撤离：部队、人员从所在地撤出，与“军队已经”和“这座城市”相合。", "诞生": "配价：诞生是不及物动词，不能带“这座城市”作宾语。", "参军": "配价：参军是不及物动词，不能带“这座城市”作宾语。", "冲毁": "搭配：冲毁多用于洪水、地震等破坏，不与军队搭配。"}, "sentence_index": 0, "correct_answer": "撤离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他撤离了这个组织。", "explanation": "这里应该用〈退出〉。撤离指部队、人员从所在地撤出，离开组织要说退出。"}, {"text": "这个社团撤离了这次活动。", "explanation": "这里应该用〈退出〉。撤离指部队、人员从所在地撤出，不再参加某项活动要说退出。"}, {"text": "他撤离了那封信。", "explanation": "这里应该用〈收回〉。撤离指从所在地撤出人员或部队，收回已发出的东西要说收回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤离", "is_correct": true, "explanation": "撤离：外国记者离开该国，与“昨天”的时间和“那个国家”的对象相合。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生是不及物动词，不能带“那个国家”作宾语。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：欢送的对象应是人，不能欢送一个国家。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：赶走指驱离人或势力，记者不能把整个国家赶走，与语义不合。"}], "explanations": {"撤离": "撤离：外国记者离开该国，与“昨天”的时间和“那个国家”的对象相合。", "出生": "配价：出生是不及物动词，不能带“那个国家”作宾语。", "欢送": "搭配：欢送的对象应是人，不能欢送一个国家。", "赶走": "语义：赶走指驱离人或势力，记者不能把整个国家赶走，与语义不合。"}, "sentence_index": 6, "correct_answer": "撤离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛撤离了。", "explanation": "这里应该用〈取消〉。撤离指人员从所在地撤出，比赛不能进行时要说取消。"}, {"text": "政府撤离了那项规定。", "explanation": "这里应该用〈废除〉。撤离针对人员或部队的撤出，规定不再有效要说废除。"}, {"text": "他撤离了那个计划。", "explanation": "这里应该用〈放弃〉。撤离指从所在地撤出，计划不再推进要说放弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部队在夜里撤离在了后方。", "corrected_sentence": "部队在夜里撤离到了后方。", "error_description": "错误形式“撤离在了”，正确形式“撤离到了”。撤离后接去往的地点要用“到”，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医疗队已经撤离着疫区。", "corrected_sentence": "医疗队已经撤离了疫区。", "error_description": "错误形式“撤离着”，正确形式“撤离了”。“已经”表示完成，撤离的完成要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
