INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96377, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人或东西在小地方里，互相推着靠得很近。", "primary_collocate": null, "pronunciation": "jǐ", "ipa": "tɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "地铁里挤着很多人。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的公交车上挤满了人。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室太小，三十个人都挤在里面。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们六个人挤在一辆小车里。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们挤在门口看热闹。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天很冷，大家挤在一起取暖。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班时间，人们都挤在地铁站门口。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发很小，三个人挤在上面。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，火车上挤得没有地方站。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一张床上挤着四只小猫。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挤了", "label": "完成体"}, {"form": "挤着", "label": "持续体"}, {"form": "挤过", "label": "经历体"}, {"form": "挤挤", "label": "重叠"}, {"form": "拥挤", "label": "复合词"}, {"form": "挤满", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动词；许多人或物在狭小空间里紧紧靠在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96377, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤（jǐ）：很多人或东西在小地方里互相推着靠得很近，是本词条的释义。"}, {"text": "集", "is_correct": false, "explanation": "集（jí）与挤（jǐ）声调不同（第二声与第三声），意思是聚集、汇集。"}, {"text": "寄", "is_correct": false, "explanation": "寄（jì）与挤（jǐ）声调不同（第四声与第三声），意思是寄送。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī）与挤（jǐ）声调不同（第一声与第三声），意思是家禽鸡。"}, {"text": "起", "is_correct": false, "explanation": "起（qǐ）与挤（jǐ）声母不同（q 与 j），声调相同，意思是起来、起床。"}, {"text": "举", "is_correct": false, "explanation": "举（jǔ）与挤（jǐ）韵母不同（ü 与 i），声调相同，意思是举起。"}], "explanations": {"挤": "挤（jǐ）：很多人或东西在小地方里互相推着靠得很近，是本词条的释义。", "集": "集（jí）与挤（jǐ）声调不同（第二声与第三声），意思是聚集、汇集。", "寄": "寄（jì）与挤（jǐ）声调不同（第四声与第三声），意思是寄送。", "鸡": "鸡（jī）与挤（jǐ）声调不同（第一声与第三声），意思是家禽鸡。", "起": "起（qǐ）与挤（jǐ）声母不同（q 与 j），声调相同，意思是起来、起床。", "举": "举（jǔ）与挤（jǐ）韵母不同（ü 与 i），声调相同，意思是举起。"}, "sentence_index": null, "correct_answer": "挤"}, "level_3": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤：许多人靠在狭小的地铁车厢里，与句中的“地铁里”和“很多人”相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指鸟或飞机在空中移动，不能用来说人在地铁里飞着。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中活动，地铁里没有水，不能说人在地铁里游着。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用嘴或风送气，不能说地铁里吹着很多人。"}], "explanations": {"挤": "挤：许多人靠在狭小的地铁车厢里，与句中的“地铁里”和“很多人”相符。", "飞": "语义：“飞”指鸟或飞机在空中移动，不能用来说人在地铁里飞着。", "游": "语义：“游”指在水中活动，地铁里没有水，不能说人在地铁里游着。", "吹": "语义：“吹”指用嘴或风送气，不能说地铁里吹着很多人。"}, "sentence_index": 0, "correct_answer": "挤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们挤在操场的各处，有的踢球，有的跑步。", "explanation": "这里应该用〈分散〉。“挤”强调许多人或物靠得很近，学生散在操场各处时不能说挤。"}, {"text": "两栋楼挤得很远，中间还有一条河。", "explanation": "这里应该用〈隔〉。“挤”强调许多人或物靠得很近，两栋楼相距很远时只能说隔。"}, {"text": "他一个人挤在大沙发上看书。", "explanation": "这里应该用〈坐〉。“挤”强调许多人或物靠在一起，一个人独占大沙发时要说坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96377, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤（jǐ）：很多人或东西在小地方里互相推着靠得很近，是本词条的释义。"}, {"text": "记", "is_correct": false, "explanation": "记（jì）与挤（jǐ）声调不同（第四声与第三声），意思是记住。"}, {"text": "吉", "is_correct": false, "explanation": "吉（jí）与挤（jǐ）声调不同（第二声与第三声），意思是吉祥、吉利。"}, {"text": "击", "is_correct": false, "explanation": "击（jī）与挤（jǐ）声调不同（第一声与第三声），意思是打击、撞击。"}, {"text": "启", "is_correct": false, "explanation": "启（qǐ）与挤（jǐ）声母不同（q 与 j），声调相同，意思是开启。"}, {"text": "洗", "is_correct": false, "explanation": "洗（xǐ）与挤（jǐ）声母不同（x 与 j），声调相同，意思是洗涤。"}], "explanations": {"挤": "挤（jǐ）：很多人或东西在小地方里互相推着靠得很近，是本词条的释义。", "记": "记（jì）与挤（jǐ）声调不同（第四声与第三声），意思是记住。", "吉": "吉（jí）与挤（jǐ）声调不同（第二声与第三声），意思是吉祥、吉利。", "击": "击（jī）与挤（jǐ）声调不同（第一声与第三声），意思是打击、撞击。", "启": "启（qǐ）与挤（jǐ）声母不同（q 与 j），声调相同，意思是开启。", "洗": "洗（xǐ）与挤（jǐ）声母不同（x 与 j），声调相同，意思是洗涤。"}, "sentence_index": null, "correct_answer": "挤"}, "level_3": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤：下班时人多，人们都靠在地铁站门口，与句中的“下班时间”和场景相符。"}, {"text": "躺", "is_correct": false, "explanation": "语义：“躺”指身体平卧休息，与下班时人们在门口走动的场景不符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，与“下班时间”的人流场景相冲突。"}, {"text": "摆", "is_correct": false, "explanation": "搭配：“摆”多用于摆放物品，不能说“人们都摆在地铁站门口”。"}], "explanations": {"挤": "挤：下班时人多，人们都靠在地铁站门口，与句中的“下班时间”和场景相符。", "躺": "语义：“躺”指身体平卧休息，与下班时人们在门口走动的场景不符。", "睡": "语义：“睡”指睡觉，与“下班时间”的人流场景相冲突。", "摆": "搭配：“摆”多用于摆放物品，不能说“人们都摆在地铁站门口”。"}, "sentence_index": 6, "correct_answer": "挤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "广场中央挤着一个人。", "explanation": "这里应该用〈站〉。“挤”表示许多人或物靠得很近，广场中央只有一个人时，不能说挤。"}, {"text": "屋里很空旷，却挤着一台冰箱。", "explanation": "这里应该用〈放〉。“挤”强调许多人或物靠得很近，空旷的屋子里只放一台冰箱时不能说挤。"}, {"text": "他一个人挤在大房子里，很自在。", "explanation": "这里应该用〈住〉。“挤”强调许多人或物靠得很近，一个人住大房子时不能说挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节假日的商场门口满挤了人。", "corrected_sentence": "节假日的商场门口挤满了人。", "error_description": "错误：“满挤了人”。正确：“挤满了人”。结果补语“满”要紧跟在动词“挤”的后面，不能放在“挤”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节日里，三个孩子挤沙发上看动画。", "corrected_sentence": "节日里，三个孩子挤在沙发上看动画。", "error_description": "错误：“挤沙发上”。正确：“挤在沙发上”。“挤”表示许多人靠得很近，后面要用介词“在”引出所在的地方，省略“在”句子就不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
