INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力压使东西排出；用力硬往里面进或往外出。", "primary_collocate": null, "pronunciation": "jǐ", "ipa": "tɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "他挤了一点牙膏在牙刷上。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李挤进了小箱子里。", "target_word": "挤", "complexity_tier": "T3", "furigana": "tā bǎ xíngli jǐ jìn le xiǎo xiāngzi lǐ.", "sentence_source": "generated"}, {"text": "我用手挤橙子，想做一杯果汁。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从后面挤进了人群。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车门快关了，她还是挤上了车。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩使劲挤到前排去看表演。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用手挤脸上的痘痘。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脚挤进了太小的鞋里。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从人群里挤了出来。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把海绵挤一挤，水就出来了。", "target_word": "挤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挤了", "label": "完成体"}, {"form": "挤着", "label": "持续体"}, {"form": "挤过", "label": "经历体"}, {"form": "挤挤", "label": "重叠"}, {"form": "挤压", "label": "复合词"}, {"form": "挤进", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动词；用力压使东西排出，或用力硬往里面钻、进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '795b523b-e6bd-4e9b-b447-3f39817fea87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤（jǐ）：用力压使东西排出，或用力硬往里面钻、进，是本义项的释义。"}, {"text": "急", "is_correct": false, "explanation": "急（jí）与挤（jǐ）声调不同（第二声与第三声），意思是着急、急迫。"}, {"text": "季", "is_correct": false, "explanation": "季（jì）与挤（jǐ）声调不同（第四声与第三声），意思是季节。"}, {"text": "积", "is_correct": false, "explanation": "积（jī）与挤（jǐ）声调不同（第一声与第三声），意思是积累、堆积。"}, {"text": "指", "is_correct": false, "explanation": "指（zhǐ）与挤（jǐ）声母不同（zh 与 j），声调相同，意思是手指、指示。"}], "explanations": {"挤": "挤（jǐ）：用力压使东西排出，或用力硬往里面钻、进，是本义项的释义。", "急": "急（jí）与挤（jǐ）声调不同（第二声与第三声），意思是着急、急迫。", "季": "季（jì）与挤（jǐ）声调不同（第四声与第三声），意思是季节。", "积": "积（jī）与挤（jǐ）声调不同（第一声与第三声），意思是积累、堆积。", "指": "指（zhǐ）与挤（jǐ）声母不同（zh 与 j），声调相同，意思是手指、指示。"}, "sentence_index": null, "correct_answer": "挤"}, "level_3": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤：用力压使牙膏从管口排出，与句中的“一点牙膏”和“牙刷上”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，牙膏不能说吃着挤到牙刷上。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指用牙咬碎食物，牙膏不能嚼着涂到牙刷上。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，与把牙膏从管里挤出来的动作不符。"}], "explanations": {"挤": "挤：用力压使牙膏从管口排出，与句中的“一点牙膏”和“牙刷上”相符。", "吃": "语义：“吃”指把食物咽下，牙膏不能说吃着挤到牙刷上。", "嚼": "语义：“嚼”指用牙咬碎食物，牙膏不能嚼着涂到牙刷上。", "扔": "语义：“扔”指抛掷，与把牙膏从管里挤出来的动作不符。"}, "sentence_index": 0, "correct_answer": "挤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用笔挤了自己的名字。", "explanation": "这里应该用〈写〉。“挤”表示用力压使东西排出或硬往里进，用笔写名字不能说挤。"}, {"text": "他用手挤了一下门铃。", "explanation": "这里应该用〈按〉。“挤”要有用力压出或硬往里钻的意思；按门铃只是用手指压下去，不说挤。"}, {"text": "他一边走路，一边挤着耳机听歌。", "explanation": "这里应该用〈戴〉。“挤”表示用力压使东西排出或硬往里进，耳机应该说戴在耳朵上，不能说挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96378, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤（jǐ）：用力压使东西排出，或用力硬往里面钻、进，是本义项的释义。"}, {"text": "技", "is_correct": false, "explanation": "技（jì）与挤（jǐ）声调不同（第四声与第三声），意思是技术、技能。"}, {"text": "只", "is_correct": false, "explanation": "只（zhǐ）与挤（jǐ）声母不同（zh 与 j），声调相同，意思是只有、仅仅。"}, {"text": "激", "is_correct": false, "explanation": "激（jī）与挤（jǐ）声调不同（第一声与第三声），意思是激动、激烈。"}, {"text": "集", "is_correct": false, "explanation": "集（jí）与挤（jǐ）声调不同（第二声与第三声），意思是聚集、集合。"}], "explanations": {"挤": "挤（jǐ）：用力压使东西排出，或用力硬往里面钻、进，是本义项的释义。", "技": "技（jì）与挤（jǐ）声调不同（第四声与第三声），意思是技术、技能。", "只": "只（zhǐ）与挤（jǐ）声母不同（zh 与 j），声调相同，意思是只有、仅仅。", "激": "激（jī）与挤（jǐ）声调不同（第一声与第三声），意思是激动、激烈。", "集": "集（jí）与挤（jǐ）声调不同（第二声与第三声），意思是聚集、集合。"}, "sentence_index": null, "correct_answer": "挤"}, "level_3": {"options": [{"text": "挤", "is_correct": true, "explanation": "挤：用力压使痘痘里的东西排出，与句中“脸上的痘痘”和“别用手”的语境相符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用嘴或风送气，不能说用手吹脸上的痘痘。"}, {"text": "贴", "is_correct": false, "explanation": "语义：“贴”指把东西粘在表面，痘痘长在脸上，不能被贴上去。"}, {"text": "掰", "is_correct": false, "explanation": "搭配：“掰”多用于掰开、掰断，不能用来处理脸上的痘痘。"}], "explanations": {"挤": "挤：用力压使痘痘里的东西排出，与句中“脸上的痘痘”和“别用手”的语境相符。", "吹": "语义：“吹”指用嘴或风送气，不能说用手吹脸上的痘痘。", "贴": "语义：“贴”指把东西粘在表面，痘痘长在脸上，不能被贴上去。", "掰": "搭配：“掰”多用于掰开、掰断，不能用来处理脸上的痘痘。"}, "sentence_index": 6, "correct_answer": "挤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力挤开了水龙头。", "explanation": "这里应该用〈拧〉。“挤”表示用力压使东西排出或硬往里进，拧开水龙头是转动开关，不能说挤。"}, {"text": "他用力挤掉了衣服上的灰尘。", "explanation": "这里应该用〈掸〉。“挤”表示用力压使东西排出或硬往里进，掸去灰尘要靠拍打，不能说挤。"}, {"text": "他用抹布挤干净了桌子。", "explanation": "这里应该用〈擦〉。“挤”是用力压使东西排出或硬往里进，擦桌子是抹去污渍，不能说挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把柠檬出挤了一点汁。", "corrected_sentence": "他把柠檬挤出了一点汁。", "error_description": "错误：“出挤”。正确：“挤出”。结果补语“出”要紧跟在动词“挤”的后面，表示从里面排出来，不能放在“挤”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把毛衣挤了行李箱。", "corrected_sentence": "他把毛衣挤进了行李箱。", "error_description": "错误：“挤了行李箱”。正确：“挤进了行李箱”。“挤”后面需要趋向补语“进”，表示用力压进某个地方，缺少“进”句子就不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5587ab3-5dd3-41ff-93d9-ccacbdbe40f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弄乱", "is_correct": true, "explanation": "正确。“弄乱”与“收拾”（把乱的东西放好）意思相反，指把东西弄得乱七八糟。"}, {"text": "保存", "is_correct": false, "explanation": "与“收拾”没有反义关系，保存指让东西不受损失地留存下来。"}, {"text": "搬运", "is_correct": false, "explanation": "与“收拾”没有反义关系，搬运指把东西从一处运到另一处。"}, {"text": "观看", "is_correct": false, "explanation": "与“收拾”没有反义关系，观看指注视着看。"}], "correct_answer": "弄乱", "explanations": {"弄乱": "正确。“弄乱”与“收拾”（把乱的东西放好）意思相反，指把东西弄得乱七八糟。", "保存": "与“收拾”没有反义关系，保存指让东西不受损失地留存下来。", "搬运": "与“收拾”没有反义关系，搬运指把东西从一处运到另一处。", "观看": "与“收拾”没有反义关系，观看指注视着看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "搞乱", "is_correct": true, "explanation": "正确。“搞乱”与“收拾”（把乱的东西放好）意思相反，指把东西弄乱。"}, {"text": "欢迎", "is_correct": false, "explanation": "与“收拾”没有反义关系，欢迎指以热情的态度接待。"}, {"text": "生长", "is_correct": false, "explanation": "与“收拾”没有反义关系，生长指生物逐渐长大。"}, {"text": "制造", "is_correct": false, "explanation": "与“收拾”没有反义关系，制造指用人力把材料做成东西。"}], "correct_answer": "搞乱", "explanations": {"搞乱": "正确。“搞乱”与“收拾”（把乱的东西放好）意思相反，指把东西弄乱。", "欢迎": "与“收拾”没有反义关系，欢迎指以热情的态度接待。", "生长": "与“收拾”没有反义关系，生长指生物逐渐长大。", "制造": "与“收拾”没有反义关系，制造指用人力把材料做成东西。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把乱的东西放好，让地方变干净整齐。", "primary_collocate": null, "pronunciation": "shōu shi", "ipa": "ʂou̯˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "妈妈在收拾厨房。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我收拾了自己的房间。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人快到了，你快收拾桌子。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，爸爸把碗收拾好了。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上收拾床铺，再去上班。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的书和衣服太乱了，快收拾一下。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边收拾屋子，一边听音乐。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我花了两天收拾新家。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把玩具扔了一地，妈妈只好收拾。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子太乱，我想先收拾，再煮饭。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收拾了", "label": "完成体"}, {"form": "收拾着", "label": "持续体"}, {"form": "收拾过", "label": "经历体"}, {"form": "收拾收拾", "label": "重叠"}], "register": "口语", "sense_fingerprint": "把房间、桌子等乱的地方弄干净整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确答案：收拾（shōu shi），指把乱的东西放好，让地方整齐干净。"}, {"text": "首饰", "is_correct": false, "explanation": "shǒu（第三声）与 shōu（第一声）声调不同，首饰指戴在身上的装饰品，如项链、戒指。"}, {"text": "收视", "is_correct": false, "explanation": "收视的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是观看电视的情况，如收视率。"}, {"text": "手势", "is_correct": false, "explanation": "shǒu shì 与 shōu shi 两个音节的声调都不同，手势指用手做出的动作。"}, {"text": "守时", "is_correct": false, "explanation": "shǒu shí 与 shōu shi 声调不同，守时指按时、不迟到。"}], "explanations": {"收拾": "正确答案：收拾（shōu shi），指把乱的东西放好，让地方整齐干净。", "首饰": "shǒu（第三声）与 shōu（第一声）声调不同，首饰指戴在身上的装饰品，如项链、戒指。", "收视": "收视的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是观看电视的情况，如收视率。", "手势": "shǒu shì 与 shōu shi 两个音节的声调都不同，手势指用手做出的动作。", "守时": "shǒu shí 与 shōu shi 声调不同，守时指按时、不迟到。"}, "sentence_index": null, "correct_answer": "收拾"}, "level_3": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确。“收拾厨房”指把乱的厨房整理干净，符合句中的语境。"}, {"text": "散步", "is_correct": false, "explanation": "配价：散步是不及物动词，后面不能直接带“厨房”作宾语。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：唱歌的对象是歌曲，不能说“唱厨房”，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，不能带“厨房”作宾语，句子不成立。"}], "explanations": {"收拾": "正确。“收拾厨房”指把乱的厨房整理干净，符合句中的语境。", "散步": "配价：散步是不及物动词，后面不能直接带“厨房”作宾语。", "唱歌": "搭配：唱歌的对象是歌曲，不能说“唱厨房”，句意不通。", "睡觉": "配价：睡觉是不及物动词，不能带“厨房”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "收拾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用手收拾眼泪。", "explanation": "这里应该用〈擦〉。收拾指把乱的东西放好、让地方整齐，眼泪不是可以收拾的东西，要说“擦眼泪”。"}, {"text": "妈妈把花瓶收拾在客厅中央。", "explanation": "这里应该用〈摆〉。收拾指把乱的东西整理好、使地方整齐，不表示把物品摆放到某处，此处要说“摆在客厅中央”。"}, {"text": "他工作三年后，终于收拾了所有欠款。", "explanation": "这里应该用〈还清〉。收拾指把乱的东西放好、使整洁，欠款不是可以整理的东西，不能说“收拾欠款”，要说“还清所有欠款”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确答案：收拾（shōu shi），指把乱的东西放好，让地方整齐干净。"}, {"text": "收市", "is_correct": false, "explanation": "收市的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是市场或股市收盘。"}, {"text": "守势", "is_correct": false, "explanation": "shǒu shì 与 shōu shi 两个音节的声调都不同，守势指防守的态势。"}, {"text": "受试", "is_correct": false, "explanation": "shòu shì 与 shōu shi 声调不同，受试指接受试验或测试的人，是研究用语。"}], "explanations": {"收拾": "正确答案：收拾（shōu shi），指把乱的东西放好，让地方整齐干净。", "收市": "收市的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是市场或股市收盘。", "守势": "shǒu shì 与 shōu shi 两个音节的声调都不同，守势指防守的态势。", "受试": "shòu shì 与 shōu shi 声调不同，受试指接受试验或测试的人，是研究用语。"}, "sentence_index": null, "correct_answer": "收拾"}, "level_3": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确。“一边收拾屋子，一边听音乐”指整理屋子的同时听音乐，符合句意。"}, {"text": "思考", "is_correct": false, "explanation": "搭配：思考的对象是问题或想法，不能说“思考屋子”。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳是不及物动词，不能带“屋子”作宾语，句子不成立。"}, {"text": "关心", "is_correct": false, "explanation": "搭配：关心的对象是人或事情，说“关心屋子”不符合搭配，句意不通。"}], "explanations": {"收拾": "正确。“一边收拾屋子，一边听音乐”指整理屋子的同时听音乐，符合句意。", "思考": "搭配：思考的对象是问题或想法，不能说“思考屋子”。", "跳": "配价：跳是不及物动词，不能带“屋子”作宾语，句子不成立。", "关心": "搭配：关心的对象是人或事情，说“关心屋子”不符合搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "收拾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她收拾完了那首歌，观众热烈鼓掌。", "explanation": "这里应该用〈唱〉。收拾指把乱的东西放好、使地方整齐，歌曲不能收拾，要说“唱完那首歌”。"}, {"text": "这首曲子被他收拾得很动听。", "explanation": "这里应该用〈演奏〉。收拾指整理物品、使整齐，曲子不能收拾，要说“演奏得很动听”。"}, {"text": "他认真收拾了这次考试。", "explanation": "这里应该用〈参加〉。收拾指把乱的东西放好、使整洁，考试不是可以整理的东西，要说“参加这次考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把厨房收拾干净着。", "corrected_sentence": "我把厨房收拾干净了。", "error_description": "错误：结果补语“干净”表示动作完成后的结果，句末应用表示完成的“了”，却用了持续体的“着”，成了“收拾干净着”。正确：“收拾干净了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把房间收拾很整齐。", "corrected_sentence": "他把房间收拾得很整齐。", "error_description": "错误：动词和状态补语之间漏了“得”。正确：“收拾得很整齐”中，“得”连接动词和状态补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弄乱", "is_correct": true, "explanation": "正确。“弄乱”与“收拾”（使物品有条理）意思相反，指把东西弄得杂乱无章。"}, {"text": "欢迎", "is_correct": false, "explanation": "与“收拾”没有反义关系，欢迎指以热情的态度接待。"}, {"text": "生长", "is_correct": false, "explanation": "与“收拾”没有反义关系，生长指生物逐渐长大。"}, {"text": "制造", "is_correct": false, "explanation": "与“收拾”没有反义关系，制造指用人力把材料做成东西。"}], "correct_answer": "弄乱", "explanations": {"弄乱": "正确。“弄乱”与“收拾”（使物品有条理）意思相反，指把东西弄得杂乱无章。", "欢迎": "与“收拾”没有反义关系，欢迎指以热情的态度接待。", "生长": "与“收拾”没有反义关系，生长指生物逐渐长大。", "制造": "与“收拾”没有反义关系，制造指用人力把材料做成东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "搞乱", "is_correct": true, "explanation": "正确。“搞乱”与“收拾”（使物品有条理）意思相反，指把东西弄乱。"}, {"text": "保存", "is_correct": false, "explanation": "与“收拾”没有反义关系，保存指让东西不受损失地留存下来。"}, {"text": "搬运", "is_correct": false, "explanation": "与“收拾”没有反义关系，搬运指把东西从一处运到另一处。"}, {"text": "呼吸", "is_correct": false, "explanation": "与“收拾”没有反义关系，呼吸指生物吸入和呼出空气。"}], "correct_answer": "搞乱", "explanations": {"搞乱": "正确。“搞乱”与“收拾”（使物品有条理）意思相反，指把东西弄乱。", "保存": "与“收拾”没有反义关系，保存指让东西不受损失地留存下来。", "搬运": "与“收拾”没有反义关系，搬运指把东西从一处运到另一处。", "呼吸": "与“收拾”没有反义关系，呼吸指生物吸入和呼出空气。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "整理、整顿；使有条理或清洁。", "primary_collocate": null, "pronunciation": "shōu shi", "ipa": "ʂou̯˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "明天去北京，我今晚要收拾行李。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收拾好书包，就去上学了。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们收拾一下桌上的书和笔。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把桌上散落的纸收拾好，放进了抽屉。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，他把东西收拾得很整齐。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行前我收拾了两个大箱子。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想先收拾一下书桌，再去找老师。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家一起收拾器材。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬家，同事们正收拾着文件。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收拾一下文件，再给经理看。", "target_word": "收拾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收拾了", "label": "完成体"}, {"form": "收拾着", "label": "持续体"}, {"form": "收拾过", "label": "经历体"}, {"form": "收拾收拾", "label": "重叠"}], "register": "口语", "sense_fingerprint": "整理行李、物品、文件等，使有条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确答案：收拾（shōu shi），指整理行李、物品，使其有条理。"}, {"text": "首饰", "is_correct": false, "explanation": "shǒu（第三声）与 shōu（第一声）声调不同，首饰指戴在身上的装饰品。"}, {"text": "手势", "is_correct": false, "explanation": "shǒu shì 与 shōu shi 两个音节的声调都不同，手势指用手做出的动作。"}, {"text": "守时", "is_correct": false, "explanation": "shǒu shí 与 shōu shi 声调不同，守时指按时、不迟到。"}, {"text": "收市", "is_correct": false, "explanation": "收市的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是市场收盘。"}], "explanations": {"收拾": "正确答案：收拾（shōu shi），指整理行李、物品，使其有条理。", "首饰": "shǒu（第三声）与 shōu（第一声）声调不同，首饰指戴在身上的装饰品。", "手势": "shǒu shì 与 shōu shi 两个音节的声调都不同，手势指用手做出的动作。", "守时": "shǒu shí 与 shōu shi 声调不同，守时指按时、不迟到。", "收市": "收市的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是市场收盘。"}, "sentence_index": null, "correct_answer": "收拾"}, "level_3": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确。“收拾行李”指把物品整理装好，准备出行，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不能说“唱行李”，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：散步是不及物动词，不能带“行李”作宾语。"}, {"text": "骑", "is_correct": false, "explanation": "配价：骑的对象是车或动物，不能说“骑行李”，句子不成立。"}], "explanations": {"收拾": "正确。“收拾行李”指把物品整理装好，准备出行，符合句意。", "唱": "搭配：唱的对象是歌曲，不能说“唱行李”，句意不通。", "散步": "配价：散步是不及物动词，不能带“行李”作宾语。", "骑": "配价：骑的对象是车或动物，不能说“骑行李”，句子不成立。"}, "sentence_index": 0, "correct_answer": "收拾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用手收拾眼泪。", "explanation": "这里应该用〈擦〉。收拾指把乱的东西放好、整理有条理，眼泪不是可以收拾的东西，要说“擦眼泪”。"}, {"text": "老师收拾完了一个故事。", "explanation": "这里应该用〈讲〉。收拾指整理物品、使有条理，故事不能收拾，要说“讲完一个故事”。"}, {"text": "他每天早上都收拾一个小时的跑步。", "explanation": "这里应该用〈坚持〉。收拾指把物品整理得有条理，跑步不是可以整理的东西，要说“坚持跑一个小时步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确答案：收拾（shōu shi），指整理文件、物品，使其有条理。"}, {"text": "收视", "is_correct": false, "explanation": "收视的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是观看电视的情况。"}, {"text": "守势", "is_correct": false, "explanation": "shǒu shì 与 shōu shi 两个音节的声调都不同，守势指防守的态势。"}, {"text": "受试", "is_correct": false, "explanation": "shòu shì 与 shōu shi 声调不同，受试指接受试验或测试的人，是研究用语。"}], "explanations": {"收拾": "正确答案：收拾（shōu shi），指整理文件、物品，使其有条理。", "收视": "收视的第二音节是第四声 shì，与收拾的轻声 shi 声调不同，意思是观看电视的情况。", "守势": "shǒu shì 与 shōu shi 两个音节的声调都不同，守势指防守的态势。", "受试": "shòu shì 与 shōu shi 声调不同，受试指接受试验或测试的人，是研究用语。"}, "sentence_index": null, "correct_answer": "收拾"}, "level_3": {"options": [{"text": "收拾", "is_correct": true, "explanation": "正确。“收拾一下书桌”指把书桌上的东西整理好，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳是不及物动词，不能带“书桌”作宾语，句子不成立。"}, {"text": "关心", "is_correct": false, "explanation": "搭配：关心的对象是人或事情，不能说“关心书桌”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：哭是不及物动词，不能带“书桌”作宾语，句意不通。"}], "explanations": {"收拾": "正确。“收拾一下书桌”指把书桌上的东西整理好，符合句意。", "跳": "配价：跳是不及物动词，不能带“书桌”作宾语，句子不成立。", "关心": "搭配：关心的对象是人或事情，不能说“关心书桌”。", "哭": "配价：哭是不及物动词，不能带“书桌”作宾语，句意不通。"}, "sentence_index": 6, "correct_answer": "收拾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他收拾了一封长信。", "explanation": "这里应该用〈写〉。收拾指把东西整理好、使有条理，信件不是可以整理的东西，要说“写了一封长信”。"}, {"text": "她收拾完了一支舞。", "explanation": "这里应该用〈跳〉。收拾指整理物品、使整齐，舞蹈不能收拾，要说“跳完一支舞”。"}, {"text": "他收拾了一杯热水。", "explanation": "这里应该用〈倒〉。收拾指把乱的东西放好，水不是可以收拾的东西，要说“倒了一杯热水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把行李收拾了好。", "corrected_sentence": "我把行李收拾好了。", "error_description": "错误：“了”放在结果补语“好”之前。正确：“收拾好”之后加“了”，即“收拾好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把书包收拾很整齐。", "corrected_sentence": "他把书包收拾得很整齐。", "error_description": "错误：动词和状态补语之间漏了“得”。正确：“收拾得很整齐”中，“得”连接动词和状态补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
