INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理国家大事、很有名的人。", "primary_collocate": null, "pronunciation": "zhèng zhì jiā", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位政治家管理国家很多年。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位很有名的政治家。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政治家每天都要处理国家大事。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老政治家一直在为国家工作。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人都想听政治家怎么说。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位政治家在电视上讲了国家的未来。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候的梦想是当一名政治家。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位政治家带着人民走过了困难的日子。", "target_word": "政治家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位好的政治家应该先想到人民。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们都很尊敬这位为国家做了很多事的政治家。", "target_word": "政治家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位政治家", "label": "量词"}, {"form": "一名政治家", "label": "量词"}], "register": "中性", "sense_fingerprint": "管理国家大事、很有名的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为职业，不管理国家，句意不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与「管理国家」无关。"}, {"text": "政治家", "is_correct": true, "explanation": "正确：政治家管理国家大事，与句意「管理国家很多年」相符。"}, {"text": "企业家", "is_correct": false, "explanation": "搭配：「管理」的对象应是国家事务，企业家多管理企业，不能说管理国家。"}], "explanations": {"歌手": "语义：歌手以唱歌为职业，不管理国家，句意不通。", "厨师": "语义：厨师的工作是做饭，与「管理国家」无关。", "政治家": "正确：政治家管理国家大事，与句意「管理国家很多年」相符。", "企业家": "搭配：「管理」的对象应是国家事务，企业家多管理企业，不能说管理国家。"}, "sentence_index": 0, "correct_answer": "政治家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位政治家每天在教室里教孩子们写字，大家都很喜欢他。", "explanation": "这里应该用〈教师〉。教师教书育人，是普通职业；政治家是管理国家大事的人，不负责教孩子写字。"}, {"text": "政治家每天很早起床，去菜市场卖自己种的蔬菜。", "explanation": "这里应该用〈菜农〉。菜农种菜、卖菜，是普通劳动者；政治家管理国家大事，不去卖菜。"}, {"text": "他的专业是政治家，大学毕业后去研究所工作。", "explanation": "这里应该用〈政治学〉。政治学是学科名称，政治家指人，不能作专业名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是职业或身份，不能作为「当」的对象。"}, {"text": "政治家", "is_correct": true, "explanation": "正确：「当一名政治家」是常见说法，表示职业理想，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「一名」只用于人，石头应用「块」，而且不能作职业。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：「当」后需要指人的职业名词，小猫不能作职业。"}], "explanations": {"雨伞": "语义：雨伞不是职业或身份，不能作为「当」的对象。", "政治家": "正确：「当一名政治家」是常见说法，表示职业理想，与句意相符。", "石头": "搭配：「一名」只用于人，石头应用「块」，而且不能作职业。", "小猫": "配价：「当」后需要指人的职业名词，小猫不能作职业。"}, "sentence_index": 6, "correct_answer": "政治家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政治家在法庭上认真审理案件，维护了公平。", "explanation": "这里应该用〈法官〉。法官在法庭上审理案件、维护公平；政治家管理国家大事，不负责审理案件。"}, {"text": "这位政治家每天在工厂里修理机器，手上全是油污。", "explanation": "这里应该用〈工人〉。修理机器是工人的工作；政治家管理国家大事，不会去工厂做这样的工作。"}, {"text": "政治家在医院里救了很多病人。", "explanation": "这里应该用〈医生〉。在医院救治病人是医生的工作，政治家不能替代医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的叔叔想当一本政治家。", "corrected_sentence": "我的叔叔想当一名政治家。", "error_description": "量词错误：「政治家」指人，应用「名」或「位」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本政治家很有能力。", "corrected_sentence": "那位政治家很有能力。", "error_description": "量词错误：「政治家」指人，应用「位」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
