INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事政治活动并有较大影响和作为的人。", "primary_collocate": null, "pronunciation": "zhèng zhì jiā", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "她从年轻时起就是有影响的政治家。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位政治家参加了很多政治活动。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家出过不少有作为的政治家。", "target_word": "政治家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但是商人，还是一位政治家。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位政治家的话影响了很多人。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政治家的一句话可能改变很多事。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一本关于政治家的传记。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位女政治家在大会上发了言。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政治家需要听听老百姓的想法。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从律师变成了有名的政治家。", "target_word": "政治家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位政治家", "label": "量词"}, {"form": "一名政治家", "label": "量词"}], "register": "中性", "sense_fingerprint": "从事政治活动、有影响有作为的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有影响力或作为，与「有影响的人」不符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「有影响」多指人或团体，花园不能说有影响。"}, {"text": "政治家", "is_correct": true, "explanation": "正确：「有影响的政治家」指从事政治活动、有作为的人，与句意相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不能有影响或作为，句意不通。"}], "explanations": {"石头": "语义：石头没有影响力或作为，与「有影响的人」不符。", "花园": "搭配：「有影响」多指人或团体，花园不能说有影响。", "政治家": "正确：「有影响的政治家」指从事政治活动、有作为的人，与句意相符。", "雨伞": "语义：雨伞是日用品，不能有影响或作为，句意不通。"}, "sentence_index": 0, "correct_answer": "政治家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是一位政治家，他每天在家里为人做衣服。", "explanation": "这里应该用〈裁缝〉。裁缝在家里为人做衣服，是手艺人；政治家从事政治活动，不做这种工作。"}, {"text": "这位政治家在比赛中打破了纪录，大家都为他鼓掌。", "explanation": "这里应该用〈运动员〉。运动员参加比赛、打破纪录；政治家从事政治活动，不在赛场上比赛。"}, {"text": "这位政治家每天凌晨四点起床去报社送报纸，风雨无阻。", "explanation": "这里应该用〈送报员〉。每天凌晨送报纸是送报员的工作；政治家从事政治活动，不做这种工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时用品，没有生平可以记述，「关于闹钟的传记」句意不通。"}, {"text": "政治家", "is_correct": true, "explanation": "正确：「关于政治家的传记」记述政治家的生平，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，没有生平可以记述，「关于窗户的传记」句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：传记记述的是人的生平，雨伞不能作为传记的对象。"}], "explanations": {"闹钟": "语义：闹钟是计时用品，没有生平可以记述，「关于闹钟的传记」句意不通。", "政治家": "正确：「关于政治家的传记」记述政治家的生平，与句意相符。", "窗户": "语义：窗户是建筑部件，没有生平可以记述，「关于窗户的传记」句意不通。", "雨伞": "搭配：传记记述的是人的生平，雨伞不能作为传记的对象。"}, "sentence_index": 6, "correct_answer": "政治家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政治家在街上抓住了小偷。", "explanation": "这里应该用〈警察〉。抓捕小偷是警察的工作，政治家不能替代警察。"}, {"text": "政治家每天核对账目，工作很细心。", "explanation": "这里应该用〈会计〉。核对账目是会计的工作，政治家不做这项工作。"}, {"text": "他的研究方向是政治家，每天在实验室做实验。", "explanation": "这里应该用〈化学〉。化学是学科名称，可以作研究方向；政治家指人，不能作研究方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时就是一本有影响的政治家。", "corrected_sentence": "他年轻时就是一位有影响的政治家。", "error_description": "量词错误：「政治家」指人，应用「位」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本政治家很有影响力。", "corrected_sentence": "那位政治家很有影响力。", "error_description": "量词错误：「政治家」指人，应用「位」，「本」多用于书籍，用在这里不当。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
