INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个民族或群体世代相传的文化习俗、观念与行为方式。", "primary_collocate": null, "pronunciation": "wén huà chuán tǒng", "ipa": "wən˧˥ xwa˥˩ ʈʂʰwan˧˥ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "每个民族都有自己的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尊敬老人是中国的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家的文化传统很不一样。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该保护自己的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外长大，不太了解家乡的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的文化传统，对礼貌的看法也不同。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市很新，也留着老的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言，也要了解那里的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重视家人是很多地方共同的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人也要学着理解自己的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "文化傳統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "文化传统:民族或群体世代相传的习俗与观念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文化传统", "is_correct": true, "explanation": "正确。“文化传统”指民族世代相传的文化习俗、观念与行为方式，符合句意。"}, {"text": "宇宙飞船", "is_correct": false, "explanation": "语义：“宇宙飞船”是航天器，不是民族世代相传的习俗或观念，句子说不通。"}, {"text": "心脏病", "is_correct": false, "explanation": "语义：“心脏病”是疾病，不是民族的习俗或观念，“每个民族都有自己的心脏病”句意不通。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：“红绿灯”是交通设施，不是民族的习俗或观念，句子说不通。"}], "explanations": {"文化传统": "正确。“文化传统”指民族世代相传的文化习俗、观念与行为方式，符合句意。", "宇宙飞船": "语义：“宇宙飞船”是航天器，不是民族世代相传的习俗或观念，句子说不通。", "心脏病": "语义：“心脏病”是疾病，不是民族的习俗或观念，“每个民族都有自己的心脏病”句意不通。", "红绿灯": "语义：“红绿灯”是交通设施，不是民族的习俗或观念，句子说不通。"}, "sentence_index": 0, "correct_answer": "文化传统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早起跑步，这是我的文化传统。", "explanation": "这里应该用〈习惯〉。个人的日常做法是个人习惯，不是民族或群体世代相传的文化习俗。"}, {"text": "他的文化传统就是每天打篮球。", "explanation": "这里应该用〈爱好〉。个人的兴趣是爱好，不是民族或群体世代相传的文化习俗。"}, {"text": "我的文化传统是每天写日记。", "explanation": "这里应该用〈习惯〉。个人的做法是习惯，不是民族或群体世代相传的文化习俗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文化传统", "is_correct": true, "explanation": "正确。“文化传统”指世代相传的习俗和观念，“留着老的文化传统”符合句意。"}, {"text": "心脏病", "is_correct": false, "explanation": "语义：“心脏病”是疾病，城市不能“留着老的心脏病”，句意不通。"}, {"text": "眼睛颜色", "is_correct": false, "explanation": "语义：“眼睛颜色”是外貌特征，城市不能“留着老的眼睛颜色”，句意不通。"}, {"text": "心跳速度", "is_correct": false, "explanation": "语义：“心跳速度”是生理指标，城市不能“留着老的心跳速度”，句意不通。"}], "explanations": {"文化传统": "正确。“文化传统”指世代相传的习俗和观念，“留着老的文化传统”符合句意。", "心脏病": "语义：“心脏病”是疾病，城市不能“留着老的心脏病”，句意不通。", "眼睛颜色": "语义：“眼睛颜色”是外貌特征，城市不能“留着老的眼睛颜色”，句意不通。", "心跳速度": "语义：“心跳速度”是生理指标，城市不能“留着老的心跳速度”，句意不通。"}, "sentence_index": 6, "correct_answer": "文化传统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年轻人也要学着坚持自己的文化传统：每天早起锻炼。", "explanation": "这里应该用〈习惯〉。个人每天的锻炼是个人习惯，不是民族或群体世代相传的文化习俗。"}, {"text": "这个年轻人的文化传统是每天打游戏。", "explanation": "这里应该用〈习惯〉。个人的日常做法是个人习惯，不是民族或群体世代相传的文化习俗。"}, {"text": "他的文化传统就是每天喝一杯茶。", "explanation": "这里应该用〈习惯〉。个人的日常做法是个人习惯，不是民族或群体世代相传的文化习俗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节日里保留这只文化传统很重要。", "corrected_sentence": "节日里保留这种文化传统很重要。", "error_description": "量词错误：“文化传统”应用量词“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻人要好学自己的文化传统。", "corrected_sentence": "年轻人要学好自己的文化传统。", "error_description": "补语错误：“学好”是动补结构，表示学会；“好学”是形容词，不能带宾语“自己的文化传统”。应说“学好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
