INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96385, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有很多好看的山水，大家去玩的地方。", "primary_collocate": null, "pronunciation": "jǐng qū", "ipa": "tɕiŋ˨˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个景区有山有水，风景很美。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们全家去山里的景区玩了一天。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区里的湖水很清，很多人在湖边照相。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区的门票不贵，我想带朋友去看看。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车到景区门口，已经中午了。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区里有一座高山，爬上去要两个小时。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天景区里人很多，我们早点出发吧。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区离城市不远，坐一个小时的车就到。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在景区里走了一天，觉得很累。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区的山水真好看，我拍了很多照片。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "旅游景区", "label": "复合"}, {"form": "景區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有山水风景、供人游玩的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96385, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "景区", "is_correct": true, "explanation": "正确：景区指有山水、供人游玩的地方，与“有山有水，风景很美”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是有山有水、风景优美的地方。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“风景很美”描述的是地方，歌手不能与之搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，没有山水风景。"}], "explanations": {"景区": "正确：景区指有山水、供人游玩的地方，与“有山有水，风景很美”的语境相符。", "厨房": "语义：厨房不是有山有水、风景优美的地方。", "歌手": "搭配：“风景很美”描述的是地方，歌手不能与之搭配。", "手机": "语义：手机是电子设备，没有山水风景。"}, "sentence_index": 0, "correct_answer": "景区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景区给我们讲了一个有意思的故事。", "explanation": "这里应该用〈导游〉。讲故事是人的行为，景区是游览的地方，不能讲故事。"}, {"text": "景区向我借了一把伞，还没还。", "explanation": "这里应该用〈游客〉。借伞、还伞是人的行为，景区是游览的地方，不能向别人借东西。"}, {"text": "景区笑着跟我们握了手。", "explanation": "这里应该用〈工作人员〉。握手、笑是人的动作，景区是地方，不能做这些事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景区", "is_correct": true, "explanation": "正确：景区指有山水、供人游玩的地方，与“夏天里人很多”的语境相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不会挤满人。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会挤满人。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机里不会挤满人。"}], "explanations": {"景区": "正确：景区指有山水、供人游玩的地方，与“夏天里人很多”的语境相符。", "书包": "语义：书包里不会挤满人。", "冰箱": "语义：冰箱里不会挤满人。", "手机": "语义：手机里不会挤满人。"}, "sentence_index": 6, "correct_answer": "景区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "景区替我参加了昨天的考试。", "explanation": "这里应该用〈同学〉。参加考试是人的行为，景区是地方，不能替人考试。"}, {"text": "景区给我们批改了数学作业，很认真。", "explanation": "这里应该用〈老师〉。批改作业是老师的工作，景区不能批改作业。"}, {"text": "景区给我们端来了茶。", "explanation": "这里应该用〈服务员〉。端茶是人的动作，景区不能端茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于找到了一棵景区。", "corrected_sentence": "我们终于找到了一个景区。", "error_description": "量词错误：“棵”用于树木等植物，景区应用量词“个”，应说“一个景区”，不能说“一棵景区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去着那个景区两次。", "corrected_sentence": "我们去过那个景区两次。", "error_description": "体标错误：表示曾经去过要用“过”，“着”表示持续状态，不能说“去着”，应说“去过那个景区两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
