INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以自然或人文景观为主、供游览参观的区域。", "primary_collocate": null, "pronunciation": "jǐng qū", "ipa": "tɕiŋ˨˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个景区里有很多古老的建筑。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区早上八点开门，晚上五点关门。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客进入景区要先买票。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区里不能抽烟，也不能乱扔垃圾。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区每年接待几百万游客。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区的工作人员告诉我们怎么走。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个著名的景区当导游。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区里有一座千年古寺，很多人来参观。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护环境，景区限制每天的游客数量。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区既有山水，也有历史文化。", "target_word": "景区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "旅游景区", "label": "复合"}, {"form": "景區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有管理、可售票的游览参观区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "景区", "is_correct": true, "explanation": "正确：景区是有管理、可售票的游览区域，与“里有很多古老的建筑”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里不会有很多古老的建筑。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，里面不可能有古老的建筑。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“里有很多古老的建筑”要求能容纳建筑的场所，手机不能这样搭配。"}], "explanations": {"景区": "正确：景区是有管理、可售票的游览区域，与“里有很多古老的建筑”相符。", "厨房": "语义：厨房里不会有很多古老的建筑。", "冰箱": "语义：冰箱是电器，里面不可能有古老的建筑。", "手机": "搭配：“里有很多古老的建筑”要求能容纳建筑的场所，手机不能这样搭配。"}, "sentence_index": 0, "correct_answer": "景区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景区替我们画了一幅肖像。", "explanation": "这里应该用〈画家〉。画肖像是画家的工作，景区不能作画。"}, {"text": "景区没带伞，淋湿了全身。", "explanation": "这里应该用〈游客〉。带伞、淋雨是人的行为，景区是游览的地方，不会带伞，也不会淋雨。"}, {"text": "景区给病人打了针。", "explanation": "这里应该用〈医生〉。打针是医生的工作，景区不能给病人打针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景区", "is_correct": true, "explanation": "正确：景区是可以当导游的游览区域，与“当导游”的语境相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是可以当导游的地方。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“当导游”要在景点或博物馆，银行不搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是景点，不能在那里当导游。"}], "explanations": {"景区": "正确：景区是可以当导游的游览区域，与“当导游”的语境相符。", "医院": "语义：医院不是可以当导游的地方。", "银行": "搭配：“当导游”要在景点或博物馆，银行不搭配。", "厨房": "语义：厨房不是景点，不能在那里当导游。"}, "sentence_index": 6, "correct_answer": "景区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "景区帮我写完了作业。", "explanation": "这里应该用〈同学〉。写作业是学生的事，景区是地方，不能替人写作业。"}, {"text": "景区教我们游泳。", "explanation": "这里应该用〈教练〉。景区是地方，不能教人游泳。"}, {"text": "景区给我们端来了茶，很热情。", "explanation": "这里应该用〈服务员〉。端茶、招待是人的动作，景区不能这样做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参观了一棵景区。", "corrected_sentence": "我们参观了一个景区。", "error_description": "量词错误：“棵”用于植物，景区应说“一个景区”，不能说“一棵景区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从没去着那个景区。", "corrected_sentence": "我们从没去过那个景区。", "error_description": "体标错误：表示有过这种经历要用“过”，“着”表示持续状态，不能说“去着”，应说“去过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
