INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印在书上的一串数字，用来分清是哪一本书。", "primary_collocate": null, "pronunciation": "shū hào", "ipa": "ʂu˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "书的封底印着书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的书号在哪儿？", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书号写在本子上。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记下了这本书的书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的老师按书号找书。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每本书都有自己的书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书号是一串数字。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，书号就在条形码上面。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用书号查到了这本书。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书号印在书的最后一页。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "国际标准书号", "label": "复合词"}, {"form": "统一书号", "label": "复合词"}], "register": "中性", "sense_fingerprint": "书上印的数字，用来认出哪一本书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书号", "is_correct": true, "explanation": "正确：书的封底印着的是书号，即这本书的编号。"}, {"text": "心情", "is_correct": false, "explanation": "语义：书的封底不会印“心情”，句子说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：书的封底不印温度，这里讲不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是用嘴或鼻子感觉的，不能印在书的封底上。"}], "explanations": {"书号": "正确：书的封底印着的是书号，即这本书的编号。", "心情": "语义：书的封底不会印“心情”，句子说不通。", "温度": "语义：书的封底不印温度，这里讲不通。", "味道": "语义：味道是用嘴或鼻子感觉的，不能印在书的封底上。"}, "sentence_index": 0, "correct_answer": "书号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的书号很好听。", "explanation": "这里应该用〈书名〉。书名是文字，可以“好听”；书号是一串数字，不能用“好听”来形容。"}, {"text": "他给我看了这本书的一座书号。", "explanation": "这里不能用“座”（山、楼房等的量词）。书号应用“个”，说“一个书号”。"}, {"text": "这本书的书号是一位很有名的老师。", "explanation": "这里应该用〈作者〉。作者是人，可以是“一位老师”；书号是数字，不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书号", "is_correct": true, "explanation": "正确：书号是一串数字，是图书的编号。"}, {"text": "姓名", "is_correct": false, "explanation": "语义：姓名是文字，不是一串数字。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是文字，不是一串数字，句子说不通。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“一串”一般用于数字、钥匙等，不说“一串故事”。"}], "explanations": {"书号": "正确：书号是一串数字，是图书的编号。", "姓名": "语义：姓名是文字，不是一串数字。", "歌词": "语义：歌词是文字，不是一串数字，句子说不通。", "故事": "搭配：“一串”一般用于数字、钥匙等，不说“一串故事”。"}, "sentence_index": 6, "correct_answer": "书号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套书的书号是三十元。", "explanation": "这里应该用〈价格〉。书号是一串数字，不是钱数；“三十元”只能用来说价格。"}, {"text": "我在书架上找到了一本书号。", "explanation": "这里不能用“本”（书的量词）。书号是数字编码，应说“一个书号”。"}, {"text": "这本书是一家书号出的。", "explanation": "这里应该用〈出版社〉。书是出版社出的；书号只是编码，不能出书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每本书的封底都印着一只书号。", "corrected_sentence": "每本书的封底都印着一个书号。", "error_description": "错误在量词“只”。“只”用于动物等，不能用于书号。书号应用量词“个”，正确的是“一个书号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书的书号印版权页上。", "corrected_sentence": "这本书的书号印在版权页上。", "error_description": "漏掉了“在”。“印”后面要用“在”引出地点，应说“印在版权页上”，不能直接说“印版权页上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
