INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "出版社为每本书编的国际标准书号，用于识别图书。", "primary_collocate": null, "pronunciation": "shū hào", "ipa": "ʂu˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "出版社给新书编了书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有书号，书就不能出版。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社申请了十个书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社每年只有一百个书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店用书号管理图书。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书的书号已经办好了。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑给这本小说编好了书号。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上书店靠书号识别每一本书。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书号出错了，书只好重新印。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书号属于另一家出版社。", "target_word": "书号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "国际标准书号", "label": "复合词"}, {"form": "统一书号", "label": "复合词"}], "register": "中性", "sense_fingerprint": "出版社给新书编的标准号码，用来识别图书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书号", "is_correct": true, "explanation": "正确：出版社给新书编的是书号，用来识别图书。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，出版社不会“编”作者，句子说不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能被“编”，这里讲不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“编”不用于桌子这类家具，不能说“编了桌子”。"}], "explanations": {"书号": "正确：出版社给新书编的是书号，用来识别图书。", "作者": "语义：作者是人，出版社不会“编”作者，句子说不通。", "墨水": "语义：墨水不能被“编”，这里讲不通。", "桌子": "搭配：“编”不用于桌子这类家具，不能说“编了桌子”。"}, "sentence_index": 0, "correct_answer": "书号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游戏公司申请了一个书号才能上线。", "explanation": "这里应该用〈版号〉。游戏上线要审批“版号”；书号是给图书用的，游戏不用书号。"}, {"text": "杂志每年都要申请一个书号。", "explanation": "这里应该用〈刊号〉。杂志用“刊号”；书号是图书的编号，杂志不申请书号。"}, {"text": "出版社领了一棵书号。", "explanation": "这里不能用“棵”（树的量词）。书号应用“个”，说“一个书号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书号", "is_correct": true, "explanation": "正确：编辑给小说编好的是书号，即图书的编码。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“编好”一般不接饭菜，这里说不通。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：编辑不会“编好”湖泊，这里讲不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是机器，不能被编辑“编好”。"}], "explanations": {"书号": "正确：编辑给小说编好的是书号，即图书的编码。", "饭菜": "搭配：“编好”一般不接饭菜，这里说不通。", "湖泊": "语义：编辑不会“编好”湖泊，这里讲不通。", "闹钟": "语义：闹钟是机器，不能被编辑“编好”。"}, "sentence_index": 6, "correct_answer": "书号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些文件都有书号，方便查找。", "explanation": "这里应该用〈编号〉。文件用“编号”来查找；书号只属于图书，文件不用书号。"}, {"text": "出版社刚收到一座书号。", "explanation": "这里不能用“座”（山、楼房等的量词）。书号应用“个”，说“一个书号”。"}, {"text": "公司办好了书号，就可以营业了。", "explanation": "这里应该用〈营业执照〉。公司要办好营业执照才能营业；书号是图书的编号，与公司营业无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出版社给这本新书申请了一只书号。", "corrected_sentence": "出版社给这本新书申请了一个书号。", "error_description": "错误在量词“只”。“只”用于动物等，不能用于书号。书号应用“个”，正确的是“一个书号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书号是出版社给这本书编了。", "corrected_sentence": "书号是出版社给这本书编的。", "error_description": "“是……的”结构强调动作的施事，动词后要用“的”，不能用“了”。应说“书号是出版社给这本书编的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
