INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "替国家去查坏人、请法官判案的人。", "primary_collocate": null, "pronunciation": "jiǎn chá guān", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "检察官会查清坏人做了什么事。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧里的检察官常常很忙。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官请法官判这个坏人坐牢。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是检察官，每天都在查案子。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位检察官找到了很多证据。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官站在法庭上，说明坏人做过什么。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大以后想当检察官，帮国家查坏人。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件案子很大，检察官查了半年。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官问证人：你那天看到了什么？", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官听完检察官的话，还要听律师说。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "首席检察官", "label": "复合"}, {"form": "檢察官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "替国家查案、请法官判案的人（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检察官", "is_correct": true, "explanation": "正确：检察官负责查清案件中坏人做了什么，与句子语境相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责调查坏人做了什么。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“查清事情”是调查工作，歌手不搭配。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不负责调查案件。"}], "explanations": {"检察官": "正确：检察官负责查清案件中坏人做了什么，与句子语境相符。", "厨师": "语义：厨师不负责调查坏人做了什么。", "歌手": "搭配：“查清事情”是调查工作，歌手不搭配。", "司机": "语义：司机不负责调查案件。"}, "sentence_index": 0, "correct_answer": "检察官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "检察官在路口指挥交通。", "explanation": "这里应该用〈警察〉。指挥交通是警察的工作，检察官不负责交通。"}, {"text": "检察官判了他三年徒刑。", "explanation": "这里应该用〈法官〉。判刑是法官的职权，检察官不能判刑。"}, {"text": "我叔叔是检察官，每天在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。为被告辩护是律师的职责，检察官是替国家查坏人，不替被告说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检察官", "is_correct": true, "explanation": "正确：检察官的职责是帮国家查坏人，与句子语境相符。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员不负责帮国家查坏人，与句中“查坏人”不符。"}, {"text": "花匠", "is_correct": false, "explanation": "搭配：“帮国家查坏人”是司法工作，花匠不搭配。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师不做查坏人的工作。"}], "explanations": {"检察官": "正确：检察官的职责是帮国家查坏人，与句子语境相符。", "运动员": "语义：运动员不负责帮国家查坏人，与句中“查坏人”不符。", "花匠": "搭配：“帮国家查坏人”是司法工作，花匠不搭配。", "理发师": "语义：理发师不做查坏人的工作。"}, "sentence_index": 6, "correct_answer": "检察官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "检察官教我们游泳。", "explanation": "这里应该用〈教练〉。教游泳是教练的工作，检察官不做这件事。"}, {"text": "检察官为病人打针。", "explanation": "这里应该用〈医生〉。为病人打针是医生的工作。"}, {"text": "检察官在舞台上唱歌。", "explanation": "这里应该用〈歌手〉。在舞台上唱歌是歌手的工作，检察官不唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我见过一位检察官们。", "corrected_sentence": "我见过一位检察官。", "error_description": "“们”的位置错误：“们”表示复数，不能跟在“一位”这样的数量词之后，应说“一位检察官”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在电视上见过一棵检察官。", "corrected_sentence": "我们在电视上见过一位检察官。", "error_description": "量词错误：“棵”用于植物，检察官是人，应用量词“位”，应说“一位检察官”，不能说“一棵检察官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
