INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在检察机关中代表国家行使检察权的官员。", "primary_collocate": null, "pronunciation": "jiǎn chá guān", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "检察官在法庭上宣读了起诉书。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位检察官已经工作了二十年。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官代表国家对犯罪行为提起公诉。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官认为证据不足，决定不起诉。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后考上了检察官。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官依法监督警察的办案过程。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访了市检察院的一位检察官。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名检察官因为办案公正受到表扬。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官向法官提交了新的证据。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的梦想是成为一名检察官。", "target_word": "检察官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "首席检察官", "label": "复合"}, {"form": "檢察官", "label": "繁体"}], "register": "书面", "sense_fingerprint": "检察机关中依法行使检察权的官员（职务身份）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检察官", "is_correct": true, "explanation": "正确：检察官负责宣读起诉书，与“在法庭上宣读了起诉书”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与法庭、起诉书无关，不会宣读起诉书。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“宣读起诉书”需要司法人员，歌手不搭配。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不会在法庭上宣读起诉书。"}], "explanations": {"检察官": "正确：检察官负责宣读起诉书，与“在法庭上宣读了起诉书”相符。", "厨师": "语义：厨师与法庭、起诉书无关，不会宣读起诉书。", "歌手": "搭配：“宣读起诉书”需要司法人员，歌手不搭配。", "医生": "语义：医生不会在法庭上宣读起诉书。"}, "sentence_index": 0, "correct_answer": "检察官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "检察官宣布了判决结果。", "explanation": "这里应该用〈法官〉。宣布判决是法官的职权，检察官负责提起公诉，不宣判。"}, {"text": "检察官在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。为被告辩护是律师的职责，检察官代表国家提起公诉。"}, {"text": "检察官为病人做了手术。", "explanation": "这里应该用〈医生〉。做手术是医生的工作，检察官不做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检察官", "is_correct": true, "explanation": "正确：记者采访的是市检察院的检察官，与句子语境相符。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员不在检察院工作，与“市检察院”的语境不符。"}, {"text": "花匠", "is_correct": false, "explanation": "搭配：“市检察院的一位”要求机关人员，花匠不搭配。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师不属于检察机关，与“市检察院”不符。"}], "explanations": {"检察官": "正确：记者采访的是市检察院的检察官，与句子语境相符。", "运动员": "语义：运动员不在检察院工作，与“市检察院”的语境不符。", "花匠": "搭配：“市检察院的一位”要求机关人员，花匠不搭配。", "理发师": "语义：理发师不属于检察机关，与“市检察院”不符。"}, "sentence_index": 6, "correct_answer": "检察官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "检察官在路口指挥交通，很忙。", "explanation": "这里应该用〈警察〉。指挥交通是警察的工作，检察官不负责交通。"}, {"text": "检察官每天在饭馆里炒菜，手艺很好。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作，检察官不做饭。"}, {"text": "检察官在舞台上唱了一首歌。", "explanation": "这里应该用〈歌手〉。在舞台上唱歌是歌手的工作，检察官不唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直想当一本检察官。", "corrected_sentence": "他一直想当一名检察官。", "error_description": "量词错误：“本”用于书籍，检察官是人，应用量词“名”，应说“一名检察官”，不能说“一本检察官”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一位很有名地检察官。", "corrected_sentence": "我认识一位很有名的检察官。", "error_description": "结构助词错误：修饰名词的“很有名”要用“的”，“地”用于修饰动词，应说“很有名的检察官”，不能说“很有名地检察官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过时", "is_correct": true, "explanation": "正确。“过时”指已经错过了合适的时机，与“正当时”相反。"}, {"text": "漆黑", "is_correct": false, "explanation": "与“正当时”没有反义关系，漆黑形容光线或颜色。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“正当时”没有反义关系，坚硬形容质地。"}, {"text": "清澈", "is_correct": false, "explanation": "与“正当时”没有反义关系，清澈形容水或空气干净透明。"}], "correct_answer": "过时", "explanations": {"过时": "正确。“过时”指已经错过了合适的时机，与“正当时”相反。", "漆黑": "与“正当时”没有反义关系，漆黑形容光线或颜色。", "坚硬": "与“正当时”没有反义关系，坚硬形容质地。", "清澈": "与“正当时”没有反义关系，清澈形容水或空气干净透明。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
