INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现在做这件事刚刚好。", "primary_collocate": null, "pronunciation": "zhèng dāng shí", "ipa": "ʈʂɤŋ˥˩ tɑŋ˥ ʂʅ˧˥", "syllable_count": 3, "sentences": [{"text": "现在去海边旅游正当时。", "target_word": "正当时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气不冷不热，爬山正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子五岁了，学钢琴正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，种花正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你刚毕业，出去看看世界正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在天还亮着，出门散步正当时。", "target_word": "正当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机降价了，这时候换新的正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "票价马上要涨了，现在订票正当时。", "target_word": "正当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想换工作，朋友说今年正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子便宜了，对想买房的人来说，现在买正当时。", "target_word": "正当时", "complexity_tier": "T3", "furigana": "fáng zi pián yi le, duì xiǎng mǎi fáng de rén lái shuō, xiàn zài mǎi zhèng dāng shí.", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "现在做某事时机正好，适合马上去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正当时", "is_correct": true, "explanation": "正确。“现在去海边旅游正当时”指现在去刚刚好，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”描述温度，与“现在做这件事刚刚好”的意思不符，句意不通。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”形容物品或风格，不能用来形容旅游这件事。"}, {"text": "凛冽", "is_correct": false, "explanation": "语义：“凛冽”形容寒风刺骨，不能用来评价旅游的时机，句意不通。"}], "explanations": {"正当时": "正确。“现在去海边旅游正当时”指现在去刚刚好，符合句意。", "寒冷": "语义：“寒冷”描述温度，与“现在做这件事刚刚好”的意思不符，句意不通。", "陈旧": "搭配：“陈旧”形容物品或风格，不能用来形容旅游这件事。", "凛冽": "语义：“凛冽”形容寒风刺骨，不能用来评价旅游的时机，句意不通。"}, "sentence_index": 0, "correct_answer": "正当时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节已经过完了，现在买年货正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，春节已过，此时买年货已错过时机，应说“已经晚了”。"}, {"text": "期末考试已经考完了，现在复习正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，考试已结束，此时复习已错过时机，应说“已经晚了”。"}, {"text": "电影已经演完了，现在去电影院正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，电影已演完，此时去电影院已错过时机，应说“已经晚了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正当时", "is_correct": true, "explanation": "正确。“换新的正当时”指现在换新的刚刚好，符合句意。"}, {"text": "衰败", "is_correct": false, "explanation": "语义：“衰败”指走向衰落，与“手机降价、现在换新”的语境矛盾。"}, {"text": "高峻", "is_correct": false, "explanation": "语域：“高峻”是书面语，形容山势高大，口语中不用于此。"}, {"text": "酷热", "is_correct": false, "explanation": "语义：“酷热”形容天气极热，与“换新的”搭配不通，句意不通。"}], "explanations": {"正当时": "正确。“换新的正当时”指现在换新的刚刚好，符合句意。", "衰败": "语义：“衰败”指走向衰落，与“手机降价、现在换新”的语境矛盾。", "高峻": "语域：“高峻”是书面语，形容山势高大，口语中不用于此。", "酷热": "语义：“酷热”形容天气极热，与“换新的”搭配不通，句意不通。"}, "sentence_index": 6, "correct_answer": "正当时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛已经结束了，现在报名正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，比赛已结束，此时报名已错过时机，应说“已经晚了”。"}, {"text": "展会已经闭幕三天了，现在参展正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，展会已闭幕，此时参展已错过时机，应说“已经晚了”。"}, {"text": "这次招聘已经截止了，现在投简历正当时。", "explanation": "这里应该用〈为时已晚〉。正当时指现在做某事刚刚好，招聘已截止，此时投简历已错过时机，应说“已经晚了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个季节去登山得正当时。", "corrected_sentence": "这个季节去登山正当时。", "error_description": "错误：“正当时”前多加了“得”。正确：“正当时”作谓语，直接跟在前面的动作后面，不加“得”，即“去登山正当时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批桃子刚熟，现在吃很正当时。", "corrected_sentence": "这批桃子刚熟，现在吃正当时。", "error_description": "错误：“正当时”前加了程度副词“很”。正确：“正当时”本身表示时机正好，不能受“很”修饰，应直接说“现在吃正当时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
