INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96396, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正处于最合适的时候。", "primary_collocate": null, "pronunciation": "zhèng dāng shí", "ipa": "ʈʂɤŋ˥˩ tɑŋ˥ ʂʅ˧˥", "syllable_count": 3, "sentences": [{"text": "九月的大闸蟹正当时。", "target_word": "正当时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "荔枝现在正当时，又甜又便宜。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "樱花开得满树都是，正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年二十五岁，人生正当时，别怕累。", "target_word": "正当时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手现在红得很，正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的西瓜正当时，冰一冰最好吃。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菊花在十月开得最好，现在正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天的橘子正当时，每个都很甜。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的事业正当时，谁也拦不住。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的柿子挂满了树，正当时。", "target_word": "正当时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "事物或人正处在最好、最盛的阶段，如当季的水果或事业的巅峰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正当时", "is_correct": true, "explanation": "正确。“九月的大闸蟹正当时”指大闸蟹正处在最好的季节，符合句意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：大闸蟹是应季的新鲜食材，“陈旧”与之矛盾，句意不通。"}, {"text": "凛冽", "is_correct": false, "explanation": "语义：“凛冽”形容寒风刺骨，不能用来形容大闸蟹，句意不通。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容高大的建筑或山，不能用来形容大闸蟹。"}], "explanations": {"正当时": "正确。“九月的大闸蟹正当时”指大闸蟹正处在最好的季节，符合句意。", "陈旧": "语义：大闸蟹是应季的新鲜食材，“陈旧”与之矛盾，句意不通。", "凛冽": "语义：“凛冽”形容寒风刺骨，不能用来形容大闸蟹，句意不通。", "高耸": "搭配：“高耸”形容高大的建筑或山，不能用来形容大闸蟹。"}, "sentence_index": 0, "correct_answer": "正当时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机昨天摔碎了，正当时。", "explanation": "这里应该用〈坏了〉。正当时指处在最好、最盛的阶段，手机已摔碎，不能用“正当时”，要说“坏了”。"}, {"text": "这把椅子的腿已经断了，正当时。", "explanation": "这里应该用〈坏了〉。正当时指处在最好、最盛的阶段，椅子断了腿，不能用“正当时”，要说“坏了”。"}, {"text": "这锅汤已经放坏了，正当时。", "explanation": "这里应该用〈变质〉。正当时指处在最好的阶段或时机刚好，汤已经放坏，不能用“正当时”来形容，要说汤已经变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正当时", "is_correct": true, "explanation": "正确。“现在正当时”指菊花现在正处在最好的时候，符合句意。"}, {"text": "衰败", "is_correct": false, "explanation": "语义：“衰败”指走向衰落，与“开得最好”矛盾，句意不通。"}, {"text": "高峻", "is_correct": false, "explanation": "语域：“高峻”是书面语，形容山势，口语中不用于花。"}, {"text": "寒酸", "is_correct": false, "explanation": "语义：“寒酸”形容贫穷、简陋，与“菊花开得最好”不符，句意不通。"}], "explanations": {"正当时": "正确。“现在正当时”指菊花现在正处在最好的时候，符合句意。", "衰败": "语义：“衰败”指走向衰落，与“开得最好”矛盾，句意不通。", "高峻": "语域：“高峻”是书面语，形容山势，口语中不用于花。", "寒酸": "语义：“寒酸”形容贫穷、简陋，与“菊花开得最好”不符，句意不通。"}, "sentence_index": 6, "correct_answer": "正当时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批橘子发霉了，正当时。", "explanation": "这里应该用〈腐烂〉。正当时指处在最好的阶段，橘子发霉了，不能用“正当时”来形容，要说橘子已经腐烂。"}, {"text": "菊花的花瓣都掉光了，正当时。", "explanation": "这里应该用〈凋谢〉。正当时指处在最盛的阶段，花瓣已经掉光，不能用“正当时”来形容，要说菊花已经凋谢。"}, {"text": "他的牙齿已经全掉光了，正当时。", "explanation": "这里应该用〈衰退〉。正当时指处在最好、最盛的阶段，牙齿全掉光是身体衰退的表现，不能用“正当时”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天的螃蟹膏满肉肥，得正当时。", "corrected_sentence": "秋天的螃蟹膏满肉肥，正当时。", "error_description": "错误：“正当时”前多加了“得”。正确：“正当时”作谓语，前面不加“得”，即“膏满肉肥，正当时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天的螃蟹很正当时。", "corrected_sentence": "这几天的螃蟹正当时。", "error_description": "错误：“正当时”前多加了程度副词“很”。正确：“正当时”是固定说法，直接作谓语，不与“很”连用，即“螃蟹正当时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
