INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个变多，另一个也跟着变多。", "primary_collocate": null, "pronunciation": "zhèng xiāng guān", "ipa": "ʈʂɤŋ˥˩ ɕjɑŋ˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "学习时间和成绩是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气越热，冰水卖得越多，这是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身高和体重常常是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两件事不是正相关，一个多，一个不多。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，努力和进步是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份报告显示，价格和质量有时是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图说明两个数字是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动多少和身体好坏是正相关吗？", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作时间越长，钱越多，两者是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发现看书的时间和词汇量是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一个变多，另一个也跟着变多的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正相关", "is_correct": true, "explanation": "正确：“正相关”指两个变量同向变化，此句说的正是这种关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能用来说明学习时间和成绩之间的关系。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不是学习时间与成绩之间的关系。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说的是人的身体重量，不能用来描述学习时间和成绩的关系。"}], "explanations": {"正相关": "正确：“正相关”指两个变量同向变化，此句说的正是这种关系。", "颜色": "语义：“颜色”指事物的色彩，不能用来说明学习时间和成绩之间的关系。", "工资": "语义：“工资”是劳动报酬，不是学习时间与成绩之间的关系。", "体重": "搭配：“体重”说的是人的身体重量，不能用来描述学习时间和成绩的关系。"}, "sentence_index": 0, "correct_answer": "正相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "价格越高，买的人越少，这是正相关。", "explanation": "这里应该用〈负相关〉。一个变多、另一个变少是负相关；正相关指两者同向变化。"}, {"text": "这个班的男女正相关是一比一。", "explanation": "这里应该用〈比例〉。正相关说的是两个变量同向变化的关系，不用来表示两个数量的比值。"}, {"text": "两种方案的正相关很清楚。", "explanation": "这里应该用〈对比〉。正相关指变量之间的同向变化关系，不用来比较两种方案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正相关", "is_correct": true, "explanation": "正确：“正相关”指两个数字同向变化，图示说明的正是这种关系。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”指两点之间的长度，不能用来说明两个数字之间的关系。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人或事物存在的年数，不能用来描述两个数字的关系。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与两个数字之间的关系无关。"}], "explanations": {"正相关": "正确：“正相关”指两个数字同向变化，图示说明的正是这种关系。", "距离": "语义：“距离”指两点之间的长度，不能用来说明两个数字之间的关系。", "年龄": "搭配：“年龄”指人或事物存在的年数，不能用来描述两个数字的关系。", "体温": "语义：“体温”指身体的温度，与两个数字之间的关系无关。"}, "sentence_index": 6, "correct_answer": "正相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这组数据的正相关是0.9。", "explanation": "这里应该用〈相关系数〉。正相关说的是变化方向一致，不是一个具体的数值。"}, {"text": "天气越冷，买冰淇淋的人越少，这是正相关。", "explanation": "这里应该用〈负相关〉…"}, {"text": "下雨的正相关是百分之七十。", "explanation": "这里应该用〈概率〉。正相关描述两个变量的变化关系，不表示事件发生的可能性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个变量很正相关。", "corrected_sentence": "这两个变量呈正相关。", "error_description": "错误在“很”。正相关是名词性术语，不能被“很”修饰；应用“呈”表示“呈现为”，即“这两个变量呈正相关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个变量之间有一张正相关。", "corrected_sentence": "两个变量之间有一种正相关。", "error_description": "错误在量词：正相关是抽象关系，应用量词“种”，不能用“张”（“张”用于纸张、桌子等平面物件）；应改为“一种正相关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负相关", "is_correct": true, "explanation": "反义：“负相关”指一个增大时另一个减小，与“正相关”的变化方向相反。"}, {"text": "比例", "is_correct": false, "explanation": "无反义关系：“比例”指两个数量之间的倍数关系，与正相关的变化方向无关。"}, {"text": "频率", "is_correct": false, "explanation": "无反义关系：“频率”指单位时间内重复发生的次数，不是正相关的反义词。"}, {"text": "因果", "is_correct": false, "explanation": "无反义关系：“因果”指原因与结果，与正相关的变化方向相反无关。"}], "correct_answer": "负相关", "explanations": {"负相关": "反义：“负相关”指一个增大时另一个减小，与“正相关”的变化方向相反。", "比例": "无反义关系：“比例”指两个数量之间的倍数关系，与正相关的变化方向无关。", "频率": "无反义关系：“频率”指单位时间内重复发生的次数，不是正相关的反义词。", "因果": "无反义关系：“因果”指原因与结果，与正相关的变化方向相反无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负相关", "is_correct": true, "explanation": "反义：“负相关”指一个增大时另一个减小，与“正相关”的变化方向相反。"}, {"text": "速度", "is_correct": false, "explanation": "无反义关系：“速度”指物体运动的快慢，不是正相关的反义词。"}, {"text": "温度", "is_correct": false, "explanation": "无反义关系：“温度”指冷热程度，与两个变量的变化方向无关。"}, {"text": "距离", "is_correct": false, "explanation": "无反义关系：“距离”指两地之间的长度，与正相关的变化方向无关。"}], "correct_answer": "负相关", "explanations": {"负相关": "反义：“负相关”指一个增大时另一个减小，与“正相关”的变化方向相反。", "速度": "无反义关系：“速度”指物体运动的快慢，不是正相关的反义词。", "温度": "无反义关系：“温度”指冷热程度，与两个变量的变化方向无关。", "距离": "无反义关系：“距离”指两地之间的长度，与正相关的变化方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个变量变化方向一致，一个增大时另一个也随之增大的关系。", "primary_collocate": null, "pronunciation": "zhèng xiāng guān", "ipa": "ʈʂɤŋ˥˩ ɕjɑŋ˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "数学课上，我们学了什么是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图上的线向上走，说明两个变量是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据表明收入和消费是正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究发现，两个变量呈正相关。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师画了一条表示正相关的直线。", "target_word": "正相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个数增大，另一个也增大，这是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两组数字不是正相关，没有这种关系。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中说，温度和冰淇淋销量是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用图来看这两个量是不是正相关。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者算出，身高和体重的正相关很强。", "target_word": "正相关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "两个变量同向变化、一个增大另一个也增大的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正相关", "is_correct": true, "explanation": "正确：“正相关”是数学课上要学的概念，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是数学课要学的内容，与“数学课上”的语境冲突。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是人与人之间的情感，不是数学课讲的知识。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭”是吃的东西，不能作为数学课上学习的内容。"}], "explanations": {"正相关": "正确：“正相关”是数学课上要学的概念，符合句意。", "颜色": "语义：“颜色”不是数学课要学的内容，与“数学课上”的语境冲突。", "友谊": "语义：“友谊”是人与人之间的情感，不是数学课讲的知识。", "午饭": "搭配：“午饭”是吃的东西，不能作为数学课上学习的内容。"}, "sentence_index": 0, "correct_answer": "正相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究发现，两个变量之间有一条正相关。", "explanation": "这里应该用〈种〉。〈条〉用于线、河等细长的东西，正相关是抽象关系，不能用〈条〉来计量。"}, {"text": "研究发现，两车的正相关差不多。", "explanation": "这里应该用〈速度〉。正相关说的是两个变量的变化关系，不用来比较两辆车。"}, {"text": "研究发现，气温有上升的正相关。", "explanation": "这里应该用〈趋势〉。正相关指两个变量同向变化的关系，不用来表示某个量上升的走势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正相关", "is_correct": true, "explanation": "正确：“不是正相关，没有这种关系”，这里否定的正是“正相关”这种关系。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”是用来称呼人或事物的，不能用来指两组数字之间的关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的袋子，与两组数字的关系无关。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”是能吃的东西，不能用来指数字之间的关系。"}], "explanations": {"正相关": "正确：“不是正相关，没有这种关系”，这里否定的正是“正相关”这种关系。", "名字": "搭配：“名字”是用来称呼人或事物的，不能用来指两组数字之间的关系。", "书包": "语义：“书包”是装东西的袋子，与两组数字的关系无关。", "食物": "语义：“食物”是能吃的东西，不能用来指数字之间的关系。"}, "sentence_index": 6, "correct_answer": "正相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究者算出，这次手术的正相关很高。", "explanation": "这里应该用〈成功率〉。正相关说的是两个变量之间的同向变化，不用来表示某次手术的成功率。"}, {"text": "研究者算出，身高和体重之间有一棵正相关。", "explanation": "这里应该用〈种〉。〈棵〉用于树木等植物，正相关是抽象关系，不能用〈棵〉来计量。"}, {"text": "研究者算出，这种药的正相关很强。", "explanation": "这里应该用〈药效〉。正相关描述两个变量的变化关系，不用来说明药物的效果强弱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数据显示收入和消费很正相关。", "corrected_sentence": "这个数据显示收入和消费呈正相关。", "error_description": "错误在“很”。正相关是名词，不能被“很”修饰；应用“呈”表示“呈现为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者算出，身高和体重之间有一张正相关。", "corrected_sentence": "研究者算出，身高和体重之间有一种正相关。", "error_description": "错误在量词：正相关是抽象关系，应用量词“种”，不能用“张”（“张”用于纸张、桌子等平面物件）；应改为“一种正相关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
