INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96401, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "法律上规定好的。", "primary_collocate": null, "pronunciation": "fǎ dìng", "ipa": "fa˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "中国的法定结婚年龄，男的是二十二岁。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节是中国的法定假日。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法定假日加班，公司必须支付加班工资。", "target_word": "法定", "complexity_tier": "T3", "furigana": "fǎ dìng jià rì jiā bān gōng sī bì xū zhī fù jiā bān gōng zī", "sentence_source": "generated"}, {"text": "他还没到法定年龄，不能开车。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法定代表人要在合同上签字。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的法定监护人是父母。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁是中国人的法定成年年龄。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法定工作时间为每周四十小时。", "target_word": "法定", "complexity_tier": "T3", "furigana": "fǎ dìng gōng zuò shí jiān wéi měi zhōu sì shí xiǎo shí", "sentence_source": "generated"}, {"text": "法定退休年龄快到了，他很高兴。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不能不给法定假期。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法定年龄", "label": "复合词"}, {"form": "法定假日", "label": "复合词"}, {"form": "法定代表人", "label": "复合词"}], "register": "书面", "sense_fingerprint": "法律上明确规定好的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确答案。法定（fǎ dìng）指法律上规定好的。"}, {"text": "法庭", "is_correct": false, "explanation": "fǎ tíng：声母 d 与 t 不同（dìng 与 tíng），声调也不同，意思是法庭。"}, {"text": "法令", "is_correct": false, "explanation": "fǎ lìng：声母 d 与 l 不同，声调相同，意思是法令。"}, {"text": "法典", "is_correct": false, "explanation": "fǎ diǎn：韵母 ìng 与 iǎn 不同，声调也不同，意思是法典。"}], "explanations": {"法定": "正确答案。法定（fǎ dìng）指法律上规定好的。", "法庭": "fǎ tíng：声母 d 与 t 不同（dìng 与 tíng），声调也不同，意思是法庭。", "法令": "fǎ lìng：声母 d 与 l 不同，声调相同，意思是法令。", "法典": "fǎ diǎn：韵母 ìng 与 iǎn 不同，声调也不同，意思是法典。"}, "sentence_index": null, "correct_answer": "法定"}, "level_3": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确。“法定结婚年龄”指法律规定的结婚年龄。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“幸福”形容感受，不能修饰“结婚年龄”这种法律规定的数值。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能说“漂亮结婚年龄”。"}, {"text": "热烈", "is_correct": false, "explanation": "语义：“热烈”形容气氛或感情，不能用来限定年龄。"}], "explanations": {"法定": "正确。“法定结婚年龄”指法律规定的结婚年龄。", "幸福": "语义：“幸福”形容感受，不能修饰“结婚年龄”这种法律规定的数值。", "漂亮": "搭配：“漂亮”形容外貌，不能说“漂亮结婚年龄”。", "热烈": "语义：“热烈”形容气氛或感情，不能用来限定年龄。"}, "sentence_index": 0, "correct_answer": "法定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的赚钱方式是法定的，没人能说什么。", "explanation": "这里应该用〈合法〉。法定指由法律规定的，说做法符合法律要用合法，不能说赚钱方式是法定的。"}, {"text": "我们每周的聚会时间是法定的，大家都会准时来。", "explanation": "这里应该用〈固定〉。法定指由法律规定的，聚会时间是大家约定的，要用固定。"}, {"text": "这是一个法定答案，老师给了满分。", "explanation": "这里应该用〈标准〉。“标准答案”指公认的正确答案，法定不能用来修饰答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确。“法定成年年龄”指法律规定的成年年龄。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容心情，不能修饰“成年年龄”。"}, {"text": "清香", "is_correct": false, "explanation": "搭配：“清香”形容气味，不能用来限定年龄。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材外形，不能用来修饰年龄。"}], "explanations": {"法定": "正确。“法定成年年龄”指法律规定的成年年龄。", "愉快": "语义：“愉快”形容心情，不能修饰“成年年龄”。", "清香": "搭配：“清香”形容气味，不能用来限定年龄。", "高大": "体貌：“高大”形容身材外形，不能用来修饰年龄。"}, "sentence_index": 6, "correct_answer": "法定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们看了一场法定的表演，全场都在鼓掌。", "explanation": "这里应该用〈精彩〉。法定指由法律规定的，不能用来评价表演好不好看，形容表演要用精彩。"}, {"text": "他是一个法定的人，大家都喜欢他。", "explanation": "这里应该用〈善良〉。法定指由法律规定的，不能用来形容人的品性，形容人要用善良。"}, {"text": "法定的学生总是按时完成作业。", "explanation": "这里应该用〈勤奋〉。法定指由法律规定的，不能用来形容学生的学习态度，形容学生要用勤奋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国庆节是法定地假日，大家都放假。", "corrected_sentence": "国庆节是法定假日，大家都放假。", "error_description": "结构助词错误：“法定”直接修饰“假日”，应说“法定假日”；“地”是状语的标记，不能用在“法定”和“假日”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个年龄是很法定的，未成年人不能买烟。", "corrected_sentence": "这个年龄是法定的，未成年人不能买烟。", "error_description": "程度副词错误：“法定”是非等级性词语，表示由法律规定，不能被“很”修饰；应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
