INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96402, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由法律规定的。", "primary_collocate": null, "pronunciation": "fǎ dìng", "ipa": "fa˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店在法定节日也开门。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买酒要达到法定年龄。", "target_word": "法定", "complexity_tier": "T3", "furigana": "mǎi jiǔ yào dá dào fǎ dìng nián líng", "sentence_source": "generated"}, {"text": "中国的法定货币是人民币。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要按法定税率交税。", "target_word": "法定", "complexity_tier": "T3", "furigana": "gōng sī yào àn fǎ dìng shuì lǜ jiāo shuì", "sentence_source": "generated"}, {"text": "工人的法定工作时间是每天八小时。", "target_word": "法定", "complexity_tier": "T3", "furigana": "gōng rén de fǎ dìng gōng zuò shí jiān shì měi tiān bā xiǎo shí", "sentence_source": "generated"}, {"text": "法定继承人有权得到房子。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆节是法定休息日。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这家公司的法定负责人。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人享有法定的权利。", "target_word": "法定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了法定期限，你就不能交了。", "target_word": "法定", "complexity_tier": "T3", "furigana": "guò le fǎ dìng qī xiàn nǐ jiù bù néng jiāo le", "sentence_source": "generated"}], "morphological_forms": [{"form": "法定年龄", "label": "复合词"}, {"form": "法定货币", "label": "复合词"}, {"form": "法定继承人", "label": "复合词"}], "register": "书面", "sense_fingerprint": "由法律来规定的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96402, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确答案。法定（fǎ dìng）指由法律来规定的。"}, {"text": "法庭", "is_correct": false, "explanation": "fǎ tíng：声母 d 与 t 不同（dìng 与 tíng），声调也不同，意思是法庭。"}, {"text": "法令", "is_correct": false, "explanation": "fǎ lìng：声母 d 与 l 不同，声调相同，意思是法令。"}, {"text": "法典", "is_correct": false, "explanation": "fǎ diǎn：韵母 ìng 与 iǎn 不同，声调也不同，意思是法典。"}], "explanations": {"法定": "正确答案。法定（fǎ dìng）指由法律来规定的。", "法庭": "fǎ tíng：声母 d 与 t 不同（dìng 与 tíng），声调也不同，意思是法庭。", "法令": "fǎ lìng：声母 d 与 l 不同，声调相同，意思是法令。", "法典": "fǎ diǎn：韵母 ìng 与 iǎn 不同，声调也不同，意思是法典。"}, "sentence_index": null, "correct_answer": "法定"}, "level_3": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确。“法定节日”指由法律规定的节日。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容味道，不能用来修饰节日。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不能说“滚烫节日”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型，不能用来修饰节日。"}], "explanations": {"法定": "正确。“法定节日”指由法律规定的节日。", "好吃": "语义：“好吃”形容味道，不能用来修饰节日。", "滚烫": "搭配：“滚烫”形容温度，不能说“滚烫节日”。", "高大": "搭配：“高大”形容体型，不能用来修饰节日。"}, "sentence_index": 0, "correct_answer": "法定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事的理解是法定的，大家都认可。", "explanation": "这里应该用〈正确〉。法定指由法律规定的，对事情的理解只能说正确，不能说法定。"}, {"text": "她有一颗法定的心，大家都喜欢她。", "explanation": "这里应该用〈温柔〉。法定不能用来形容人的性格或内心，形容性格要用温柔。"}, {"text": "他是一个法定的战士，保护了村民。", "explanation": "这里应该用〈勇敢〉。法定不能用来形容人的品质，形容战士的品质要用勇敢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法定", "is_correct": true, "explanation": "正确。“法定休息日”指法律规定的休息日。"}, {"text": "大胆", "is_correct": false, "explanation": "语义：“大胆”形容做事的勇气，不能用来修饰休息日。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度或态度，不能说“冰冷休息日”。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，不能用来修饰休息日。"}], "explanations": {"法定": "正确。“法定休息日”指法律规定的休息日。", "大胆": "语义：“大胆”形容做事的勇气，不能用来修饰休息日。", "冰冷": "搭配：“冰冷”形容温度或态度，不能说“冰冷休息日”。", "辛辣": "语义：“辛辣”形容味道，不能用来修饰休息日。"}, "sentence_index": 6, "correct_answer": "法定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "聚会的气氛是法定的，大家都很开心。", "explanation": "这里应该用〈热烈〉。法定指由法律规定的，不能用来形容聚会的气氛，形容气氛要用热烈。"}, {"text": "教室里有一盏法定的灯，大家都在看书。", "explanation": "这里应该用〈明亮〉。法定不能用来形容光线，形容灯的亮度要用明亮。"}, {"text": "她穿了一条法定的裙子，大家都夸她。", "explanation": "这里应该用〈漂亮〉。法定不能用来形容衣服，形容裙子要用漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种货币是法定地货币，可以在全国使用。", "corrected_sentence": "这种货币是法定货币，可以在全国使用。", "error_description": "结构助词错误：“法定”直接修饰“货币”，应说“法定货币”；“地”是状语的标记，不能用在“法定”和“货币”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个期限是很法定的，过了就不能交了。", "corrected_sentence": "这个期限是法定的，过了就不能交了。", "error_description": "程度副词错误：“法定”是非等级性词语，表示由法律规定，不能被“很”修饰；应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
