INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96403, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很深很深，特别重。", "primary_collocate": null, "pronunciation": "shēn shēn", "ipa": "ʂən˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "雪地上留下了一串深深的脚印。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手上有一道深深的伤口。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的脸上有很多深深的皱纹。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行给我留下了深深的印象。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着远方，发出了一声深深的叹息。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有两道深深的车印。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的话在我心里留下了深深的伤痕。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑的时候，脸上有两个深深的酒窝。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山谷深深的，看不到底。", "target_word": "深深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对故乡有一份深深的思念。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "深深的", "label": "带“的”的定语形式"}], "register": "中性", "sense_fingerprint": "深深（形容词）：修饰名词，指痕迹、印象、感情等很深很重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深深", "is_correct": true, "explanation": "深深：形容词，修饰“脚印”，表示痕迹很深，符合语境。"}, {"text": "高高", "is_correct": false, "explanation": "语义：“高高的”描述高度，脚印是地上的凹痕，不能说高高的脚印。"}, {"text": "甜甜", "is_correct": false, "explanation": "语义：“甜甜的”描述味道，与脚印这种痕迹毫无关系。"}, {"text": "香香", "is_correct": false, "explanation": "语义：“香香的”描述气味，脚印不会有香味，与语境矛盾。"}], "explanations": {"深深": "深深：形容词，修饰“脚印”，表示痕迹很深，符合语境。", "高高": "语义：“高高的”描述高度，脚印是地上的凹痕，不能说高高的脚印。", "甜甜": "语义：“甜甜的”描述味道，与脚印这种痕迹毫无关系。", "香香": "语义：“香香的”描述气味，脚印不会有香味，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "深深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一个深深的西瓜。", "explanation": "这里应该用〈大大〉。“深深”形容痕迹、印象、感情很深很重，形容东西体积大要用“大大的”。"}, {"text": "他身上穿着深深的棉衣。", "explanation": "这里应该用〈厚厚〉。“深深”指很深很重，描述衣服的厚度要说“厚厚的”。"}, {"text": "他买了一块深深的面包。", "explanation": "这里应该用〈松软〉。“深深”形容痕迹、印象、感情很深很重，不能用来形容面包的口感；形容面包要说“松软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深深", "is_correct": true, "explanation": "深深：形容词，修饰“伤痕”，表示伤痕很深很重，符合语境。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，伤痕不会发出声音，与“留在心里的伤痕”相矛盾。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音很大，与“留在心里的伤痕”不相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外表好看的人或事物，不说“漂亮的伤痕”。"}], "explanations": {"深深": "深深：形容词，修饰“伤痕”，表示伤痕很深很重，符合语境。", "清脆": "语义：“清脆”形容声音，伤痕不会发出声音，与“留在心里的伤痕”相矛盾。", "响亮": "语义：“响亮”形容声音很大，与“留在心里的伤痕”不相符。", "漂亮": "搭配：“漂亮”多形容外表好看的人或事物，不说“漂亮的伤痕”。"}, "sentence_index": 6, "correct_answer": "深深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位深深的老师。", "explanation": "“深深”形容痕迹、印象、感情很深很重，不能用来形容人的身份。"}, {"text": "我们度过了一个深深的星期天。", "explanation": "“深深”不能修饰“星期天”这样的时间词，这里的用法不对。"}, {"text": "那只小猫有一双深深的耳朵。", "explanation": "“深深”描述凹陷、痕迹或感情的深度，耳朵没有可以“深”的凹陷，这样说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上有一道深深地裂缝。", "corrected_sentence": "墙上有一道深深的裂缝。", "error_description": "错误：“深深地”是副词，不能直接修饰名词“裂缝”；修饰名词应用“深深的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的膝盖上有一道深深伤疤。", "corrected_sentence": "他的膝盖上有一道深深的伤疤。", "error_description": "错误：重叠形容词“深深”修饰名词“伤疤”时，中间必须加“的”，漏掉“的”不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
