INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96404, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "程度很深地；十分地。", "primary_collocate": null, "pronunciation": "shēn shēn", "ipa": "ʂən˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "听了她的话，我深深地感动了。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他深深地爱着自己的家乡。", "target_word": "深深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句话深深地影响了我。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她深深地后悔自己说了那句话。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事让我深深地明白了朋友的重要性。", "target_word": "深深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他深深地爱上了这座城市。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个画面深深地印在我的脑海里。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我深深地感谢你们对我的帮助。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到妈妈的白头发，他深深地感到自责。", "target_word": "深深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事深深打动了每一个人。", "target_word": "深深", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "深深地", "label": "带“地”的状语形式"}], "register": "中性", "sense_fingerprint": "深深（副词）：修饰动词，表示程度很深，十分地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深深", "is_correct": true, "explanation": "深深：副词，修饰“感动”，表示程度很深，符合语境。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声地”说明声音很响，“感动”是内心的感受，不能说大声地感动。"}, {"text": "冷冷", "is_correct": false, "explanation": "语义：“冷冷地”表示态度冷淡，与“感动”所表达的温暖之情相矛盾。"}, {"text": "飞快", "is_correct": false, "explanation": "搭配：“飞快地”说明动作的速度，“感动”不是动作，不能说飞快地感动。"}], "explanations": {"深深": "深深：副词，修饰“感动”，表示程度很深，符合语境。", "大声": "语义：“大声地”说明声音很响，“感动”是内心的感受，不能说大声地感动。", "冷冷": "语义：“冷冷地”表示态度冷淡，与“感动”所表达的温暖之情相矛盾。", "飞快": "搭配：“飞快地”说明动作的速度，“感动”不是动作，不能说飞快地感动。"}, "sentence_index": 0, "correct_answer": "深深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要深深地研究这个问题。", "explanation": "这里应该用〈深入〉。“深入研究”指进入事物内部；“深深地”只表示感情或心理的深切程度，“深深地研究”语义不清，不自然。"}, {"text": "我深深地有三个哥哥。", "explanation": "这里应该用〈确实〉。“深深地”表示感情或心理上的深切程度，不能用来强调“有三个哥哥”这类客观事实。"}, {"text": "这张桌子深深地是木头做的。", "explanation": "这里应该用〈主要〉。“深深地”表示感情或心理上的深切程度，不能用来说明“是木头做的”这类材料构成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深深", "is_correct": true, "explanation": "深深：副词，修饰“印在”，表示印象程度很深，符合语境。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便地”表示随意、不在乎，与画面深深印在脑海里的郑重感受相矛盾。"}, {"text": "草草", "is_correct": false, "explanation": "语义：“草草地”表示马虎、匆忙，与“深深”强调的印象程度相矛盾。"}, {"text": "轻声", "is_correct": false, "explanation": "搭配：“轻声地”修饰说话或声音，画面印在脑海里不能用“轻声地”来形容。"}], "explanations": {"深深": "深深：副词，修饰“印在”，表示印象程度很深，符合语境。", "随便": "语义：“随便地”表示随意、不在乎，与画面深深印在脑海里的郑重感受相矛盾。", "草草": "语义：“草草地”表示马虎、匆忙，与“深深”强调的印象程度相矛盾。", "轻声": "搭配：“轻声地”修饰说话或声音，画面印在脑海里不能用“轻声地”来形容。"}, "sentence_index": 6, "correct_answer": "深深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我深深地吃了三十个饺子。", "explanation": "“深深地”强调感受或心理的深度，不用来说明动作的数量，这里修饰“吃”，用法不对。"}, {"text": "听到敲门声，我深深地跑去开门。", "explanation": "这里应该用〈赶紧〉。“深深地”表示感情或心理上的深切程度，不修饰“跑去”这类表示位移的动作，这里的用法不对。"}, {"text": "这个方法深深地便宜。", "explanation": "这里应该用〈非常〉。“深深地”只用于表示感情或心理的深切程度，不能修饰“便宜”这类描述价格的形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个消息，他深深的松了一口气。", "corrected_sentence": "听到这个消息，他深深地松了一口气。", "error_description": "错误：“深深的”用于修饰名词。这里“深深”修饰动词“松了一口气”，应改为“深深地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她深深得喜欢这座小城。", "corrected_sentence": "她深深地喜欢这座小城。", "error_description": "错误：“深深得”用了补语标记“得”。这里“深深”是状语，修饰动词“喜欢”，应改为“深深地”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
