INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天刚亮的时候。", "primary_collocate": null, "pronunciation": "qīng chén", "ipa": "tɕʰiŋ˥ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "清晨，天刚亮，街上很安静。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的空气特别新鲜。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天清晨六点起床跑步。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的阳光照在窗户上。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨，鸟儿在树上唱歌。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈清晨就去市场买菜了。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在清晨读书。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的公园里有很多老人。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨下了一场小雨。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车清晨五点到了北京。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "清晨：天刚亮的那一小段时间，强调刚天亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深夜", "is_correct": false, "explanation": "语义：“深夜”指夜里很晚的时候，与“天刚亮”矛盾。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”指天快黑的时候，与“天刚亮”矛盾。"}, {"text": "前夕", "is_correct": false, "explanation": "配价：“前夕”需要说明是什么的前夕，单独作时间状语不完整。"}, {"text": "清晨", "is_correct": true, "explanation": "“清晨”指天刚亮的时候，与“天刚亮”一致，描述的是这一段时间。"}], "explanations": {"深夜": "语义：“深夜”指夜里很晚的时候，与“天刚亮”矛盾。", "傍晚": "语义：“傍晚”指天快黑的时候，与“天刚亮”矛盾。", "前夕": "配价：“前夕”需要说明是什么的前夕，单独作时间状语不完整。", "清晨": "“清晨”指天刚亮的时候，与“天刚亮”一致，描述的是这一段时间。"}, "sentence_index": 0, "correct_answer": "清晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他清晨三点就起床了。", "explanation": "这里应该用〈凌晨〉。“清晨”指天刚亮的时候，三点天还没亮，不能说清晨。"}, {"text": "清晨的夕阳很美。", "explanation": "这里应该用〈黄昏〉。夕阳出现在傍晚，清晨不会有夕阳。"}, {"text": "我们在清晨的烈日下工作，很辛苦。", "explanation": "这里应该用〈正午〉。“烈日”多指中午强烈的太阳，清晨的太阳不会这么烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "配价：“太阳”作处所要说“太阳底下”，不能直接说“在太阳读书”。"}, {"text": "年代", "is_correct": false, "explanation": "语义：“年代”指一段年份，不能作读书的时间或地点。"}, {"text": "清晨", "is_correct": true, "explanation": "“清晨”指天刚亮的时候，可以作读书的时间状语。"}, {"text": "中间", "is_correct": false, "explanation": "配价：“中间”需要说明是什么的中间，单独使用不完整。"}], "explanations": {"太阳": "配价：“太阳”作处所要说“太阳底下”，不能直接说“在太阳读书”。", "年代": "语义：“年代”指一段年份，不能作读书的时间或地点。", "清晨": "“清晨”指天刚亮的时候，可以作读书的时间状语。", "中间": "配价：“中间”需要说明是什么的中间，单独使用不完整。"}, "sentence_index": 6, "correct_answer": "清晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店清晨十二点才关门。", "explanation": "这里应该用〈午夜〉。“清晨”是天刚亮的时候，不会是十二点。"}, {"text": "我每天清晨六点吃晚饭。", "explanation": "这里应该用〈傍晚〉。晚饭一般在傍晚吃，清晨不吃晚饭。"}, {"text": "我清晨在食堂吃午饭。", "explanation": "这里应该用〈中午〉。午饭一般在中午吃，“清晨”指天刚亮的时候，不能用来指吃午饭的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天清晨的都去跑步。", "corrected_sentence": "我每天清晨都去跑步。", "error_description": "“清晨”作时间状语时后面不能加“的”，否则结构不通。应改为“我每天清晨都去跑步。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我清晨了五点就到了火车站。", "corrected_sentence": "我清晨五点就到了火车站。", "error_description": "“清晨”是时间词，后面不能加“了”。应改为“我清晨五点就到了火车站。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
