INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天刚亮的时候；早晨。", "primary_collocate": null, "pronunciation": "qīng chén", "ipa": "tɕʰiŋ˥ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "今天清晨我去了海边。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的雾很大，看不清路。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个清晨，爸爸都先喝一杯茶。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从清晨一直忙到晚上。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的地铁里人不多。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们清晨就起来玩儿了。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天清晨，我在河边遇到了老同学。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的校园里，同学们在读书。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的清晨有点冷，要多穿衣服。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的湖面上飘着薄雾。", "target_word": "清晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "清晨：早晨这段时间，可指一天的早上时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去年", "is_correct": false, "explanation": "语义：“去年”与“今天”冲突，不能同时修饰同一件事的时间。"}, {"text": "前夕", "is_correct": false, "explanation": "配价：“前夕”需要说明是什么的前夕，单独作时间状语不完整。"}, {"text": "清晨", "is_correct": true, "explanation": "“清晨”指早晨这段时间，与“今天”搭配，说明是今天的早上。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”与“今天”冲突，不能同时修饰同一件事。"}], "explanations": {"去年": "语义：“去年”与“今天”冲突，不能同时修饰同一件事的时间。", "前夕": "配价：“前夕”需要说明是什么的前夕，单独作时间状语不完整。", "清晨": "“清晨”指早晨这段时间，与“今天”搭配，说明是今天的早上。", "昨天": "语义：“昨天”与“今天”冲突，不能同时修饰同一件事。"}, "sentence_index": 0, "correct_answer": "清晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天清晨十二点吃午饭。", "explanation": "这里应该用〈中午〉。“清晨”指天刚亮的时候，十二点是中午，吃午饭也在中午。"}, {"text": "他清晨三点还在工作。", "explanation": "这里应该用〈凌晨〉。“清晨”指天刚亮的时候，三点天还没亮，不能说清晨。"}, {"text": "清晨的晚霞很美。", "explanation": "这里应该用〈黄昏〉。晚霞出现在傍晚，清晨不会有晚霞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”与“昨天”冲突，而且句中是过去发生的“遇到”。"}, {"text": "今年", "is_correct": false, "explanation": "语义：“今年”与“昨天”冲突，不能同时修饰同一件事的时间。"}, {"text": "时候", "is_correct": false, "explanation": "配价：“时候”需要说明是哪段时间的时候，单独作时间词不完整。"}, {"text": "清晨", "is_correct": true, "explanation": "“清晨”指天刚亮后的一段时间，与“昨天”搭配，说明是哪天的早上。"}], "explanations": {"明天": "语义：“明天”与“昨天”冲突，而且句中是过去发生的“遇到”。", "今年": "语义：“今年”与“昨天”冲突，不能同时修饰同一件事的时间。", "时候": "配价：“时候”需要说明是哪段时间的时候，单独作时间词不完整。", "清晨": "“清晨”指天刚亮后的一段时间，与“昨天”搭配，说明是哪天的早上。"}, "sentence_index": 6, "correct_answer": "清晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议安排在清晨十二点。", "explanation": "这里应该用〈午夜〉。“清晨”是天刚亮的时候，不会是十二点。"}, {"text": "我们全家清晨八点一起吃晚饭。", "explanation": "这里应该用〈晚上〉。晚饭一般在晚上吃，“清晨”指天刚亮的时候，不能用来指吃晚饭的时间。"}, {"text": "他每天清晨十二点午睡。", "explanation": "这里应该用〈中午〉。午睡一般在中午，清晨不会是十二点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天清晨了我去看了海。", "corrected_sentence": "今天清晨我去看了海。", "error_description": "“清晨”是时间词，后面不能加“了”。应改为“今天清晨我去看了海。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天清晨的去河边散步。", "corrected_sentence": "我每天清晨去河边散步。", "error_description": "“清晨”作时间状语时后面不加“的”，应直接接动词。应改为“我每天清晨去河边散步。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
