INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西量一量，看看有多少。", "primary_collocate": null, "pronunciation": "cè", "ipa": "tsʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "医生给我测了体温。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去测一下血压吧。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子测了测桌子。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要给我们测视力。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天早上测一下体重。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想测一测房间有多大。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边测水深。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用温度计测室内的温度。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说要测一下血糖。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去操场测跑道有多长。", "target_word": "测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "测了", "label": "体标"}, {"form": "测过", "label": "体标"}, {"form": "测测", "label": "重叠"}, {"form": "测一测", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用工具量一量，看有多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96407, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "测", "is_correct": true, "explanation": "正确答案。测（cè）指用东西量一量。"}, {"text": "撤", "is_correct": false, "explanation": "chè：声母 ch 与 c 不同，声调相同，意思是撤去、撤退。"}, {"text": "车", "is_correct": false, "explanation": "chē：声母 ch 与 c 不同，声调也不同（第一声），意思是车。"}, {"text": "菜", "is_correct": false, "explanation": "cài：韵母 ai 与 e 不同，声调相同，意思是菜。"}, {"text": "色", "is_correct": false, "explanation": "sè：声母 s 与 c 不同，声调相同，意思是颜色。"}], "explanations": {"测": "正确答案。测（cè）指用东西量一量。", "撤": "chè：声母 ch 与 c 不同，声调相同，意思是撤去、撤退。", "车": "chē：声母 ch 与 c 不同，声调也不同（第一声），意思是车。", "菜": "cài：韵母 ai 与 e 不同，声调相同，意思是菜。", "色": "sè：声母 s 与 c 不同，声调相同，意思是颜色。"}, "sentence_index": null, "correct_answer": "测"}, "level_3": {"options": [{"text": "测", "is_correct": true, "explanation": "正确。“测了体温”指用仪器量出体温。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃了体温”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与量体温的动作无关。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”不能与“体温”搭配，“送了体温”不成立。"}], "explanations": {"测": "正确。“测了体温”指用仪器量出体温。", "吃": "搭配：“吃”的对象是食物，不能说“吃了体温”。", "唱": "语义：“唱”指发声歌唱，与量体温的动作无关。", "送": "搭配：“送”不能与“体温”搭配，“送了体温”不成立。"}, "sentence_index": 0, "correct_answer": "测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用相机测了这张照片，很满意。", "explanation": "这里应该用〈拍〉。测指用工具量出数量，用相机拍照要用拍，不能用测。"}, {"text": "他去商店测了这件衣服的价格。", "explanation": "这里应该用〈问〉。测只用于量取长度、重量等数量，想知道价格要用问。"}, {"text": "我在网上测资料，很快找到了答案。", "explanation": "这里应该用〈搜索〉。测不能用来指在网上查找信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96407, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "测", "is_correct": true, "explanation": "正确答案。测（cè）指用东西量一量。"}, {"text": "残", "is_correct": false, "explanation": "cán：韵母 an 与 e 不同，声调也不同，意思是残缺。"}, {"text": "层", "is_correct": false, "explanation": "céng：韵母 eng 与 e 不同，声调也不同，意思是层次。"}, {"text": "错", "is_correct": false, "explanation": "cuò：韵母 uo 与 e 不同，声调相同，意思是错误。"}], "explanations": {"测": "正确答案。测（cè）指用东西量一量。", "残": "cán：韵母 an 与 e 不同，声调也不同，意思是残缺。", "层": "céng：韵母 eng 与 e 不同，声调也不同，意思是层次。", "错": "cuò：韵母 uo 与 e 不同，声调相同，意思是错误。"}, "sentence_index": null, "correct_answer": "测"}, "level_3": {"options": [{"text": "测", "is_correct": true, "explanation": "正确。“测水深”指用工具量出水的深度。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”不能与“水深”搭配，“踩水深”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，不能说“洗水深”。"}, {"text": "绣", "is_correct": false, "explanation": "语义：“绣”指用针线做图案，与测量水深无关。"}], "explanations": {"测": "正确。“测水深”指用工具量出水的深度。", "踩": "搭配：“踩”不能与“水深”搭配，“踩水深”不成立。", "洗": "搭配：“洗”的对象是物品，不能说“洗水深”。", "绣": "语义：“绣”指用针线做图案，与测量水深无关。"}, "sentence_index": 6, "correct_answer": "测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起测了这个问题，然后做了决定。", "explanation": "这里应该用〈讨论〉。测只用于量取数量，不能用来说讨论问题。"}, {"text": "我想测一下当兵的生活。", "explanation": "这里应该用〈体验〉。测不能用于人的经历或生活感受。"}, {"text": "周末我们去电影院测了新电影。", "explanation": "这里应该用〈观看〉。测不能用来指看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士每天都给病人测了血压。", "corrected_sentence": "护士每天都给病人测血压。", "error_description": "体标错误：“每天都”表示经常性的动作，“测”后不能加“了”；应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们在桥下测了三个水深。", "corrected_sentence": "工人们在桥下测了三次水深。", "error_description": "量词错误：测水深这个动作要用“次”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
