INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "抓鱼养鱼的工作。", "primary_collocate": null, "pronunciation": "yú yè", "ipa": "y˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我家住在海边，大家都靠渔业过日子。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子的人主要靠渔业生活。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就跟着爸爸从事渔业。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔业很辛苦，渔民早上三点就要出海。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在渔业干了一辈子。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学学的是渔业，想去海边工作。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前这里的人只靠渔业，不种地。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在海边做渔业，每天养鱼、抓鱼。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做渔业的人每天抓鱼，也养鱼。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔业需要天气好，下雨时渔船不能出海。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "漁業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "渔业：人们靠抓鱼、养鱼过日子的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业指捕捞和养殖水产的工作，与“住在海边”和“靠……过日子”相合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是可以用来谋生的行业，「靠……过日子」不成立，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以用来谋生的行业，「靠……过日子」不成立，句子说不通。"}, {"text": "沙漠", "is_correct": false, "explanation": "搭配：沙漠是地貌，不是可以用来“靠”以“过日子”的行业，与“靠……过日子”不搭配。"}], "explanations": {"渔业": "正确。渔业指捕捞和养殖水产的工作，与“住在海边”和“靠……过日子”相合。", "月亮": "语义：月亮是天体，不是可以用来谋生的行业，「靠……过日子」不成立，句子说不通。", "空气": "语义：空气不是可以用来谋生的行业，「靠……过日子」不成立，句子说不通。", "沙漠": "搭配：沙漠是地貌，不是可以用来“靠”以“过日子”的行业，与“靠……过日子”不搭配。"}, "sentence_index": 0, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔业每天早上三点出海。", "explanation": "这里应该用〈渔民〉。渔民是人，会出海；渔业指行业，不能作为出海的主体。"}, {"text": "今天我抓了三条渔业。", "explanation": "这里应该用〈鱼〉。渔业是行业，不能被抓；“抓”的对象应是鱼，不能说抓渔业。"}, {"text": "我们在渔业的岸边钓鱼。", "explanation": "这里应该用〈海边〉。渔业是行业，不是地点，不能说“在渔业的岸边”；指地点要用海边、渔港。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业与“只靠……不种地”相合，指以捕鱼养鱼为生的行业。"}, {"text": "种植业", "is_correct": false, "explanation": "语义：种植业本身就是种地，与句中“不种地”直接矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是可以用来谋生的行业，与「只靠……，不种地」的语境不合，句子说不通。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：草原是地貌，不能用作生计来源，与“只靠……”的说法搭配不通。"}], "explanations": {"渔业": "正确。渔业与“只靠……不种地”相合，指以捕鱼养鱼为生的行业。", "种植业": "语义：种植业本身就是种地，与句中“不种地”直接矛盾。", "月亮": "语义：月亮是天体，不是可以用来谋生的行业，与「只靠……，不种地」的语境不合，句子说不通。", "草原": "搭配：草原是地貌，不能用作生计来源，与“只靠……”的说法搭配不通。"}, "sentence_index": 6, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的渔业很新鲜，我们买一些吧。", "explanation": "这里应该用〈海鲜〉。海鲜是可以购买、可以新鲜的食物；渔业是行业，不能说新鲜。"}, {"text": "渔业破了一个大洞，我们得修。", "explanation": "这里应该用〈渔网〉。渔网是工具，会破、会修；渔业是行业，不能破损。"}, {"text": "我们一家人都住在渔业里。", "explanation": "这里应该用〈渔村〉。渔业是行业，不是居住的地方，不能说“住在渔业里”；指地方要用渔村。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子有一座古老的渔业。", "corrected_sentence": "这个村子有一种古老的渔业。", "error_description": "错误：「一座渔业」；正确：「一种渔业」。「座」用于山、楼等大型固定物，渔业是行业，应使用「种」等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从事渔业了已经很多年了。", "corrected_sentence": "他从事渔业已经很多年了。", "error_description": "错误：「渔业了」；正确：「渔业」后面不加「了」。「了」应在动词或句末表示完成或变化，不应直接跟在宾语「渔业」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
