INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "捕捞和养殖水生动植物的产业。", "primary_collocate": null, "pronunciation": "yú yè", "ipa": "y˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的渔业发展得很快。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔业是海边城市的重要产业。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在渔业不但捕鱼，还养虾和海带。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想保护海洋，也想发展渔业。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的渔业每年卖很多海产品到国外。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风多的年份，渔业的收入会少很多。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多渔业公司在海上养鱼，也出口海产品。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染让渔业的损失越来越大。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护鱼，政府限制渔业的捕鱼量。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，海水变暖会影响全世界的渔业。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "漁業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "渔业：捕捞和养殖水生动植物的产业，常与经济、政策、海洋有关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业是捕捞和养殖水生动植物的产业，与“这个国家的……发展得很快”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不会“发展”，与“这个国家的……发展得很快”的产业语境不符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是矿物颗粒，不是可以“发展”的事物，与“这个国家的……发展得很快”的语境不符，句子说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，与“这个国家的”这一社会语境不符，句子说不通。"}], "explanations": {"渔业": "正确。渔业是捕捞和养殖水生动植物的产业，与“这个国家的……发展得很快”相合。", "天气": "语义：天气是自然现象，不会“发展”，与“这个国家的……发展得很快”的产业语境不符。", "沙子": "语义：沙子是矿物颗粒，不是可以“发展”的事物，与“这个国家的……发展得很快”的语境不符，句子说不通。", "月亮": "语义：月亮是天体，与“这个国家的”这一社会语境不符，句子说不通。"}, "sentence_index": 0, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的一座渔业很发达。", "explanation": "这里应该用〈个〉或〈种〉。「座」用于山、楼等大型固定物，渔业是行业，量词用错了。"}, {"text": "今年的渔业很多，价格却很低。", "explanation": "这里应该用〈渔获〉。渔获指捕到的鱼，渔业指行业；此处说的是捕到的鱼，不是行业。"}, {"text": "渔业破了一个大洞。", "explanation": "这里应该用〈渔网〉。渔网是工具，会破损；渔业是行业，不能破损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业作定语修饰“公司”，指从事捕鱼养鱼的企业，与“在海上养鱼”相合。"}, {"text": "林业", "is_correct": false, "explanation": "语义：林业以森林为对象，与“在海上养鱼”的经营内容不符。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子公司从事电子产品业务，与“在海上养鱼”的经营内容不符。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：石油不能用来养鱼，「石油公司在海上养鱼」与常识和搭配都不通。"}], "explanations": {"渔业": "正确。渔业作定语修饰“公司”，指从事捕鱼养鱼的企业，与“在海上养鱼”相合。", "林业": "语义：林业以森林为对象，与“在海上养鱼”的经营内容不符。", "电子": "语义：电子公司从事电子产品业务，与“在海上养鱼”的经营内容不符。", "石油": "搭配：石油不能用来养鱼，「石油公司在海上养鱼」与常识和搭配都不通。"}, "sentence_index": 6, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔业停靠在港口，装满了鱼。", "explanation": "这里应该用〈渔船〉。渔业是行业，不能停靠、装鱼；能停靠、装鱼的是渔船。"}, {"text": "我们在渔业的甲板上晒太阳。", "explanation": "这里应该用〈渔船〉。甲板属于船，渔业是行业，没有甲板，不能说“渔业的甲板”。"}, {"text": "渔业在海上撒网，很快就收工了。", "explanation": "这里应该用〈渔民〉。撒网的是人，渔业是行业，不能做动作；此句说的是渔民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去渔业买了几条新鲜的鱼。", "corrected_sentence": "我们去渔港买了几条新鲜的鱼。", "error_description": "错误：「去渔业」；正确：「去渔港」。渔业是产业，不是地点，不能“去”；买鱼的地方应说渔港或市场。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村的渔业的发展了很多年。", "corrected_sentence": "这个村的渔业发展了很多年。", "error_description": "错误：「渔业的发展了」；正确：「渔业发展了」。「渔业的发展」是名词性短语，不能直接带动态助词「了」作谓语，应去掉「的」，让「渔业」作主语、「发展」作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
