INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海水一会儿涨高，一会儿退下去。", "primary_collocate": null, "pronunciation": "cháo", "ipa": "ʈʂʰaʊ˧˥", "syllable_count": 1, "sentences": [{"text": "海边的潮退了，沙滩上有很多小螃蟹。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，潮来了，我们快回岸上去吧。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的潮很高，水都到路上了。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等潮退了，我们再去海边捡贝壳。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的潮涨得很快，船都升高了。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的潮一会儿涨，一会儿退。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上玩，没注意潮已经来了。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潮退下去以后，海边露出了一大片沙子。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民说，今天下午三点潮最高。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潮涨起来，小河里的水也变多了。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涨潮", "label": "复合"}, {"form": "退潮", "label": "复合"}, {"form": "潮水", "label": "复合"}], "register": "中性", "sense_fingerprint": "海水涨起来又退下去（眼前所见的海潮）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。潮读 cháo（第二声），指海水一会儿涨、一会儿退。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo，第一声）与潮（cháo，第二声）声调不同，意思是超过。"}, {"text": "炒", "is_correct": false, "explanation": "炒（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是用油翻炒。"}, {"text": "槽", "is_correct": false, "explanation": "槽（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，意思是水槽、马槽。"}], "explanations": {"潮": "正确。潮读 cháo（第二声），指海水一会儿涨、一会儿退。", "超": "超（chāo，第一声）与潮（cháo，第二声）声调不同，意思是超过。", "炒": "炒（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是用油翻炒。", "槽": "槽（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，意思是水槽、马槽。"}, "sentence_index": null, "correct_answer": "潮"}, "level_3": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。“潮”指海水涨落，与“退了”“沙滩”的语境相符。"}, {"text": "风", "is_correct": false, "explanation": "语义：风没有涨落退的现象，“退”只用于潮水、海水，不能说“海边的风退了”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“退”不搭配“雨”，雨停了说“停”，不说“退”。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不会涨落，也不会“退”，句中的“退”指海水退去。"}], "explanations": {"潮": "正确。“潮”指海水涨落，与“退了”“沙滩”的语境相符。", "风": "语义：风没有涨落退的现象，“退”只用于潮水、海水，不能说“海边的风退了”。", "雨": "搭配：“退”不搭配“雨”，雨停了说“停”，不说“退”。", "山": "语义：山不会涨落，也不会“退”，句中的“退”指海水退去。"}, "sentence_index": 0, "correct_answer": "潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨以后，我的被子很潮，晚上没法睡。", "explanation": "这里的“潮”是“潮湿”的意思，指东西含水分多，与海水定时涨落的“潮”不是一个意思。"}, {"text": "他的穿衣风格很潮，总是走在流行前面。", "explanation": "这里的“潮”是口语里“时髦、流行”的意思，指人或东西跟得上潮流，与海水涨落无关。"}, {"text": "听到这个消息，他心里一阵潮涌上来，半天说不出话。", "explanation": "这里的“潮”指心里一阵阵涌动的感情，与海水定时涨落的现象无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。潮读 cháo（第二声），指海水一会儿涨、一会儿退。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo，第一声）与潮（cháo，第二声）声调不同，意思是抄写。"}, {"text": "吵", "is_correct": false, "explanation": "吵（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是吵闹。"}, {"text": "钞", "is_correct": false, "explanation": "钞（chāo，第一声）与潮（cháo，第二声）声调不同，意思是钱币。"}, {"text": "曹", "is_correct": false, "explanation": "曹（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，是常见的姓氏。"}], "explanations": {"潮": "正确。潮读 cháo（第二声），指海水一会儿涨、一会儿退。", "抄": "抄（chāo，第一声）与潮（cháo，第二声）声调不同，意思是抄写。", "吵": "吵（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是吵闹。", "钞": "钞（chāo，第一声）与潮（cháo，第二声）声调不同，意思是钱币。", "曹": "曹（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，是常见的姓氏。"}, "sentence_index": null, "correct_answer": "潮"}, "level_3": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。“潮”指海水涨上来，与“没注意……已经来了”的语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能说“来了”，句中指涨上来的海水。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印不会“来”，句中指海水涨上来。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“来”，句中指涨上来的海水。"}], "explanations": {"潮": "正确。“潮”指海水涨上来，与“没注意……已经来了”的语境相符。", "作业": "搭配：“作业”不能说“来了”，句中指涨上来的海水。", "脚印": "语义：脚印不会“来”，句中指海水涨上来。", "石头": "语义：石头不会“来”，句中指涨上来的海水。"}, "sentence_index": 6, "correct_answer": "潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山里雨多，屋子里的墙都很潮。", "explanation": "这里的“潮”是“潮湿”的意思，指墙面含水多，与海水定时涨落的“潮”不是一个意思。"}, {"text": "游泳池的潮降了两厘米，工人正在加水。", "explanation": "这里应该用〈水位〉。游泳池里水面的高低说水位，潮只指海水定时涨落。"}, {"text": "现在网上刮起一股潮，大家都在玩这个游戏。", "explanation": "这里的“潮”是“一时的风气、流行”的意思，指社会上的流行趋势，与海水涨落无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在海边看到一只很大的潮。", "corrected_sentence": "我昨天在海边看到了很大的潮。", "error_description": "错误形式：“一只很大的潮”；正确形式：“很大的潮”。“只”用来数动物等，不能用来数潮；这里直接说“很大的潮”就可以。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "午后的潮涨下来了，很快就淹没了礁石。", "corrected_sentence": "午后的潮涨起来了，很快就淹没了礁石。", "error_description": "错误形式：“涨下来”；正确形式：“涨起来”。“涨”表示水位向上升，应该用趋向补语“起来”，不能用“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
