INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "海水定时涨落的现象。", "primary_collocate": null, "pronunciation": "cháo", "ipa": "ʈʂʰaʊ˧˥", "syllable_count": 1, "sentences": [{"text": "潮每天涨落两次，渔民都知道。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮和地球的关系会影响潮。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书详细讲了潮的形成过程。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月农历十五，海边的潮特别大。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着潮一次次涨起来，他想了很多。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，潮的变化有一定的时间。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看潮的高低，就知道什么时候出海。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口的潮和别的地方不一样。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看到潮，觉得大海真神奇。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的科学课上，老师给我们讲了潮。", "target_word": "潮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涨潮", "label": "复合"}, {"form": "退潮", "label": "复合"}, {"form": "潮汐", "label": "复合"}], "register": "中性", "sense_fingerprint": "海水定时涨落这一自然现象（可作知识、规律来谈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96412, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。潮读 cháo（第二声），指海水定时涨落的现象。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo，第一声）与潮（cháo，第二声）声调不同，意思是超过。"}, {"text": "炒", "is_correct": false, "explanation": "炒（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是用油翻炒。"}, {"text": "槽", "is_correct": false, "explanation": "槽（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，意思是水槽、马槽。"}], "explanations": {"潮": "正确。潮读 cháo（第二声），指海水定时涨落的现象。", "超": "超（chāo，第一声）与潮（cháo，第二声）声调不同，意思是超过。", "炒": "炒（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是用油翻炒。", "槽": "槽（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，意思是水槽、马槽。"}, "sentence_index": null, "correct_answer": "潮"}, "level_3": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。“潮”指海水定时涨落，与“每天涨落两次”相符。"}, {"text": "风", "is_correct": false, "explanation": "语义：风没有定时涨落的现象，“涨落”只用于水位、潮水等。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“涨落”不搭配“雨”，雨只说下、停，不说涨落。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不存在涨落现象，句中指海水定时起伏。"}], "explanations": {"潮": "正确。“潮”指海水定时涨落，与“每天涨落两次”相符。", "风": "语义：风没有定时涨落的现象，“涨落”只用于水位、潮水等。", "雨": "搭配：“涨落”不搭配“雨”，雨只说下、停，不说涨落。", "树": "语义：树不存在涨落现象，句中指海水定时起伏。"}, "sentence_index": 0, "correct_answer": "潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的墙很潮，都长霉了。", "explanation": "这里的“潮”是“潮湿”的意思，指墙或空气含水多，与海水定时涨落的现象不是一个意思。"}, {"text": "这个发型很潮，大家都说好看。", "explanation": "这里的“潮”是口语里“时髦、流行”的意思，指款式跟得上流行，与海水涨落无关。"}, {"text": "他看着朋友远去，心里一阵潮涌上来，说不出话。", "explanation": "这里的“潮”指心里一阵阵涌动的感情，与海水定时涨落的现象无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96412, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。潮读 cháo（第二声），指海水定时涨落的现象。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo，第一声）与潮（cháo，第二声）声调不同，意思是抄写。"}, {"text": "吵", "is_correct": false, "explanation": "吵（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是吵闹。"}, {"text": "钞", "is_correct": false, "explanation": "钞（chāo，第一声）与潮（cháo，第二声）声调不同，意思是钱币。"}, {"text": "曹", "is_correct": false, "explanation": "曹（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，是常见的姓氏。"}], "explanations": {"潮": "正确。潮读 cháo（第二声），指海水定时涨落的现象。", "抄": "抄（chāo，第一声）与潮（cháo，第二声）声调不同，意思是抄写。", "吵": "吵（chǎo，第三声）与潮（cháo，第二声）声调不同，意思是吵闹。", "钞": "钞（chāo，第一声）与潮（cháo，第二声）声调不同，意思是钱币。", "曹": "曹（cáo，第二声）与潮（cháo）声母不同：c 与 ch 不同，是常见的姓氏。"}, "sentence_index": null, "correct_answer": "潮"}, "level_3": {"options": [{"text": "潮", "is_correct": true, "explanation": "正确。“看潮的高低”指观察海水涨落的幅度，句意成立。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“高低”不用于“作业”，句中指海水涨落的幅度。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影没有高低的说法，不能借以判断出海的时间。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子的高低指鞋跟，不能用来判断什么时候出海。"}], "explanations": {"潮": "正确。“看潮的高低”指观察海水涨落的幅度，句意成立。", "作业": "搭配：“高低”不用于“作业”，句中指海水涨落的幅度。", "电影": "语义：电影没有高低的说法，不能借以判断出海的时间。", "鞋子": "语义：鞋子的高低指鞋跟，不能用来判断什么时候出海。"}, "sentence_index": 6, "correct_answer": "潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把伞收了一夜，伞面还是很潮。", "explanation": "这里的“潮”是“潮湿”的意思，指伞面含水多，与海水定时涨落的现象不是一个意思。"}, {"text": "工人每天记录池子的潮，防止溢出。", "explanation": "这里应该用〈水位〉。池子里水面的高低说水位，潮只指海水定时涨落。"}, {"text": "会场里传来一阵潮，大家都停下了说话。", "explanation": "这里应该用〈声浪〉。形容一阵阵的声音用声浪；潮指海水定时涨落或像潮水一样的社会趋势，不用来说声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书上详细说明了一只潮的形成原因。", "corrected_sentence": "书上详细说明了潮的形成原因。", "error_description": "错误形式：“一只潮的形成原因”；正确形式：“潮的形成原因”。这里“潮”是抽象的涨落现象，不能用量词“只”来数，应直接说“潮的形成原因”，或用“次”来数具体的一次涨落。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农历十五那天，潮涨下来得特别高。", "corrected_sentence": "农历十五那天，潮涨得特别高。", "error_description": "错误形式：“潮涨下来”；正确形式：“潮涨”。潮涨是水位向上升，不能用表示向下的“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都喜欢、都在做的新样子。", "primary_collocate": null, "pronunciation": "cháo liú", "ipa": "tʂʰɑʊ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "年轻人都喜欢追潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿得很有个性，总是走在潮流的前面。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鞋子现在是最新的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太懂潮流，只喜欢舒服的衣服。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说今年的潮流是白色的运动鞋。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每个月都买新衣服，想跟上潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人跟着网上的潮流剪头发。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个潮流来得快，去得也快。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明星戴过的帽子，很快就成了潮流。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他的衣服不是潮流，但是很好穿。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股潮流", "label": "量词"}], "register": "中性", "sense_fingerprint": "潮流：衣服、发型等方面大家都喜欢的新样子，即时尚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是可以追赶的对象。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指大家都喜欢、都在做的新样子，“追潮流”是常见搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能用来追赶。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“追”接的是人、趋势等，不说“追早饭”。"}], "explanations": {"电话": "语义：电话是通讯工具，不是可以追赶的对象。", "潮流": "潮流指大家都喜欢、都在做的新样子，“追潮流”是常见搭配。", "冰箱": "语义：冰箱是家用电器，不能用来追赶。", "早饭": "搭配：“追”接的是人、趋势等，不说“追早饭”。"}, "sentence_index": 0, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的潮流是打篮球，每个周末都去球场。", "explanation": "这里应该用〈爱好〉。潮流指社会上大家都在追随的新样子，个人喜欢做的事要说爱好，不说潮流。"}, {"text": "比赛进入了最后的潮流，观众大声欢呼。", "explanation": "这里应该用〈高潮〉。高潮指比赛、演出发展到最激烈、最精彩的阶段，潮流指大家追随的新样子，不指比赛的阶段。"}, {"text": "他的潮流很暴躁，动不动就发火。", "explanation": "这里应该用〈脾气〉。脾气指一个人的性情和发作时的样子，潮流指大家追随的新样子，不用来形容人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说人的高矮，不能作为跟着剪发的依据。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指大家都在做的新样子，“跟着……的潮流”是常见说法，修饰“剪头发”的样式。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不指式样，不能跟着它剪头发。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“故事”不是可以照着剪的样子，不能说“跟着网上的故事剪头发”。"}], "explanations": {"身高": "体貌：“身高”说人的高矮，不能作为跟着剪发的依据。", "潮流": "潮流指大家都在做的新样子，“跟着……的潮流”是常见说法，修饰“剪头发”的样式。", "时间": "语义：时间不指式样，不能跟着它剪头发。", "故事": "搭配：“故事”不是可以照着剪的样子，不能说“跟着网上的故事剪头发”。"}, "sentence_index": 6, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的潮流是教小学生画画，每天都很忙。", "explanation": "这里应该用〈工作〉。潮流指社会上大家都在追随的新样子，个人的职业要说工作，不说潮流。"}, {"text": "他的潮流很踏实，做事认真负责。", "explanation": "这里应该用〈作风〉。作风指一个人做事的态度和风格，潮流指大家追随的新样子，不用来形容人的做事态度。"}, {"text": "这所学校的潮流很贵，很多家庭负担不起。", "explanation": "这里应该用〈学费〉。学费指上学要交的钱，潮流指大家追随的新样子，不指学校收取的费用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种发型曾经是潮流过，现在已经过时了。", "corrected_sentence": "这种发型曾经是潮流，现在已经过时了。", "error_description": "错误在时态助词“过”。“潮流”是名词，后面不能直接加“过”，“曾经”已经表示过去，应说“曾经是潮流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件潮流很快就传遍了整个学校。", "corrected_sentence": "这股潮流很快就传遍了整个学校。", "error_description": "量词错误。“潮流”是抽象的趋势，应搭配量词“股”，说“这股潮流”；“件”用于衣服等具体物品，不能用来数“潮流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆流", "is_correct": true, "explanation": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "与“潮流”无反义关系，桌子是具体的家具，不表示社会趋势。"}, {"text": "石头", "is_correct": false, "explanation": "与“潮流”无反义关系，石头是具体的物体，不表示社会趋势。"}, {"text": "窗户", "is_correct": false, "explanation": "与“潮流”无反义关系，窗户是房屋的构件，不表示社会趋势。"}], "correct_answer": "逆流", "explanations": {"逆流": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。", "桌子": "与“潮流”无反义关系，桌子是具体的家具，不表示社会趋势。", "石头": "与“潮流”无反义关系，石头是具体的物体，不表示社会趋势。", "窗户": "与“潮流”无反义关系，窗户是房屋的构件，不表示社会趋势。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆流", "is_correct": true, "explanation": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。"}, {"text": "钥匙", "is_correct": false, "explanation": "与“潮流”无反义关系，钥匙是开锁的工具，不表示社会趋势。"}, {"text": "书包", "is_correct": false, "explanation": "与“潮流”无反义关系，书包是装东西的用具，不表示社会趋势。"}, {"text": "花瓶", "is_correct": false, "explanation": "与“潮流”无反义关系，花瓶是盛花的器物，不表示社会趋势。"}], "correct_answer": "逆流", "explanations": {"逆流": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。", "钥匙": "与“潮流”无反义关系，钥匙是开锁的工具，不表示社会趋势。", "书包": "与“潮流”无反义关系，书包是装东西的用具，不表示社会趋势。", "花瓶": "与“潮流”无反义关系，花瓶是盛花的器物，不表示社会趋势。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻社会变动或发展的趋势；也指风行一时的事物。", "primary_collocate": null, "pronunciation": "cháo liú", "ipa": "tʂʰɑʊ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要跟上时代的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界经济的潮流是越来越开放。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人想改变社会，也想走在时代潮流的前面。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司看清了市场的潮流，所以赚了很多钱。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保已经成了世界的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也挡不住时代的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读书的人越来越多，这是社会发展的潮流。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很早就看到了互联网的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史的潮流向前走，没有人能停下来。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学生要顺着时代的潮流，不断学习。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股潮流", "label": "量词"}], "register": "中性", "sense_fingerprint": "潮流：社会、时代、经济等发展变化的大趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65cfc7aa-6cf5-4d83-a040-057d0d97b079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高峰", "is_correct": false, "explanation": "搭配：“跟上”接的是步伐、潮流，攀上的才是高峰，不说“跟上时代的高峰”。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指社会、时代发展的大趋势，与“跟上”搭配，表示要紧跟时代的变化。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以跟上的发展方向。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是具体的机器，不是可以跟随的社会趋势。"}], "explanations": {"高峰": "搭配：“跟上”接的是步伐、潮流，攀上的才是高峰，不说“跟上时代的高峰”。", "潮流": "潮流指社会、时代发展的大趋势，与“跟上”搭配，表示要紧跟时代的变化。", "天气": "语义：天气是自然现象，不是可以跟上的发展方向。", "电脑": "语义：电脑是具体的机器，不是可以跟随的社会趋势。"}, "sentence_index": 0, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年夏天气温一直在上升，形成了明显的潮流。", "explanation": "这里应该用〈趋势〉。潮流指社会、时代或流行中的大方向，不用来说气温等自然数据的变化。"}, {"text": "涨潮的时候，潮流很快就淹没了礁石。", "explanation": "这里应该用〈潮水〉。淹没礁石的是潮水；潮流只指海水流动的方向和速度，不会淹没东西。"}, {"text": "演唱会进入了最精彩的潮流，观众全部站了起来。", "explanation": "这里应该用〈高潮〉。高潮指演出、比赛发展到最激烈、最精彩的阶段；潮流指社会上的大趋势，不指演出的某个阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说人或物的体形，不用来形容社会的发展。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指社会发展的大趋势，“社会发展的潮流”是常见说法，正好说明读书的人越来越多这一趋势。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指给商品套上的外壳，与社会发展的趋势无关。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”只说食物或人的喜好，不能说“社会发展的口味”。"}], "explanations": {"身材": "体貌：“身材”说人或物的体形，不用来形容社会的发展。", "潮流": "潮流指社会发展的大趋势，“社会发展的潮流”是常见说法，正好说明读书的人越来越多这一趋势。", "包装": "语义：“包装”指给商品套上的外壳，与社会发展的趋势无关。", "口味": "搭配：“口味”只说食物或人的喜好，不能说“社会发展的口味”。"}, "sentence_index": 6, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警方已经掌握了嫌疑人的潮流，随时可以行动。", "explanation": "这里应该用〈动向〉。潮流指时代或社会的大趋势，不指某个人的行踪或举动。"}, {"text": "他每天早上都有跑步的潮流。", "explanation": "这里应该用〈习惯〉。潮流指社会上大家都在追随的趋势，个人的日常习惯要说习惯，不说潮流。"}, {"text": "他对数学的潮流很浓，常常自己做题。", "explanation": "这里应该用〈兴趣〉。兴趣指个人对某件事的喜爱，潮流指社会上的大趋势，不用来说个人的喜好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就跟上着潮流。", "corrected_sentence": "他很快就跟上了潮流。", "error_description": "错误：「跟上着」；正确：「跟上了」。「跟上」表示已经完成的动作，应用完成态助词「了」，不能用表示持续的「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只潮流很快就传到了我们学校。", "corrected_sentence": "这股潮流很快就传到了我们学校。", "error_description": "量词错误。“潮流”应用量词“股”，不能用“只”，“只”用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "博学", "is_correct": true, "explanation": "博学：学识广博，与“无知”构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "与“无知”无反义关系，干净形容卫生状况，与知识无关。"}, {"text": "高兴", "is_correct": false, "explanation": "与“无知”无反义关系，高兴形容心情，与知识无关。"}, {"text": "沉重", "is_correct": false, "explanation": "与“无知”无反义关系，沉重形容重量或心情，与知识无关。"}], "correct_answer": "博学", "explanations": {"博学": "博学：学识广博，与“无知”构成反义。", "干净": "与“无知”无反义关系，干净形容卫生状况，与知识无关。", "高兴": "与“无知”无反义关系，高兴形容心情，与知识无关。", "沉重": "与“无知”无反义关系，沉重形容重量或心情，与知识无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857d4bb9-7be3-4c45-98f8-b09ecebd0747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
