INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买东西时要付的钱是多少。", "primary_collocate": null, "pronunciation": "wù jià", "ipa": "u˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的物价很高。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近物价一直在涨，大家都觉得生活不容易。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们那儿的物价比北京低很多。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的物价太高了，我不想买东西。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去国外旅行以前，我先了解了那里的物价。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价上涨以后，妈妈买菜都要想一想。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想办法让超市里的物价保持稳定。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个国家的物价很便宜，所以很多人去旅游。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资没有变，可是物价每年都在涨。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市生活，物价是要考虑的问题。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物价指数", "label": "复合词"}, {"form": "物价水平", "label": "复合词"}], "register": "中性", "sense_fingerprint": "日常生活中买东西要花多少钱，物价高、物价低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：wù jià，指买东西时要付的钱的水平。"}, {"text": "无价", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）只差声调，“无价”意思是没有价格、极其珍贵。"}, {"text": "午假", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）只差声调，“午假”指中午的休息时间。"}, {"text": "物件", "is_correct": false, "explanation": "jiàn 与 jià 声调相同，只差韵尾（n），“物件”意思是东西、物品。"}, {"text": "度假", "is_correct": false, "explanation": "dù 与 wù 只差声母：dù 有声母 d，wù 没有声母，“度假”意思是休假、外出休息。"}], "explanations": {"物价": "正确答案：wù jià，指买东西时要付的钱的水平。", "无价": "wú（第二声）与 wù（第四声）只差声调，“无价”意思是没有价格、极其珍贵。", "午假": "wǔ（第三声）与 wù（第四声）只差声调，“午假”指中午的休息时间。", "物件": "jiàn 与 jià 声调相同，只差韵尾（n），“物件”意思是东西、物品。", "度假": "dù 与 wù 只差声母：dù 有声母 d，wù 没有声母，“度假”意思是休假、外出休息。"}, "sentence_index": null, "correct_answer": "物价"}, "level_3": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：“物价”指买东西要付的钱的水平，可以说“很高”，符合“这个城市的物价很高”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能用“很高”来形容城市的收费水平，句子的意思不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”的数量一般说“多”或“少”，不说“很高”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不能用“很高”来形容，这个句子说的是城市的价格水平。"}], "explanations": {"物价": "正确答案：“物价”指买东西要付的钱的水平，可以说“很高”，符合“这个城市的物价很高”的语境。", "天气": "语义：“天气”不能用“很高”来形容城市的收费水平，句子的意思不通。", "人口": "搭配：“人口”的数量一般说“多”或“少”，不说“很高”。", "语言": "语义：“语言”不能用“很高”来形容，这个句子说的是城市的价格水平。"}, "sentence_index": 0, "correct_answer": "物价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救灾时，政府运来了很多物价。", "explanation": "这里应该用〈物资〉。物价指买东西要付的钱的水平，不指可以运送的实物，运送的是物资。"}, {"text": "这种物价对人体有害。", "explanation": "这里应该用〈物质〉。物价是价钱，不是化学物质，不能说它对人体有害。"}, {"text": "这片森林里保护着许多珍稀物价。", "explanation": "这里应该用〈物种〉。物价是价钱，珍稀的是动植物的种类，要用物种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：“物价”指买东西要付的钱的水平，超市里的物价可以“保持稳定”，符合语境。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是身体的生理活动，政府无法让它保持稳定，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是人的身体特征，不能说政府想办法让它“保持稳定”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体指标，不能说超市里的体重保持稳定。"}], "explanations": {"物价": "正确答案：“物价”指买东西要付的钱的水平，超市里的物价可以“保持稳定”，符合语境。", "心跳": "语义：“心跳”是身体的生理活动，政府无法让它保持稳定，句子不通。", "身高": "语义：“身高”是人的身体特征，不能说政府想办法让它“保持稳定”。", "体重": "语义：体重是人的身体指标，不能说超市里的体重保持稳定。"}, "sentence_index": 6, "correct_answer": "物价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱子里装满了各种物价。", "explanation": "这里应该用〈物品〉。物价是价钱，箱子里装的是东西，不是价钱。"}, {"text": "桌上放着一个陌生的物价。", "explanation": "这里应该用〈物体〉。物价不指具体的东西，桌上放的是一个物体。"}, {"text": "这间屋子里堆着很多旧物价。", "explanation": "这里应该用〈物件〉。物价不能用来指旧的东西，堆着的是物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇的物价很多。", "corrected_sentence": "这个小镇的物价很低。", "error_description": "错误：“物价”说的是价格水平，形容高低要用“高”或“低”，不能用“多”。应改为：这个小镇的物价很低。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近物价很快。", "corrected_sentence": "最近物价涨得很快。", "error_description": "错误：“很快”修饰的是动作的速度，不能直接修饰“物价”，句中缺少动词。应改为：最近物价涨得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
