INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品和服务的价格水平。", "primary_collocate": null, "pronunciation": "wù jià", "ipa": "u˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "今年的物价比去年高了一点儿。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在努力控制物价。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价稳定，人们的生活才能安心。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说下个月物价会下降。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价上涨会影响每个家庭。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的物价整体上比去年低了一些。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展得快，物价也会变化。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，物价和工资有很大关系。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年物价涨得很快。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价太高的时候，人们都少花钱。", "target_word": "物价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物价指数", "label": "复合词"}, {"form": "物价水平", "label": "复合词"}], "register": "中性", "sense_fingerprint": "经济上商品和服务整体的价格水平，物价上涨、控制物价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：wù jià，指商品和服务的整体价格水平。"}, {"text": "无价", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）只差声调，“无价”意思是没有价格、极其珍贵。"}, {"text": "午假", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）只差声调，“午假”指中午的休息时间。"}, {"text": "物件", "is_correct": false, "explanation": "jiàn 与 jià 声调相同，只差韵尾（n），“物件”意思是东西、物品。"}, {"text": "度假", "is_correct": false, "explanation": "dù 与 wù 只差声母：dù 有声母 d，wù 没有声母，“度假”意思是休假、外出休息。"}], "explanations": {"物价": "正确答案：wù jià，指商品和服务的整体价格水平。", "无价": "wú（第二声）与 wù（第四声）只差声调，“无价”意思是没有价格、极其珍贵。", "午假": "wǔ（第三声）与 wù（第四声）只差声调，“午假”指中午的休息时间。", "物件": "jiàn 与 jià 声调相同，只差韵尾（n），“物件”意思是东西、物品。", "度假": "dù 与 wù 只差声母：dù 有声母 d，wù 没有声母，“度假”意思是休假、外出休息。"}, "sentence_index": null, "correct_answer": "物价"}, "level_3": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：“物价”指整体价格水平，可以和“比去年高了一点儿”搭配，符合句子的语境。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”的增长说“大”，不说“比去年高了一点儿”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不会随时间用“高”来比较，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不能用“比去年高了一点儿”来描述，这个说法不成立。"}], "explanations": {"物价": "正确答案：“物价”指整体价格水平，可以和“比去年高了一点儿”搭配，符合句子的语境。", "年龄": "搭配：“年龄”的增长说“大”，不说“比去年高了一点儿”。", "名字": "语义：“名字”不会随时间用“高”来比较，句子说不通。", "脾气": "语义：“脾气”不能用“比去年高了一点儿”来描述，这个说法不成立。"}, "sentence_index": 0, "correct_answer": "物价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣的物价很便宜。", "explanation": "这里应该用〈价格〉。物价指整体的价格水平，说一件毛衣的价钱要用价格。"}, {"text": "这本书很有物价。", "explanation": "这里应该用〈价值〉。物价是价格水平，不能用来说东西有没有用、值不值得。"}, {"text": "仓库里存放着大量物价。", "explanation": "这里应该用〈物资〉。物价不是实物，仓库里存放的是物资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物价", "is_correct": true, "explanation": "正确答案：“物价”会随经济发展而变化，符合“经济发展得快，物价也会变化”的语境。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是固定的日期，不会因为经济发展而变化，句子不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”不随经济发展变化，说“性别也会变化”没有道理。"}, {"text": "出生地", "is_correct": false, "explanation": "语义：“出生地”是固定的事实，不随经济发展而变化，句子说不通。"}], "explanations": {"物价": "正确答案：“物价”会随经济发展而变化，符合“经济发展得快，物价也会变化”的语境。", "生日": "语义：“生日”是固定的日期，不会因为经济发展而变化，句子不通。", "性别": "语义：“性别”不随经济发展变化，说“性别也会变化”没有道理。", "出生地": "语义：“出生地”是固定的事实，不随经济发展而变化，句子说不通。"}, "sentence_index": 6, "correct_answer": "物价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "超市的货架上摆满了物价。", "explanation": "这里应该用〈物品〉。物价是价格水平，货架上摆的是物品，不是价格。"}, {"text": "动物园里饲养着很多珍稀物价。", "explanation": "这里应该用〈物种〉。物价不指动物的种类，饲养的是珍稀的物种。"}, {"text": "博物馆里陈列着很多古老的物价。", "explanation": "这里应该用〈物件〉。物价不能指古老的东西，陈列的是物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近物价有点儿大。", "corrected_sentence": "最近物价有点儿高。", "error_description": "错误：形容物价的高低要用“高”，不能用“大”。应改为：最近物价有点儿高。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近两年物价很重。", "corrected_sentence": "最近两年物价很高。", "error_description": "错误：形容物价的高低要用“高”，不能用“重”。应改为：最近两年物价很高。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
