INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不知道正确的答案，自己想一想说出来。", "primary_collocate": null, "pronunciation": "cāi cè", "ipa": "tsʰai˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "关于盒子里装的是什么，大家只能猜测。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "老师让我们猜测这个谜语的答案。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能根据我的样子猜测我的年龄吗？", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "没有人告诉我，我只好自己猜测。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我手里有几颗糖？请大胆猜测。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "他闭着眼睛，凭感觉猜测桌上的东西。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "游戏里，玩家要根据提示猜测卡片上的词。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "这道题我不会，只好根据常识猜测答案。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "孩子们争着猜测礼物里是什么玩具。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}, {"text": "请先大胆猜测，再看后面的答案。", "target_word": "猜测", "complexity_tier": "T3", "furigana": "cāi cè", "sentence_source": "generated"}], "morphological_forms": [{"form": "猜测了", "label": "完成体"}, {"form": "猜测过", "label": "经历体"}, {"form": "猜测着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "面对问题或谜题，不知答案而自己想一个说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "承认", "is_correct": false, "explanation": "配价：“承认”需要宾语，如“承认错误”，这里“只能承认”后面没有内容。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”需要数据或公式，盒子里装的是什么无法通过计算得出。"}, {"text": "猜测", "is_correct": true, "explanation": "“猜测”指不知道答案时自己想一个说出来，正好对应“不知道盒子里装的是什么”的情境。"}, {"text": "讲述", "is_correct": false, "explanation": "配价：“讲述”需要有所讲述的内容作宾语，这里找不到对象，句子不成立。"}], "explanations": {"承认": "配价：“承认”需要宾语，如“承认错误”，这里“只能承认”后面没有内容。", "计算": "语义：“计算”需要数据或公式，盒子里装的是什么无法通过计算得出。", "猜测": "“猜测”指不知道答案时自己想一个说出来，正好对应“不知道盒子里装的是什么”的情境。", "讲述": "配价：“讲述”需要有所讲述的内容作宾语，这里找不到对象，句子不成立。"}, "sentence_index": 0, "correct_answer": "猜测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把答案写在黑板上了，我还在猜测它。", "explanation": "猜测用于不知道答案的情况。答案已经写在黑板上，应直接看，不能说猜测它。"}, {"text": "这道题有现成的公式，我用公式猜测出了答案。", "explanation": "这里应该用〈计算〉。有公式可以推算时要用计算，猜测不能用来描述依据公式得出的答案。"}, {"text": "这个礼物是我亲手买的，我却猜测它是什么。", "explanation": "猜测用于不知道答案的情况。礼物是我自己买的，我早就知道是什么，不能说猜测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撕掉", "is_correct": false, "explanation": "语义：“撕掉”会毁坏卡片，与根据提示猜词的游戏目的不相符。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”用于作业、试卷，不用于卡片上的词。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指彻底毁坏，与根据提示找词的游戏规则无关。"}, {"text": "猜测", "is_correct": true, "explanation": "“猜测”指根据线索猜出答案，符合游戏里根据提示猜词的情境。"}], "explanations": {"撕掉": "语义：“撕掉”会毁坏卡片，与根据提示猜词的游戏目的不相符。", "批改": "搭配：“批改”用于作业、试卷，不用于卡片上的词。", "烧毁": "语义：“烧毁”指彻底毁坏，与根据提示找词的游戏规则无关。", "猜测": "“猜测”指根据线索猜出答案，符合游戏里根据提示猜词的情境。"}, "sentence_index": 6, "correct_answer": "猜测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务台可以猜测列车的时刻。", "explanation": "这里应该用〈查询〉。列车时刻是可以查到的信息，猜测是没有依据的推想，不能用来代替查询。"}, {"text": "我今年二十岁，我猜测自己的年龄是二十岁。", "explanation": "猜测用于不知道答案的情况。自己的年龄是确定知道的，不能说猜测。"}, {"text": "这首诗是我亲手写的，我却猜测它的作者。", "explanation": "这里应该用〈知道〉。猜测用于不知道答案的推想，这首诗是我自己写的，应说我知道它的作者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题的答案我猜测很准。", "corrected_sentence": "这道题的答案我猜测得很准。", "error_description": "错误：“猜测”后面带程度补语时漏掉了“得”。正确：“猜测得很准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有线索，只能把常识猜测。", "corrected_sentence": "我没有线索，只能根据常识猜测。", "error_description": "错误：“把常识猜测”用了“把”字句，但“猜测”后面没有补语，句子不完整。正确：用“根据”引出依据，说“根据常识猜测”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有确切根据地推想。", "primary_collocate": null, "pronunciation": "cāi cè", "ipa": "tsʰai˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都在猜测他为什么没来。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有证据，我们只能猜测。", "target_word": "猜测", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警方猜测小偷是从窗户进来的。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者猜测这家公司会涨价。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不说话，我只能猜测她不高兴。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别乱猜测别人的想法。", "target_word": "猜测", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家猜测，明年天气会比今年冷。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没回信息，我猜测他在开会。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生没看到病人，不敢随便猜测病因。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到地上的水，他猜测楼上漏水了。", "target_word": "猜测", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "猜测了", "label": "完成体"}, {"form": "猜测过", "label": "经历体"}, {"form": "猜测着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "缺少证据时对原因或结果作出推想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保证", "is_correct": false, "explanation": "语义：“保证”指担保将来会发生的事，不能用来推想已经发生的原因。"}, {"text": "猜测", "is_correct": true, "explanation": "“猜测”表示没有确切根据地推想，符合“大家都在……他为什么没来”的语境。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，后面不能直接接“他为什么没来”这样的从句作宾语。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”针对主张或行为，“反对他为什么没来”说不通。"}], "explanations": {"保证": "语义：“保证”指担保将来会发生的事，不能用来推想已经发生的原因。", "猜测": "“猜测”表示没有确切根据地推想，符合“大家都在……他为什么没来”的语境。", "发生": "配价：“发生”是不及物动词，后面不能直接接“他为什么没来”这样的从句作宾语。", "反对": "语义：“反对”针对主张或行为，“反对他为什么没来”说不通。"}, "sentence_index": 0, "correct_answer": "猜测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用实验猜测了酸能腐蚀金属。", "explanation": "这里应该用〈证明〉。猜测指没有根据的推想，用实验得出的结论要用证明。"}, {"text": "根据人口普查，政府猜测城市人口已超过一千万。", "explanation": "这里应该用〈估计〉。人口数据来自普查，有依据的估算要用估计，猜测强调没有根据。"}, {"text": "这个数学定理早已被证明，我们只是在猜测它。", "explanation": "这里应该用〈研究〉。猜测指没有根据的推想，定理已被证明、结论确定，应说我们只是在研究它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "配价：“批评”需要被批评的对象作宾语，这里没有，逗号后的句子接不上。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去的事，不能用来推断明年的天气。"}, {"text": "猜测", "is_correct": true, "explanation": "“猜测”表示没有证据的推想，“专家猜测”后接对未来天气的判断，语境契合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除灰尘垃圾，不能引出对天气的判断。"}], "explanations": {"批评": "配价：“批评”需要被批评的对象作宾语，这里没有，逗号后的句子接不上。", "回忆": "语义：“回忆”指想起过去的事，不能用来推断明年的天气。", "猜测": "“猜测”表示没有证据的推想，“专家猜测”后接对未来天气的判断，语境契合。", "打扫": "语义：“打扫”指清除灰尘垃圾，不能引出对天气的判断。"}, "sentence_index": 6, "correct_answer": "猜测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物业经过检查，已经猜测楼上漏水了。", "explanation": "这里应该用〈确认〉。检查已经有结果，猜测是没有依据的推想，不能用于查证之后的结论。"}, {"text": "他亲眼猜测楼上漏水了。", "explanation": "这里应该用〈看到〉。猜测是没有根据的推想，这句说的是亲自看见，应说他看到楼上漏水了。"}, {"text": "我亲手关的门，我猜测门是关着的。", "explanation": "猜测是没有根据的推想。门是我亲手关的，有确切依据，应说我知道门是关着的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次都猜测很准。", "corrected_sentence": "他每次都猜测得很准。", "error_description": "错误：补语标记“得”漏掉，“猜测很准”不成立。正确：“猜测得很准”。动词后面带程度补语时要用“得”引出，“很”不能直接跟在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天没来，我很猜测他可能是生病了。", "corrected_sentence": "他今天没来，我猜测他可能是生病了。", "error_description": "错误：在动词“猜测”前加了程度副词“很”，“很猜测”不成立。正确：去掉“很”，直接说“我猜测”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "苦", "is_correct": true, "explanation": "反义：苦与甜是味觉上相对的一对，指吃起来的味道相反。"}, {"text": "软", "is_correct": false, "explanation": "与甜无关：“软”说的是质地，不是味道。"}, {"text": "冷", "is_correct": false, "explanation": "与甜无关：“冷”说的是温度，不是味道。"}, {"text": "远", "is_correct": false, "explanation": "与甜无关：“远”说的是距离，与味道无关。"}], "correct_answer": "苦", "explanations": {"苦": "反义：苦与甜是味觉上相对的一对，指吃起来的味道相反。", "软": "与甜无关：“软”说的是质地，不是味道。", "冷": "与甜无关：“冷”说的是温度，不是味道。", "远": "与甜无关：“远”说的是距离，与味道无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "苦", "is_correct": true, "explanation": "反义：苦与甜是味觉上相对的一对，指吃起来的味道相反。"}, {"text": "高", "is_correct": false, "explanation": "与甜无关：“高”说的是高度，不是味道。"}, {"text": "深", "is_correct": false, "explanation": "与甜无关：“深”说的是深浅，与味道无关。"}, {"text": "快", "is_correct": false, "explanation": "与甜无关：“快”说的是速度，与味道无关。"}], "correct_answer": "苦", "explanations": {"苦": "反义：苦与甜是味觉上相对的一对，指吃起来的味道相反。", "高": "与甜无关：“高”说的是高度，不是味道。", "深": "与甜无关：“深”说的是深浅，与味道无关。", "快": "与甜无关：“快”说的是速度，与味道无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像糖和蜂蜜一样，吃起来让人觉得好吃的味道。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这个西瓜很甜，我吃了两块。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜比白糖还要甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的红薯又软又甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种苹果一点儿也不甜，有点酸。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱吃甜的东西。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我一杯放了很多糖的咖啡，太甜了。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的葡萄特别甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕不太甜，我很喜欢。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尝尝这个橙子甜不甜？", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的草莓又大又红，吃起来很甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "甜甜", "label": "重叠"}, {"form": "甜味", "label": "复合"}, {"form": "甜食", "label": "复合"}], "register": "中性", "sense_fingerprint": "味觉：像糖和蜂蜜的好味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甜", "is_correct": true, "explanation": "甜（tián）：像糖和蜂蜜一样，吃起来让人觉得好吃。"}, {"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是“天空”。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}, {"text": "添", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是“添加”。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tián 韵母不同（an 与 ian），意思是“谈话”。"}], "explanations": {"甜": "甜（tián）：像糖和蜂蜜一样，吃起来让人觉得好吃。", "天": "tiān（第一声）与 tián（第二声）声调不同，意思是“天空”。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。", "添": "tiān（第一声）与 tián（第二声）声调不同，意思是“添加”。", "谈": "tán 与 tián 韵母不同（an 与 ian），意思是“谈话”。"}, "sentence_index": null, "correct_answer": "甜"}, "level_3": {"options": [{"text": "臭", "is_correct": false, "explanation": "语义：“臭”指气味难闻，与“吃了两块”的情境矛盾。"}, {"text": "甜", "is_correct": true, "explanation": "甜：描述西瓜像糖一样的好味道，与“很”搭配，也与“吃了两块”一致。"}, {"text": "脏", "is_correct": false, "explanation": "语义：“脏”指不干净，不能用来形容吃了两块的西瓜。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不能用来形容西瓜的味道。"}], "explanations": {"臭": "语义：“臭”指气味难闻，与“吃了两块”的情境矛盾。", "甜": "甜：描述西瓜像糖一样的好味道，与“很”搭配，也与“吃了两块”一致。", "脏": "语义：“脏”指不干净，不能用来形容吃了两块的西瓜。", "吵": "搭配：“吵”形容声音，不能用来形容西瓜的味道。"}, "sentence_index": 0, "correct_answer": "甜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份方案很甜，大家都很满意。", "explanation": "这里应该用〈好〉。甜只形容食物的味道，形容方案的质量不能用“甜”。"}, {"text": "这次考试我考得很甜。", "explanation": "这里应该用〈理想〉。甜只形容食物的味道，形容考试成绩好要用〈理想〉。"}, {"text": "这台电脑很甜，开机不卡。", "explanation": "这里应该用〈流畅〉。甜只形容食物的味道，形容电脑运行顺畅要用〈流畅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甜", "is_correct": true, "explanation": "甜（tián）：像糖和蜂蜜一样，吃起来让人觉得好吃。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 tián（第二声）声母不同（q 与 t），意思是钱。"}, {"text": "眠", "is_correct": false, "explanation": "mián（第二声）与 tián（第二声）声母不同（m 与 t），意思是睡眠。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}], "explanations": {"甜": "甜（tián）：像糖和蜂蜜一样，吃起来让人觉得好吃。", "钱": "qián（第二声）与 tián（第二声）声母不同（q 与 t），意思是钱。", "眠": "mián（第二声）与 tián（第二声）声母不同（m 与 t），意思是睡眠。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}, "sentence_index": null, "correct_answer": "甜"}, "level_3": {"options": [{"text": "慢", "is_correct": false, "explanation": "语义：“慢”指速度，与葡萄的特征无关。"}, {"text": "甜", "is_correct": true, "explanation": "甜：描述葡萄的好味道，与“特别”搭配，句意完整。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度，不适用于描述葡萄的味道。"}, {"text": "窄", "is_correct": false, "explanation": "体貌：“窄”形容宽度，不能用来形容葡萄。"}], "explanations": {"慢": "语义：“慢”指速度，与葡萄的特征无关。", "甜": "甜：描述葡萄的好味道，与“特别”搭配，句意完整。", "矮": "体貌：“矮”形容高度，不适用于描述葡萄的味道。", "窄": "体貌：“窄”形容宽度，不能用来形容葡萄。"}, "sentence_index": 6, "correct_answer": "甜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很甜，敲起来很响。", "explanation": "这里应该用〈硬〉。甜只形容食物的味道，形容石头的质地要用〈硬〉。"}, {"text": "这个房间很甜，阳光充足，很舒服。", "explanation": "这里应该用〈明亮〉。甜只形容食物的味道，形容房间的光线要用〈明亮〉。"}, {"text": "这条路很甜，一直通到山顶。", "explanation": "这里应该用〈长〉。甜只形容食物的味道，形容路的长短要用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXC