INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢吃甜地点心。", "corrected_sentence": "我喜欢吃甜的点心。", "error_description": "错误形式：“甜地点心”；正确形式：“甜的点心”。“甜”修饰名词“点心”，应用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
