INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像糖或蜜的味道。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这杯奶茶太甜了，我喝不完。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月饼里的豆沙很甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢甜的饮料，只喝茶。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里放了太多糖，有点儿甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蜜柑甜得像糖一样。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人爱吃咸的，南方人爱吃甜的。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我不能吃太甜的东西。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗粥一点都不甜，再加点糖吧。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的烤栗子又香又甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢喝不加糖的咖啡，不喜欢太甜。", "target_word": "甜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "甜甜", "label": "重叠"}, {"form": "甜味", "label": "复合"}, {"form": "甜食", "label": "复合"}], "register": "中性", "sense_fingerprint": "味觉：食物饮料像糖或蜜的味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甜", "is_correct": true, "explanation": "甜（tián）：像糖或蜜的味道。"}, {"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是“天空”。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}, {"text": "添", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是“添加”。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tián 韵母不同（an 与 ian），意思是“谈话”。"}], "explanations": {"甜": "甜（tián）：像糖或蜜的味道。", "天": "tiān（第一声）与 tián（第二声）声调不同，意思是“天空”。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。", "添": "tiān（第一声）与 tián（第二声）声调不同，意思是“添加”。", "谈": "tán 与 tián 韵母不同（an 与 ian），意思是“谈话”。"}, "sentence_index": null, "correct_answer": "甜"}, "level_3": {"options": [{"text": "窄", "is_correct": false, "explanation": "体貌：“窄”形容宽度，不能用来形容奶茶。"}, {"text": "甜", "is_correct": true, "explanation": "甜：描述奶茶像糖一样的味道，与“太”和“喝不完”的语境一致。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度，不能用来形容奶茶。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不能用来形容饮料的味道。"}], "explanations": {"窄": "体貌：“窄”形容宽度，不能用来形容奶茶。", "甜": "甜：描述奶茶像糖一样的味道，与“太”和“喝不完”的语境一致。", "矮": "体貌：“矮”形容高度，不能用来形容奶茶。", "吵": "搭配：“吵”形容声音，不能用来形容饮料的味道。"}, "sentence_index": 0, "correct_answer": "甜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同很甜，签字前请再看看。", "explanation": "这里应该用〈清楚〉。甜只形容食物的味道，形容合同条款明白要用〈清楚〉。"}, {"text": "这次出差很甜，每天都很忙。", "explanation": "这里应该用〈辛苦〉。甜只形容食物的味道，形容出差的劳累要用〈辛苦〉。"}, {"text": "这把伞很甜，撑起来很稳。", "explanation": "这里应该用〈结实〉。甜只形容食物的味道，形容伞的牢固要用〈结实〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甜", "is_correct": true, "explanation": "甜（tián）：像糖或蜜的味道。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 tián（第二声）声母不同（q 与 t），意思是钱。"}, {"text": "眠", "is_correct": false, "explanation": "mián（第二声）与 tián（第二声）声母不同（m 与 t），意思是睡眠。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}], "explanations": {"甜": "甜（tián）：像糖或蜜的味道。", "钱": "qián（第二声）与 tián（第二声）声母不同（q 与 t），意思是钱。", "眠": "mián（第二声）与 tián（第二声）声母不同（m 与 t），意思是睡眠。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，意思是“用舌头接触”。"}, "sentence_index": null, "correct_answer": "甜"}, "level_3": {"options": [{"text": "快", "is_correct": false, "explanation": "语义：“快”指速度，吃东西的时候不能用来形容东西的特征。"}, {"text": "甜", "is_correct": true, "explanation": "甜：描述食物的味道，与“医生说不能吃太……的东西”的语境相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容高度，不能用来形容食物。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，与饮食的禁忌无关。"}], "explanations": {"快": "语义：“快”指速度，吃东西的时候不能用来形容东西的特征。", "甜": "甜：描述食物的味道，与“医生说不能吃太……的东西”的语境相符。", "高": "体貌：“高”形容高度，不能用来形容食物。", "亮": "语义：“亮”指光线明亮，与饮食的禁忌无关。"}, "sentence_index": 6, "correct_answer": "甜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板很甜，摸上去一点也不扎手。", "explanation": "这里应该用〈光滑〉。甜只形容食物的味道，形容木板表面平滑要用〈光滑〉。"}, {"text": "这间屋子很甜，天花板很高。", "explanation": "这里应该用〈宽敞〉。甜只形容食物的味道，形容房间的空间大要用〈宽敞〉。"}, {"text": "这份报告很甜，内容很丰富。", "explanation": "这里应该用〈详细〉。甜只形容食物的味道，形容报告内容周全要用〈详细〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯奶茶甜地发腻。", "corrected_sentence": "这杯奶茶甜得发腻。", "error_description": "错误形式：“甜地发腻”；正确形式：“甜得发腻”。表示程度的补语要用“得”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不喜欢太甜地饮料。", "corrected_sentence": "我不喜欢太甜的饮料。", "error_description": "错误形式：“太甜地饮料”；正确形式：“太甜的饮料”。“甜”修饰名词“饮料”，应用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
