INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物留下的印迹。", "primary_collocate": null, "pronunciation": "hén jì", "ipa": "xən˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老房子上有时间留下的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市到处都是历史的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脸上没有一点哭过的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争在这个村子里留下了痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话时，还带着南方口音的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本旧书里有很多岁月的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里没有人住过的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活的痕迹留在每一件旧家具上。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有找到他来过的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老街上还能看到过去的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一些痕迹", "label": "量词"}, {"form": "痕跡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "痕迹：时间、历史、事件或人活动后留下的印迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：痕迹（hén jì）指事物或时间留下的印迹。"}, {"text": "人际", "is_correct": false, "explanation": "rén（第二声）与 hén（第二声）声母不同，意思是人与人之间的关系。"}, {"text": "寒季", "is_correct": false, "explanation": "hán（第二声）与 hén 韵母不同（an 与 en），意思是寒冷的季节。"}, {"text": "很挤", "is_correct": false, "explanation": "hěn（第三声）与 hén（第二声）声调不同，jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。"}, {"text": "很急", "is_correct": false, "explanation": "hěn（第三声）与 hén 声调不同，jí（第二声）与 jì（第四声）声调不同，意思是非常着急。"}], "explanations": {"痕迹": "正确：痕迹（hén jì）指事物或时间留下的印迹。", "人际": "rén（第二声）与 hén（第二声）声母不同，意思是人与人之间的关系。", "寒季": "hán（第二声）与 hén 韵母不同（an 与 en），意思是寒冷的季节。", "很挤": "hěn（第三声）与 hén（第二声）声调不同，jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。", "很急": "hěn（第三声）与 hén 声调不同，jí（第二声）与 jì（第四声）声调不同，意思是非常着急。"}, "sentence_index": null, "correct_answer": "痕迹"}, "level_3": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：痕迹指时间留下的印迹，与“留下”搭配。"}, {"text": "价格", "is_correct": false, "explanation": "语义：时间能留下的是印迹，价格不是时间留在房子上的东西。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性情，不会由时间留在房子上。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“留下”的对象应是印迹，“年纪”只说增长，不说留下。"}], "explanations": {"痕迹": "正确：痕迹指时间留下的印迹，与“留下”搭配。", "价格": "语义：时间能留下的是印迹，价格不是时间留在房子上的东西。", "脾气": "语义：脾气是人的性情，不会由时间留在房子上。", "年纪": "搭配：“留下”的对象应是印迹，“年纪”只说增长，不说留下。"}, "sentence_index": 0, "correct_answer": "痕迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市有一只历史的痕迹。", "explanation": "这里应该用〈些〉。这种抽象的痕迹常说“一些”“一丝”，“只”一般用于动物。"}, {"text": "他心里有一个很好的痕迹，想先和大家讨论。", "explanation": "这里应该用〈想法〉。痕迹指事物留下的印迹，不能用来表示人心里的念头。"}, {"text": "这次改革取得了很大的痕迹，大家都很满意。", "explanation": "这里应该用〈成绩〉。痕迹指事物留下的印迹，不能用来指取得的成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：“没有人住过的痕迹”指没有人居住过留下的印迹。"}, {"text": "房租", "is_correct": false, "explanation": "语义：房租是付给房东的钱，与“没有人住过”的印迹无关。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：屋里没有人住过，就不可能留下欢笑的印迹。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：体型指人的身材，说屋里“没有人住过的体型”不成立。"}], "explanations": {"痕迹": "正确：“没有人住过的痕迹”指没有人居住过留下的印迹。", "房租": "语义：房租是付给房东的钱，与“没有人住过”的印迹无关。", "欢笑": "语义：屋里没有人住过，就不可能留下欢笑的印迹。", "体型": "体貌：体型指人的身材，说屋里“没有人住过的体型”不成立。"}, "sentence_index": 6, "correct_answer": "痕迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于定下了一个可行的痕迹，大家都很高兴。", "explanation": "这里应该用〈计划〉。痕迹指东西留下的印迹，不能用来指事先定好的方案。"}, {"text": "他从小就有一个远大的痕迹。", "explanation": "这里应该用〈理想〉。痕迹不能用来指人对未来的追求。"}, {"text": "老街上有一颗历史的痕迹。", "explanation": "这里应该用〈些〉。这种抽象的痕迹常说“一些”“一丝”，“颗”用于小而圆的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市里留下了一丝历史地痕迹。", "corrected_sentence": "这座城市里留下了一丝历史的痕迹。", "error_description": "“历史”修饰名词“痕迹”，应用“的”；“地”用于修饰动词，写成“历史地痕迹”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老街上还留着一只过去的痕迹。", "corrected_sentence": "老街上还留着一丝过去的痕迹。", "error_description": "“痕迹”应搭配“一丝”“一点”等量词，“只”一般用于动物或成对的东西，不能计量这种印迹。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
