INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公开发布新作品、新成果或新产品的会议。", "primary_collocate": null, "pronunciation": "fā biǎo huì", "ipa": "fa˥ pjɑʊ̯˨˩˦ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "公司明天下午开新产品发表会。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的新书发表会在书店举行。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天参加了一场手机发表会。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发表会上，经理介绍了新产品。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所开了一次研究成果发表会。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去看那位歌手的新专辑发表会。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次发表会请了很多记者来参加。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发表会结束后，大家都在讨论新手机。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为新车发表会准备了一个月。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发表会的入场券很难买到。", "target_word": "发表会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "新品发表会", "label": "复合"}], "register": "正式", "sense_fingerprint": "公司或机构公开发布新产品、新书、新成果的正式会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发表会", "is_correct": true, "explanation": "正确。“发表会”指公开发布新产品的会议，与“开新产品”相符。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“开”不搭配“生日”，应说“过生日”。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼与新产品发布无关，句子不成立。"}, {"text": "旅游", "is_correct": false, "explanation": "搭配：“开”不搭配“旅游”，应说“去旅游”。"}], "explanations": {"发表会": "正确。“发表会”指公开发布新产品的会议，与“开新产品”相符。", "生日": "搭配：“开”不搭配“生日”，应说“过生日”。", "葬礼": "语义：葬礼与新产品发布无关，句子不成立。", "旅游": "搭配：“开”不搭配“旅游”，应说“去旅游”。"}, "sentence_index": 0, "correct_answer": "发表会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校每年都开发表会，帮毕业生找工作。", "explanation": "这里应该用〈招聘会〉。帮毕业生找工作的是招聘会；发表会是公开发布新作品或新产品的会议，不用于找工作。"}, {"text": "发表会上，大家默哀了三分钟。", "explanation": "这里应该用〈追悼会〉。默哀是追悼会的内容；发表会是公开发布新作品或新产品的会议，不用于悼念。"}, {"text": "公司把新产品的发表会装进了箱子里。", "explanation": "这里的“发表会”被当成了“物品”的意思，发表会是聚会活动，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发表会", "is_correct": true, "explanation": "正确。“发表会”是正式的新品发布活动，记者来参加符合语境。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不会邀请记者来参加，句中指正式的发布活动。"}, {"text": "体检", "is_correct": false, "explanation": "语义：体检不会请记者来参加，与发布活动无关。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“参加”不搭配“作业”，句中指公开的发布活动。"}], "explanations": {"发表会": "正确。“发表会”是正式的新品发布活动，记者来参加符合语境。", "考试": "语义：考试不会邀请记者来参加，句中指正式的发布活动。", "体检": "语义：体检不会请记者来参加，与发布活动无关。", "作业": "搭配：“参加”不搭配“作业”，句中指公开的发布活动。"}, "sentence_index": 6, "correct_answer": "发表会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的发表会很便宜，一顿饭只要十块。", "explanation": "这里的“发表会”被当成了“优惠促销”的意思，发表会只指公开发布新产品的会议，不能用来说饭的价格。"}, {"text": "发表会上，新郎新娘向大家敬酒。", "explanation": "这里应该用〈婚礼〉。向宾客敬酒是婚礼的场景；发表会是公开发布新产品的会议，不用于婚礼。"}, {"text": "学校发表会上，同学们跑得很快。", "explanation": "这里应该用〈运动会〉。赛跑是运动会的内容；发表会是公开发布新作品或新产品的会议，不用于体育比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司下个月要办一本新车发表会。", "corrected_sentence": "公司下个月要办一场新车发表会。", "error_description": "错误形式：“一本新车发表会”；正确形式：“一场新车发表会”。发表会是活动，应该用量词“场”，“本”用于书等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家明天要打新书发表会。", "corrected_sentence": "这位作家明天要开新书发表会。", "error_description": "错误形式：“打新书发表会”；正确形式：“开新书发表会”。发表会是会议，要说“开”或“举行”，不能说“打”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
