INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛对着一个东西，准备打到它。", "primary_collocate": null, "pronunciation": "miáo zhǔn", "ipa": "mjɑʊ̯˧˥ ʈʂwən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他闭上一只眼睛，瞄准了远处的靶子。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明瞄准垃圾桶，把纸团扔了过去。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先瞄准红点，再扔飞镖。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他瞄准树上的苹果，扔出一块石头。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子瞄准雪人的头，扔了一个雪球。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瞄准了就扔，别想太久。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她瞄准了很久，才把球投出去。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我瞄准那个杯子，用小球打它。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边瞄准篮筐，一边慢慢呼吸。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你瞄准一点儿，别扔偏了。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞄准了", "label": "体标"}, {"form": "瞄准着", "label": "体标"}, {"form": "瞄准过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用眼睛盯住东西，准备扔或打中它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞄准", "is_correct": true, "explanation": "符合句意：闭上一只眼睛后对准远处的靶子，准备射击。"}, {"text": "睁开", "is_correct": false, "explanation": "配价：睁开的宾语应是眼睛，不能接“靶子”；且与前半句“闭上一只眼睛”相反。"}, {"text": "捡起", "is_correct": false, "explanation": "语义：靶子在远处，不能“捡起”，与“远处的”矛盾。"}, {"text": "摸", "is_correct": false, "explanation": "语义：远处的靶子够不到，不能用手“摸”，与“远处的”矛盾。"}], "explanations": {"瞄准": "符合句意：闭上一只眼睛后对准远处的靶子，准备射击。", "睁开": "配价：睁开的宾语应是眼睛，不能接“靶子”；且与前半句“闭上一只眼睛”相反。", "捡起": "语义：靶子在远处，不能“捡起”，与“远处的”矛盾。", "摸": "语义：远处的靶子够不到，不能用手“摸”，与“远处的”矛盾。"}, "sentence_index": 0, "correct_answer": "瞄准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他瞄准了路边的水坑，小心地绕了过去。", "explanation": "这里应该用〈避开〉。瞄准是为了击中目标，绕过水坑是躲开它，意思正相反。"}, {"text": "他把书瞄准书架的空位，整理得很整齐。", "explanation": "这里应该用〈放〉。瞄准指要击中目标，把书放进书架不需要瞄准。"}, {"text": "他瞄准了窗外的月亮，轻轻叹了一口气。", "explanation": "这里应该用〈望〉。瞄准是为了击中目标，望着月亮叹气不需要瞄准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞄准", "is_correct": true, "explanation": "符合句意：她长时间对准目标，然后才把球投出去。"}, {"text": "捡起", "is_correct": false, "explanation": "搭配：“捡起”是一次性动作，不能与“很久”搭配。"}, {"text": "放下", "is_correct": false, "explanation": "搭配：“放下”是一次性动作，不能与“很久”搭配；放下了球也无法再投出去。"}, {"text": "接住", "is_correct": false, "explanation": "搭配：“接住”是瞬间动作，不能说“接住了很久”。"}], "explanations": {"瞄准": "符合句意：她长时间对准目标，然后才把球投出去。", "捡起": "搭配：“捡起”是一次性动作，不能与“很久”搭配。", "放下": "搭配：“放下”是一次性动作，不能与“很久”搭配；放下了球也无法再投出去。", "接住": "搭配：“接住”是瞬间动作，不能说“接住了很久”。"}, "sentence_index": 6, "correct_answer": "瞄准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仔细瞄准那道题，终于想出了答案。", "explanation": "这里应该用〈思考〉。瞄准指对准目标以打中它，解题不需要瞄准。"}, {"text": "我们站在画前瞄准那幅画，看了很久。", "explanation": "这里应该用〈欣赏〉。瞄准是为了击中目标，欣赏画作不用瞄准。"}, {"text": "他瞄准桌上的茶杯，轻轻喝了一口。", "explanation": "这里应该用〈端〉。瞄准是为了打中目标，端起杯子喝水不需要瞄准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她先瞄准到那只远处的鸟，再扔出石头。", "corrected_sentence": "她先瞄准那只远处的鸟，再扔出石头。", "error_description": "错误：“瞄准”后多加了结果补语“到”。正确：“瞄准”是动作，后面直接接宾语，应说“先瞄准那只远处的鸟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直瞄准了着那个目标，不敢眨眼。", "corrected_sentence": "我一直瞄准着那个目标，不敢眨眼。", "error_description": "错误：“瞄准”后面同时出现了“了”和“着”。正确：表示动作正在进行时只用“着”，应去掉“了”，即“瞄准着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
