INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96428, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "射击或投掷时把枪口等对准目标。", "primary_collocate": null, "pronunciation": "miáo zhǔn", "ipa": "mjɑʊ̯˧˥ ʈʂwən˨˩˦", "syllable_count": 2, "sentences": [{"text": "士兵举起枪，瞄准了前面的目标。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人瞄准那只鹿，慢慢扣动扳机。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "射箭时，你要先瞄准再放箭。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用枪瞄准着门口的人。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有瞄准，子弹打偏了。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员瞄准十米外的靶心开枪。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炮手瞄准敌人的车，等着命令。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瞄准的时候，手一定要稳。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用弓瞄准了远处的靶子。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练教我们怎么瞄准目标。", "target_word": "瞄准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞄准了", "label": "体标"}, {"form": "瞄准着", "label": "体标"}, {"form": "瞄准过", "label": "体标"}], "register": "中性", "sense_fingerprint": "射击、射箭时让枪口或箭对准目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞄准", "is_correct": true, "explanation": "符合句意：士兵举枪对准前方目标，准备射击。"}, {"text": "放下", "is_correct": false, "explanation": "语义：前半句说“举起枪”，“放下”与之矛盾，句意不通。"}, {"text": "闻", "is_correct": false, "explanation": "语义：远处的目标闻不到，“闻了前面的目标”不通。"}, {"text": "盖上", "is_correct": false, "explanation": "配价：“盖上”的宾语应是可以覆盖的东西，不能接“目标”这样的抽象对象。"}], "explanations": {"瞄准": "符合句意：士兵举枪对准前方目标，准备射击。", "放下": "语义：前半句说“举起枪”，“放下”与之矛盾，句意不通。", "闻": "语义：远处的目标闻不到，“闻了前面的目标”不通。", "盖上": "配价：“盖上”的宾语应是可以覆盖的东西，不能接“目标”这样的抽象对象。"}, "sentence_index": 0, "correct_answer": "瞄准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他瞄准面前的菜，慢慢拿起一块鱼。", "explanation": "这里应该用〈夹〉。瞄准是射击或投掷时把枪口等对准目标，夹菜不需要瞄准。"}, {"text": "他瞄准了枪的保险，然后走出门。", "explanation": "这里应该用〈检查〉。瞄准的对象应是要射击的目标，保险不能作为瞄准对象。"}, {"text": "他慢慢瞄准扳机，等待子弹射出。", "explanation": "这里应该用〈扣动〉。瞄准是对准目标，扣动扳机才是射击时的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞄准", "is_correct": true, "explanation": "符合句意：炮手对准敌人的车，等待命令。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的宾语应是人或动物，不能接“车”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能带“敌人的车”这样的宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与对准敌人的车无关，句子不通。"}], "explanations": {"瞄准": "符合句意：炮手对准敌人的车，等待命令。", "喂": "配价：“喂”的宾语应是人或动物，不能接“车”。", "哭": "配价：“哭”不能带“敌人的车”这样的宾语。", "唱": "语义：唱歌与对准敌人的车无关，句子不通。"}, "sentence_index": 6, "correct_answer": "瞄准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶瞄准了远处的白云，轻轻笑了起来。", "explanation": "这里应该用〈望〉。瞄准是为了击中目标，望着白云微笑不需要瞄准。"}, {"text": "他瞄准了桌上的信，拿起来看了一遍。", "explanation": "这里应该用〈拿〉。瞄准是为了击中目标，拿起信件不需要瞄准。"}, {"text": "他仔细瞄准远处的枪声。", "explanation": "这里应该用〈听〉。枪声是听到的，不能被瞄准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很瞄准那只飞过的鸟，然后开了枪。", "corrected_sentence": "他仔细瞄准那只飞过的鸟，然后开了枪。", "error_description": "错误：程度副词“很”不能直接修饰动作动词“瞄准”。正确：应用方式状语，如“仔细瞄准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猎人很瞄准远处的野兔，就开了枪。", "corrected_sentence": "猎人仔细瞄准远处的野兔，就开了枪。", "error_description": "错误：程度副词“很”不能直接修饰动作动词“瞄准”。正确：应用方式状语，如“仔细瞄准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
