INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门从事学术研究的机构。", "primary_collocate": null, "pronunciation": "yán jiū yuàn", "ipa": "jɛn˧˥ tɕjoʊ˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "他在一家研究院工作。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所研究院是五十年前成立的。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院里的专家都很有名。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后去了研究院。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家研究院每年发表很多文章。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多有名的研究院。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院招了十个新人。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的哥哥是研究院的院长。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究院专门研究历史。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院给学生提供了奖学金。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "所", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究院：从事学术研究的正式机构或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究院", "is_correct": true, "explanation": "研究院指专门从事学术研究的机构，可以用“家”计量，与“工作”搭配自然。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林不是工作单位，“一家森林”不通，无法在此工作。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是工作单位，“一家河流”不通，无法在此工作。"}, {"text": "沙滩", "is_correct": false, "explanation": "语义：沙滩不是工作单位，“一家沙滩”不通，不能在此工作。"}], "explanations": {"研究院": "研究院指专门从事学术研究的机构，可以用“家”计量，与“工作”搭配自然。", "森林": "语义：森林不是工作单位，“一家森林”不通，无法在此工作。", "河流": "语义：河流不是工作单位，“一家河流”不通，无法在此工作。", "沙滩": "语义：沙滩不是工作单位，“一家沙滩”不通，不能在此工作。"}, "sentence_index": 0, "correct_answer": "研究院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她大学毕业后当上了研究院。", "explanation": "这里应该用〈研究员〉。研究院是机构，不能当职务；“当上”后接的是人的职业，如“研究员”。"}, {"text": "她大学毕业后成了研究院。", "explanation": "这里应该用〈研究员〉。“成了”后接人的身份或职业，研究院是机构，不能当作人的身份来说。"}, {"text": "她大学毕业后被任命为研究院。", "explanation": "这里应该用〈院长〉。“被任命为”后接职务，研究院是机构而不是职务，应说“院长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究院", "is_correct": true, "explanation": "研究院是有人员的机构，能够招人，与“招了十个新人”搭配。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是单位，不能招人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是单位，不能招人。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是食物，不能招聘新人。"}], "explanations": {"研究院": "研究院是有人员的机构，能够招人，与“招了十个新人”搭配。", "河流": "语义：河流不是单位，不能招人。", "石头": "语义：石头不是单位，不能招人。", "大米": "语义：大米是食物，不能招聘新人。"}, "sentence_index": 6, "correct_answer": "研究院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司附近有一条研究院。", "explanation": "这里应该用〈所〉。研究院是机构，量词用“所”或“家”；“条”用于细长的东西。"}, {"text": "周末我们去看了一把研究院。", "explanation": "这里应该用〈所〉。“把”用于有柄的东西，不能用来计量研究院。"}, {"text": "这座城市里有一朵研究院。", "explanation": "这里应该用〈所〉。“朵”用于花等东西，研究院是机构，不能用“朵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她研究院做了三年实验。", "corrected_sentence": "她在研究院做了三年实验。", "error_description": "“研究院”前面漏了介词“在”。正确说法是“在研究院做实验”，用“在”引出动作发生的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只研究院的实验室很新。", "corrected_sentence": "这所研究院的实验室很新。", "error_description": "量词错误：“研究院”是机构，量词应用“所”，“只”多用于动物，不能用来计量研究院。正确说法是“这所研究院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
