INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "清清楚楚，一点也不错。", "primary_collocate": null, "pronunciation": "què qiè", "ipa": "tɕʰɥɛ˥˩ tɕʰiɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他说不出确切的时间。", "target_word": "确切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没有确切的消息，不能乱说。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议几点开始，请给我一个确切的答复。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察已经知道了确切的地点。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息还不确切，别告诉别人。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事什么时候发生，没人说得确切。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生还没有确切的结论。", "target_word": "确切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请告诉我确切的人数，好订座位。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于他的年龄，没有人知道确切的数字。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上有确切的位置，你一看就懂。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更确切", "label": "比较级"}, {"form": "确切地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "时间、地点、消息等信息清楚而肯定，没有差错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能修饰“时间”。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”形容高度，不能用来修饰“时间”。"}, {"text": "确切", "is_correct": true, "explanation": "“确切”表示清楚、肯定，正好修饰“时间”，符合“说不出……的时间”的语境。"}, {"text": "挺棒", "is_correct": false, "explanation": "语域：“挺棒”是口语化的说法，与句子的中性语域不符，“挺棒的时间”也说不通。"}], "explanations": {"宽敞": "搭配：“宽敞”形容空间，不能修饰“时间”。", "高": "搭配：“高”形容高度，不能用来修饰“时间”。", "确切": "“确切”表示清楚、肯定，正好修饰“时间”，符合“说不出……的时间”的语境。", "挺棒": "语域：“挺棒”是口语化的说法，与句子的中性语域不符，“挺棒的时间”也说不通。"}, "sentence_index": 0, "correct_answer": "确切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我确切的朋友。", "explanation": "这里应该用〈真正〉。“确切”指信息清楚肯定，不能用来修饰朋友这类人际关系，应说真正的朋友。"}, {"text": "这件事的时间还没定，我只能给一个确切的大概。", "explanation": "这里应该用〈估计〉。“确切”表示清楚肯定，不能修饰不确定的说法；时间还没定，只能给出估计。"}, {"text": "妈妈的爱很确切。", "explanation": "这里应该用〈深厚〉。“确切”指信息或说法清楚肯定，不用于形容感情，形容爱应说深厚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味", "is_correct": false, "explanation": "搭配：“美味”形容食物，不能修饰“结论”。"}, {"text": "确切", "is_correct": true, "explanation": "“确切”表示清楚、肯定，符合“还没有确切的结论”的语境。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音或口感，不能修饰“结论”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，与“结论”无关。"}], "explanations": {"美味": "搭配：“美味”形容食物，不能修饰“结论”。", "确切": "“确切”表示清楚、肯定，符合“还没有确切的结论”的语境。", "清脆": "搭配：“清脆”形容声音或口感，不能修饰“结论”。", "沙哑": "语义：“沙哑”形容嗓音，与“结论”无关。"}, "sentence_index": 6, "correct_answer": "确切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "时间还没有定，我先给你一个确切的待定时间。", "explanation": "这里应该用〈大约〉。“确切”指信息清楚肯定，不能修饰尚未定下的时间，只能给出大约的时间。"}, {"text": "他的脚步声很确切。", "explanation": "这里应该用〈清晰〉。“确切”用于消息、数字等信息清楚肯定，不能用来形容脚步声，描述声音应说清晰。"}, {"text": "他的脾气很确切。", "explanation": "这里应该用〈温和〉。“确切”指信息、说法清楚肯定，不用于形容性格或脾气，形容脾气应说温和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们还没有确切地消息。", "corrected_sentence": "我们还没有确切的消息。", "error_description": "错误：“确切”修饰名词“消息”时要用“的”，不能用“地”。正确：“确切的消息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的答复不够的确切，请再核实一下。", "corrected_sentence": "他的答复不够确切，请再核实一下。", "error_description": "错误：“不够”和“确切”之间多插了“的”。正确：“不够确切”，“不够”后直接接形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
