INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96432, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "准确的；真实而恰当的。", "primary_collocate": null, "pronunciation": "què qiè", "ipa": "tɕʰɥɛ˥˩ tɕʰiɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个词用得很确切。", "target_word": "确切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的描述很确切，我一听就懂。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话的翻译不太确切。", "target_word": "确切", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "用“快乐”来形容他，不够确切。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章里的用词很确切。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这个比喻特别确切。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能不能换一个更确切的说法？", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字的意思，字典里解释得很确切。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用确切的语言说明了问题。", "target_word": "确切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个说法很确切，正好说明了他的性格。", "target_word": "确切", "complexity_tier": "T3", "furigana": "què qiè", "sentence_source": "generated"}], "morphological_forms": [{"form": "更确切", "label": "比较级"}, {"form": "确切地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "用词、说法、描述准确而恰当，符合实际", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b063f9c-e8ac-4645-928e-4bf7eaf05846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "搭配：“高”形容高度，不能用来评价用词的好坏。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或物的身形，不能用来评价用词。"}, {"text": "确切", "is_correct": true, "explanation": "“确切”形容用词准确、恰当，符合“这个词用得很……”的语境。"}, {"text": "碎裂", "is_correct": false, "explanation": "语义：“碎裂”形容物体破碎，不能用来评价用词。"}], "explanations": {"高": "搭配：“高”形容高度，不能用来评价用词的好坏。", "瘦": "体貌：“瘦”描写人或物的身形，不能用来评价用词。", "确切": "“确切”形容用词准确、恰当，符合“这个词用得很……”的语境。", "碎裂": "语义：“碎裂”形容物体破碎，不能用来评价用词。"}, "sentence_index": 0, "correct_answer": "确切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很确切。", "explanation": "这里应该用〈稳固〉。“确切”用于说法、描述的准确，不能用来形容椅子，说椅子结实应用稳固。"}, {"text": "现在是确切的时候，我们出发吧。", "explanation": "这里应该用〈恰当〉。“确切”用于说法、描述的准确，表示时机合适要用恰当。"}, {"text": "他的歌声很确切。", "explanation": "这里应该用〈动听〉。“确切”用于评价说法、描述是否准确，不能用来形容歌声，形容歌声应说动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”形容金属的状态，不能用来描述说法。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体的状态，不能用来修饰“说法”。"}, {"text": "确切", "is_correct": true, "explanation": "“确切”形容说法准确，“更确切的说法”符合“能不能换一个……的说法”的语境。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写高度，不能用来形容说法。"}], "explanations": {"生锈": "语义：“生锈”形容金属的状态，不能用来描述说法。", "潮湿": "搭配：“潮湿”形容空气或物体的状态，不能用来修饰“说法”。", "确切": "“确切”形容说法准确，“更确切的说法”符合“能不能换一个……的说法”的语境。", "矮": "体貌：“矮”描写高度，不能用来形容说法。"}, "sentence_index": 6, "correct_answer": "确切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还不能确定他的意思，只能给一个确切的猜测。", "explanation": "这里应该用〈大致〉。“确切”表示准确肯定，不能修饰没有根据的推想，只能给出大致的判断。"}, {"text": "这首歌的节奏很确切。", "explanation": "这里应该用〈平稳〉。“确切”评价的是用词、说法是否准确，不用于描述节奏，描述节奏应说平稳。"}, {"text": "我们班的气氛很确切。", "explanation": "这里应该用〈融洽〉。“确切”用于评价说法、描述是否准确，不能用来形容气氛，形容气氛应说融洽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给了我一个确切地答复，让我放心。", "corrected_sentence": "他给了我一个确切的答复，让我放心。", "error_description": "错误：“确切”修饰名词“答复”时要用“的”，不能用“地”。正确：“确切的答复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418eee91-b0cd-4276-8371-4e48bb53c20c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
