INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96433, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不粗，窄窄的、小小的。", "primary_collocate": null, "pronunciation": "xì", "ipa": "ɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这根绳子很细，不太结实。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的腰很细。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一支细一点儿的笔。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的腿太细了，我穿不进去。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脖子又细又长。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根针比那根细。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝很细，别爬上去。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的沙子很细，踩上去很软。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一条很细的线。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河变得越来越细，最后只剩一点儿水。", "target_word": "细", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "细细", "label": "重叠"}, {"form": "细长", "label": "复合"}, {"form": "細", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西不粗、很窄或颗粒很小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f1f5a2-dc92-4ecd-9fe2-3c47368a221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "细", "is_correct": true, "explanation": "xì（第四声）指条状物不粗、窄窄的、小小的。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是西方。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}], "explanations": {"细": "xì（第四声）指条状物不粗、窄窄的、小小的。", "西": "xī（第一声）与 xì（第四声）声调不同，意思是西方。", "洗": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。", "习": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}, "sentence_index": null, "correct_answer": "细"}, "level_3": {"options": [{"text": "细", "is_correct": true, "explanation": "符合句意：绳子不粗，所以不太结实。"}, {"text": "粗", "is_correct": false, "explanation": "语义：粗绳子一般较结实，与“不太结实”矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容绳子。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，不能描述绳子的粗细或结实程度。"}], "explanations": {"细": "符合句意：绳子不粗，所以不太结实。", "粗": "语义：粗绳子一般较结实，与“不太结实”矛盾。", "甜": "搭配：“甜”形容味道，不能用来形容绳子。", "快": "语义：“快”形容速度，不能描述绳子的粗细或结实程度。"}, "sentence_index": 0, "correct_answer": "细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很细，放得下三张床。", "explanation": "这里应该用〈大〉。细指条状物不粗，房间的大小要用大。"}, {"text": "这个箱子很细，我一个人搬不动。", "explanation": "这里应该用〈重〉。细形容粗细，箱子的轻重要用重。"}, {"text": "今天的太阳很细，大家都戴上了帽子。", "explanation": "这里应该用〈大〉。细形容条状物不粗，形容阳光强要说“太阳很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96433, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "细", "is_correct": true, "explanation": "xì（第四声）指条状物不粗、窄窄的、小小的。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是席位。"}, {"text": "吸", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。"}], "explanations": {"细": "xì（第四声）指条状物不粗、窄窄的、小小的。", "喜": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。", "席": "xí（第二声）与 xì（第四声）声调不同，意思是席位。", "吸": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。"}, "sentence_index": null, "correct_answer": "细"}, "level_3": {"options": [{"text": "细", "is_correct": true, "explanation": "符合句意：树枝很细，所以别爬上去。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，不能用来形容树枝。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容树枝。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容树枝。"}], "explanations": {"细": "符合句意：树枝很细，所以别爬上去。", "香": "搭配：“香”形容气味，不能用来形容树枝。", "甜": "搭配：“甜”形容味道，不能用来形容树枝。", "咸": "搭配：“咸”形容味道，不能用来形容树枝。"}, "sentence_index": 6, "correct_answer": "细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家离学校很细，每天骑车要半小时。", "explanation": "这里应该用〈远〉。细指条状物不粗，距离的远近要用远。"}, {"text": "他跑得很细，第一个到了终点。", "explanation": "这里应该用〈快〉。细不用于描述速度，形容速度要用快。"}, {"text": "他起床很细，每天都比别人先到教室。", "explanation": "这里应该用〈早〉。细形容粗细或窄小，起床的时间早晚要用早，不能用细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根针细很，穿线要小心。", "corrected_sentence": "这根针很细，穿线要小心。", "error_description": "错误：副词“很”放到了“细”之后。正确：程度副词应放在形容词前，即“很细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条绳子太很细了，别用它拉东西。", "corrected_sentence": "这条绳子太细了，别用它拉东西。", "error_description": "错误：“太”和“很”同时修饰“细”，程度副词重复。正确：只用“太”，即“太细了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2ff969-eb7d-41fe-8dbd-c211fc6b1914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
