INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96435, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个部门里管事最大的人。", "primary_collocate": null, "pronunciation": "zǒng jiān", "ipa": "tsʊŋ˨˩˦ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我们部门的总监很忙。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总监让我明天交报告。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们的新总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总监今天开了三个会。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李当了五年总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总监在办公室里等着你。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很喜欢这位总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总监说这个问题要马上解决。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文件交给了总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作很努力，当上了总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "總監", "label": "繁体"}], "register": "中性", "sense_fingerprint": "总监：一个部门里职位最高、管事最大的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总监", "is_correct": true, "explanation": "总监是一个部门里管事最大的人，可以说“很忙”，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不会“很忙”。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不是人，不会“很忙”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不会“很忙”。"}], "explanations": {"总监": "总监是一个部门里管事最大的人，可以说“很忙”，与句意相符。", "窗户": "语义：窗户不是人，不会“很忙”。", "台灯": "语义：台灯不是人，不会“很忙”。", "石头": "语义：石头不是人，不会“很忙”。"}, "sentence_index": 0, "correct_answer": "总监"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的总监今天请了假。", "explanation": "这里应该用〈班长〉。班级的负责人叫班长，“总监”用于企业的高级主管。"}, {"text": "我们连队新来了一位总监。", "explanation": "这里应该用〈连长〉。连队的负责人叫连长，“总监”不用于军队。"}, {"text": "我们村的总监今年换了人。", "explanation": "这里应该用〈村长〉。村里的负责人叫村长，“总监”不用于村庄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总监", "is_correct": true, "explanation": "总监是人，“这位”是对人的敬称，与“很喜欢”搭配自然。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“这位”只用于人，不能修饰“公司”，应说“这家公司”。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“这位”只用于人，不能修饰“窗帘”，应说“这幅窗帘”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不会被说成“这位”，句意不通。"}], "explanations": {"总监": "总监是人，“这位”是对人的敬称，与“很喜欢”搭配自然。", "公司": "搭配：“这位”只用于人，不能修饰“公司”，应说“这家公司”。", "窗帘": "搭配：“这位”只用于人，不能修饰“窗帘”，应说“这幅窗帘”。", "石头": "语义：石头不是人，不会被说成“这位”，句意不通。"}, "sentence_index": 6, "correct_answer": "总监"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司新来了一条总监。", "explanation": "这里应该用〈位〉。“总监”指人，应用“位”；“条”用于细长的东西。"}, {"text": "她是我们部门的一把总监。", "explanation": "这里应该用〈位〉。“把”用于有柄的东西，不能用来计量人。"}, {"text": "这次聚会里有一朵总监。", "explanation": "这里应该用〈位〉。“朵”用于花等东西，不能用来计量总监。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我总监的办公室里等了一会儿。", "corrected_sentence": "我在总监的办公室里等了一会儿。", "error_description": "“总监的办公室里”前面漏了介词“在”。正确说法是“在总监的办公室里等”，地点要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只总监今天很忙。", "corrected_sentence": "这位总监今天很忙。", "error_description": "量词错误：“总监”指人，应用“位”，不能用“只”（“只”多用于动物）。正确说法是“这位总监”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
