INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "企业中负责某一方面全面工作的高级主管。", "primary_collocate": null, "pronunciation": "zǒng jiān", "ipa": "tsʊŋ˨˩˦ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "他是公司的技术总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场总监正在见客人。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当上了财务总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司新来了一位销售总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的创意总监想出了好办法。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人事总监请大家开会。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从经理变成了运营总监。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务总监要看这个月的账。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位市场总监去过很多国家。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品总监和客户谈了一个小时。", "target_word": "总监", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "總監", "label": "繁体"}], "register": "中性", "sense_fingerprint": "总监：企业里负责技术、市场、财务等某一方面的高级主管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总监", "is_correct": true, "explanation": "总监指企业中负责某一方面全面工作的高级主管，“技术总监”搭配自然。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不是企业的高级主管，不能负责公司的技术工作。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：清洁工不负责公司的全面技术工作。"}, {"text": "教授", "is_correct": false, "explanation": "语义：教授是大学里的学术职称，不是企业职务，不说“公司的技术教授”。"}], "explanations": {"总监": "总监指企业中负责某一方面全面工作的高级主管，“技术总监”搭配自然。", "小学生": "语义：小学生不是企业的高级主管，不能负责公司的技术工作。", "清洁工": "语义：清洁工不负责公司的全面技术工作。", "教授": "语义：教授是大学里的学术职称，不是企业职务，不说“公司的技术教授”。"}, "sentence_index": 0, "correct_answer": "总监"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小组的总监负责全组工作。", "explanation": "这里应该用〈组长〉。“总监”指统管一个大方面的高级主管，一个小组的负责人应叫组长。"}, {"text": "我们班的总监负责管理班级。", "explanation": "这里应该用〈班长〉。班级的负责人叫班长，“总监”用于企业的高级主管。"}, {"text": "我们社团的总监负责组织活动。", "explanation": "这里应该用〈社长〉。社团的负责人叫社长，“总监”不用于社团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总监", "is_correct": true, "explanation": "总监是企业的高级职务，“从经理变成了”后接职务，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“变成”职务，句意不通。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不能“变成”职务，句意不通。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“运营冠军”不是常用说法，不能与“运营”搭配。"}], "explanations": {"总监": "总监是企业的高级职务，“从经理变成了”后接职务，符合句意。", "石头": "语义：石头不能“变成”职务，句意不通。", "大树": "语义：大树不能“变成”职务，句意不通。", "冠军": "搭配：“运营冠军”不是常用说法，不能与“运营”搭配。"}, "sentence_index": 6, "correct_answer": "总监"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司有一只产品总监，负责全部工作。", "explanation": "这里应该用〈位〉。“总监”指人，应用“位”；“只”多用于动物。"}, {"text": "我们公司有一朵产品总监。", "explanation": "这里应该用〈位〉。“朵”用于花等东西，不能用来计量人。"}, {"text": "这间公司只有一把产品总监。", "explanation": "这里应该用〈位〉。“把”用于有柄的东西，不能用来计量总监。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在技术部门当一只总监。", "corrected_sentence": "他在技术部门当一位总监。", "error_description": "量词错误：“总监”指人，应用“位”，不能用“只”（“只”多用于动物）。正确说法是“当一位总监”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只技术总监每天都很忙。", "corrected_sentence": "这位技术总监每天都很忙。", "error_description": "量词错误：“总监”指人，应用“位”，不能用“只”。正确说法是“这位技术总监”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
