INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96437, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多普通人自己聚起来办的团体。", "primary_collocate": null, "pronunciation": "qún zhòng zǔ zhī", "ipa": "tɕʰyn˧˥ ʈʂʊŋ˥˩ tsu˨˩ ʈʂɨ˥", "syllable_count": 4, "sentences": [{"text": "小区里的邻居们自己办了一个群众组织。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群众组织由爱跑步的人发起。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的老人成立了一个群众组织，每天一起唱歌。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群众组织不收钱，大家都是自愿来的。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了一个帮助流浪猫的群众组织。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个群众组织每个月开一次会。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人加入了这个群众组织，一起打扫公园。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群众组织是居民自己办的，不是政府办的。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办一个群众组织，让大家一起学做饭。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近的群众组织常常帮老人买菜。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "群众组织（名词）：普通人自发聚在一起办的民间团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群众组织", "is_correct": true, "explanation": "群众组织：由普通人自己办的团体，与“邻居们自己办了一个”相符。"}, {"text": "政府机构", "is_correct": false, "explanation": "语义：政府机构由政府设立，与“邻居们自己办”的说法相矛盾。"}, {"text": "跨国公司", "is_correct": false, "explanation": "搭配：跨国公司规模大、需要大量资金，不能和“小区里的邻居们自己办”搭配。"}, {"text": "行政机关", "is_correct": false, "explanation": "语义：“行政机关”是政府设立的机构，与“邻居们自己办”相矛盾。"}], "explanations": {"群众组织": "群众组织：由普通人自己办的团体，与“邻居们自己办了一个”相符。", "政府机构": "语义：政府机构由政府设立，与“邻居们自己办”的说法相矛盾。", "跨国公司": "搭配：跨国公司规模大、需要大量资金，不能和“小区里的邻居们自己办”搭配。", "行政机关": "语义：“行政机关”是政府设立的机构，与“邻居们自己办”相矛盾。"}, "sentence_index": 0, "correct_answer": "群众组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家群众组织今年赚了很多钱。", "explanation": "这里应该用〈公司〉。群众组织是普通人自愿组成的团体，不以赚钱为目的，所以这样说不通。"}, {"text": "这个群众组织每天卖很多面包。", "explanation": "这里应该用〈面包店〉。群众组织是普通人自己办的团体，不是卖东西的商店，这样说不通。"}, {"text": "这家群众组织是政府的一个部门。", "explanation": "这里应该用〈机关〉。群众组织是普通人自己办的团体，不属于政府机关系统，这样用不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群众组织", "is_correct": true, "explanation": "群众组织：由普通民众组成的团体，与“加入了这个……，一起打扫公园”相符。"}, {"text": "航空公司", "is_correct": false, "explanation": "语义：航空公司是经营航运的企业，不是为打扫公园而组织的团体。"}, {"text": "皇家卫队", "is_correct": false, "explanation": "语义：“皇家卫队”是保卫王室的军队，不是年轻人自愿加入、打扫公园的团体。"}, {"text": "研究所", "is_correct": false, "explanation": "语义：研究所以科研为主，与“一起打扫公园”的活动内容不符。"}], "explanations": {"群众组织": "群众组织：由普通民众组成的团体，与“加入了这个……，一起打扫公园”相符。", "航空公司": "语义：航空公司是经营航运的企业，不是为打扫公园而组织的团体。", "皇家卫队": "语义：“皇家卫队”是保卫王室的军队，不是年轻人自愿加入、打扫公园的团体。", "研究所": "语义：研究所以科研为主，与“一起打扫公园”的活动内容不符。"}, "sentence_index": 6, "correct_answer": "群众组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的群众组织今天生病了，需要去医院。", "explanation": "群众组织是团体，不是人，不能像人一样生病。"}, {"text": "这个群众组织长得很高，有一米八。", "explanation": "群众组织是团体，不是人，不能用身高来描述。"}, {"text": "他每天都把群众组织带到学校吃午饭。", "explanation": "群众组织是团体，不是可以随身携带的物品，这样说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个朋友自己办了一位群众组织。", "corrected_sentence": "几个朋友自己办了一个群众组织。", "error_description": "错误：“群众组织”是团体，应该用量词“个”；“位”只用于人，这里应该说“一个群众组织”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个群众组织们经常一起开会。", "corrected_sentence": "这几个群众组织经常一起开会。", "error_description": "错误：“们”只能加在指人的名词后，“群众组织”是团体，不能加“们”，应说“这几个群众组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
