INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由广大普通民众组成的团体，如工会、妇联。", "primary_collocate": null, "pronunciation": "qún zhòng zǔ zhī", "ipa": "tɕʰyn˧˥ ʈʂʊŋ˥˩ tsu˨˩ ʈʂɨ˥", "syllable_count": 4, "sentences": [{"text": "工会是一种群众组织。", "target_word": "群众组织", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妇联是为妇女服务的群众组织。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "共青团也是青年的群众组织。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工会、妇联等群众组织都在这里开会。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群众组织可以帮工人解决工作中的问题。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多群众组织，如工会和妇联。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的工会是工人们的群众组织。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的学生会也属于群众组织。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在一个群众组织里为妇女和孩子工作。", "target_word": "群众组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府常常请群众组织一起讨论新办法。", "target_word": "群众组织", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "群众组织（名词）：工会、妇联等由广大民众组成的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
